window.__EU5_GLOSSARY__ = [{"id": "dominant_upper_class_culture", "zh": "上层阶级优势文化", "en": "Dominant Upper Class Culture", "pillar": "culture", "desc": "【上层阶级】优势文化是一个【国家】里上层阶级【人群】中力量最大的【文化】，这一力量以他们所属【阶层】的自然【政治力量】为基数，受这些人群所在【地点】的【控制力】修正。\n\n因此，占据上层阶级人口最多的文化并不一定是上层阶级优势文化。", "desc_en": "The dominant Upper Class culture is the largest Culture in a Country of all the upper class Pops, scaled by the Control of the Locations they are present in, as well as the innate Political Power of the Estate they belong to.\n\nThis does not necessarily mean that it is the majority."}, {"id": "karma", "zh": "业力", "en": "Karma", "pillar": "culture", "desc": "业力用于反映一个【国家】过去的行动所招致的果报，它在‑100到+100之间浮动。\n当国家的业力处于‑33到+33之间时，该国将从业力中获得奖励。", "desc_en": "Karma is measured on a scale from -100 to +100, and reflects the past deeds of a Country.\nA country will benefit the most when its karma is in balance, between -33 and +33."}, {"id": "state_religion", "zh": "主导宗教", "en": "Primary Religion", "pillar": "culture", "desc": "一个【国家】官方认定的【宗教】。它将启用各种类别的游戏内容和机制，从而带来风格迥异的游戏体验。\n\n信仰主导宗教的【人群】将会拥有更高的【人群满意度】，在条件允许的情况下，非国教人群将缓慢【皈依】主导宗教。\n\n主导宗教对【外交】也有重大影响。主导宗教相同的国家倾向于对彼此抱以更友善的态度。", "desc_en": "The official Religion of a Country. It gives access to different content and mechanics, and may allow for very different playstyles.\n\nPops will have higher Pop Satisfaction if they belong to the Primary Religion, and other Pops will slowly Convert to the Primary Religion under the right conditions.\n\nThe Primary Religion also has great impact on Diplomacy, since brethren Countries tend to see each other in a more favorable light."}, {"id": "primary_or_accepted_culture", "zh": "主流或已接纳文化", "en": "Primary or Accepted Culture", "pillar": "culture", "desc": "这是一个【国家】的【主流文化】或【已接纳文化】。", "desc_en": "This is a Culture that is either a Primary or Accepted Culture in a Country."}, {"id": "primary_culture", "zh": "主流文化", "en": "Primary Culture", "pillar": "culture", "desc": "这是代表一个【国家】身份认同的【文化】。当满足条件时，其他文化的【人群】将被主流文化所【同化】。\n\n主流文化的【语言】决定了【国家】的【通用语言】。\n\n属于一个【国家】主流文化的【人群】能获得25%的pop satisfaction with icon加成。", "desc_en": "This is the Culture that a Country is considered to belong to. Pops of another culture will Assimilate to this when the circumstances are right.\n\nThe Common Language of each Country is determined by the Language of their Primary Culture.\n\nPops belonging to the Primary Culture of a Country will see their pop satisfaction with icon increased by 25%."}, {"id": "yanantin", "zh": "亚南廷", "en": "Yanantin", "pillar": "culture", "desc": "亚南廷代表了两个互补但又对立的实体之间的平衡。按照安第斯文化组【文化】的观念，只有当一个存在——一个男人，黑暗，太阳找到他的互补——一个女人，光明，月亮，并与之联结，和谐才能实现。", "desc_en": "Yanantin represents the balance between two complementary but opposing entities. Following the mindset of the andean group Cultures, harmony can only be achieved when a being, a man, darkness, the Sun, finds its complement and joins it, a woman, light, the Moon."}, {"id": "tithe", "zh": "什一税", "en": "Tithe", "pillar": "culture", "desc": "这是对天主教国家的所有信奉该宗教的【人群】征收的【杜卡特】，会被交给教宗国。对教宗国【好感】为负的国家将拒付什一税。", "desc_en": "This is the amount of Ducats collected from all Pops of the catholic faith in countries following the same faith, and given to the Papacy. Countries with negative Opinion of the Papacy will not pay the tithe."}, {"id": "righteousness", "zh": "仁义", "en": "Righteousness", "pillar": "culture", "desc": "仁义是衡量政府在人们眼中有多遵循儒家的哲学与道德的标准。", "desc_en": "Righteousness is a measure of how the government is perceived to be following the philosophy and morals of Confucianism."}, {"id": "dominant_religion", "zh": "优势宗教", "en": "Dominant Religion", "pillar": "culture", "desc": "优势宗教是在某个【地点】或【国家】中拥有最多信徒【人群】的【宗教】。\n这并不一定意味着它占主导地位。", "desc_en": "The Dominant Religion is the Religion with the most Pops following it in a Location or a Country.\nThis does not necessarily mean that it is the majority."}, {"id": "dominant_culture", "zh": "优势文化", "en": "Dominant Culture", "pillar": "culture", "desc": "优势文化是一个【地点】或一个【国家】内规模最大的【文化】。\n这并不一定意味着它占主导地位。", "desc_en": "The dominant culture is the largest Culture in a Location or a Country.\nThis does not necessarily mean that it is the majority."}, {"id": "dominant_dialect", "zh": "优势方言", "en": "Dominant Dialect", "pillar": "culture", "desc": "优势方言是在某个【地点】中拥有最多【人群】使用的【方言】。\n这并不一定意味着它占主导地位。", "desc_en": "The Dominant Dialect is the Dialect with the most Pops speaking it in a Location.\nThis does not necessarily mean that it is the majority."}, {"id": "dominant_language", "zh": "优势语言", "en": "Dominant Language", "pillar": "culture", "desc": "优势语言是在某个【地点】中使用【人群】最多的【语言】。\n这并不一定意味着它占主导地位。", "desc_en": "The Dominant Language is the Language with the most Pops speaking it in a Location.\nThis does not necessarily mean that it is the majority."}, {"id": "stored_research", "zh": "储备研究力", "en": "Stored Research Progress", "pillar": "culture", "desc": "当没有选择【革新】时会积累研究进度。一旦选择了【革新】，研究力储量将被立刻使用。", "desc_en": "Stored Research Progress is accumulated when there is no Advance selected. Stored Research is instantly applied once Advance is selected."}, {"id": "strength_damage_taken", "zh": "兵力承伤", "en": "Strength Damage Taken", "pillar": "culture", "desc": "该数值会影响单位在【战斗】中受到的伤害。对于【舰船】，是对实际【舰船】的伤害，而对于【军团】，这决定了在战斗中会有多少【人力】死亡。", "desc_en": "This impacts the amount of damage a unit takes in Combat. For Ships, it is the damage to the actual Ship, while for Regiments this determines how much Manpower dies from combat."}, {"id": "strength_damage_done", "zh": "兵力杀伤", "en": "Strength Damage Done", "pillar": "culture", "desc": "该数值影响对敌军造成的总伤害。对于【舰船】，是对实际【舰船】的伤害，而对于【军团】，这决定了在战斗中会杀死多少【人力】。", "desc_en": "This impacts the amount of damage dealt to an enemy. For Ships, this damages the actual Ship, while for Regiments this determines how much Manpower they will kill."}, {"id": "chivalric_order", "zh": "勋贵骑士团", "en": "Chivalric Order", "pillar": "culture", "desc": "勋贵骑士团是由贵族战士组成的排他性兄弟会，致力于践行国家的军事理想。符合条件的角色可以被邀请加入，并获得骑士团的角色修正与增益。只要国家拥有活跃的骑士团且统治者是其成员，国家本身就能获得骑士团的国家修正。", "desc_en": "A Chivalric Order is an exclusive brotherhood of noble warriors dedicated to a country's martial ideals. Eligible characters may be invited to join, receiving the order's character modifiers and bonuses. The country itself gains the order's country modifiers as long as it has an active order and a ruler who is a member."}, {"id": "avatar", "zh": "化身", "en": "Avatar", "pillar": "culture", "desc": "化身是特定的【神】在印度教中可接受的不同外表、显现或肉身。", "desc_en": "Avatars are the different aspects, manifestations, or incarnations that a particular God can take in hindu."}, {"id": "counterespionage", "zh": "反间谍行动", "en": "Counterespionage", "pillar": "culture", "desc": "反间谍行动衡量了一个【国家】在积极阻止【外国】在其境内建立【间谍网】上的能力。", "desc_en": "Counterespionage is how good a Country is to actively stop the build up of Foreign Spy Networks in their country."}, {"id": "discover", "zh": "发现", "en": "Discover", "pillar": "culture", "desc": "【地点】被发现后，【未知之地】会被移除，现在可以在地图上看到并进行互动。", "desc_en": "When a Location is discovered, the Terra Incognita is removed from it, and is now visible and interactable with."}, {"id": "non_accepted_culture", "zh": "受忽视文化", "en": "Ignored Culture", "pillar": "culture", "desc": "【国家】内存在的每种【文化】，如果没有针对它应用任何特定政策——既不是【主流文化】、【已接纳文化】、【相容文化】，也不是【受歧视文化】——都算作受忽视文化。\n\n受忽视文化不会获得满意度加成或惩罚，也没有特殊限制，但除非有特殊【法律】，这类【人群】不能被征召为【陆军征召兵】和【海军征召兵】。", "desc_en": "Every Culture present in a Country for which no specific policy has been applied — neither Primary Culture, Accepted Culture, Tolerated Culture, nor Discriminated Culture — counts as an Ignored Culture.\n\nIgnored Cultures receive no satisfaction bonus or penalty, but their Pops suffer -500% maximum Literacy and may not be raised as Army Levies and Naval Levies without a special Law."}, {"id": "discriminated_culture", "zh": "受歧视文化", "en": "Discriminated Culture", "pillar": "culture", "desc": "被【国家】主动选择予以歧视的【文化】。属于受歧视文化的pops with icon将承受-25%的pop satisfaction with icon惩罚，并且不会向其【国家】或【阶层】贡献任何【政治力量】。他们无法产生新的【角色】，也不能在【内阁】中任职，不能担任【陆军将领】、【海军将领】或【探险家】。\n\n若无特殊【法律】，受歧视文化不得被征召为【陆军征召兵】或【海军征召兵】。", "desc_en": "A Culture that a Country has actively chosen to discriminate against. pops with icon of a Discriminated Culture suffer a large pop satisfaction with icon penalty of -25% and contribute no Political Power to their Country or their Estate. They cannot generate new Characters and may not serve in the Cabinet, as Generals, as Admirals, or as Explorers. They also suffer -1500% maximum Literacy.\n\nDiscriminated Cultures may not be raised as Army Levies and Naval Levies without a special Law."}, {"id": "saint", "zh": "圣人", "en": "Saint", "pillar": "culture", "desc": "圣人是指在基督教【宗教】体系中，因展现非凡圣德的事迹而被认可的【角色】。成为【圣人】需经历【封圣】流程。", "desc_en": "A Saint is a Character that is recognized in a christian Religion by having an extraordinary degree of holiness through their deeds. They process to become a Saint is known as Canonization."}, {"id": "calling", "zh": "圣召", "en": "Calling", "pillar": "culture", "desc": "【宗教骑士团】所遵循的圣召，如祈祷、学术、医疗或战争。圣召将修会导向某些【社会价值观】，并决定其【据点】提供什么。它也会影响骑士团与其所在【国家】的关系：忠诚的修会以其圣召为国家带来利益，而不忠的修会则把同样的使命变成一种负担。详情见religious order loyalty short。", "desc_en": "The vocation a Religious Order devotes itself to, such as prayer, scholarship, healing, or war. A Calling draws the order toward certain Societal Values and decides what its Holdings provide. It also colors the order's dealings with its host Country: a devoted order blesses the realm with its Calling, while one whose devotion has lapsed turns that same Calling into a burden."}, {"id": "holy_site", "zh": "圣地", "en": "Holy Site", "pillar": "culture", "desc": "这代表着一处对特定【宗教】有特殊利益的地点。圣地可以为所在【地点】或其【拥有者】提供各类增益，这些修正按照圣地的【重要性】进行比例调整。", "desc_en": "A place that is of special interest to a particular Religion. A Holy Site may provide various bonuses to the Location or Owner, which are scaled by its Importance."}, {"id": "holy_site_type", "zh": "圣地类型", "en": "Holy Site Type", "pillar": "culture", "desc": "每个【圣地】都属于以下类型之一。\n（详见速查典：holy_site_type）", "desc_en": "Each Holy Site belongs to one of the types below.\n(See ledger: holy_site_type)"}, {"id": "morale_damage_done", "zh": "士气打击", "en": "Morale Damage Done", "pillar": "culture", "desc": "该数值影响了单位在【战斗】中造成的【士气】损伤。", "desc_en": "This impacts the amount of damage dealt to the Morale of an enemy in Combat."}, {"id": "morale_damage_taken", "zh": "士气承伤", "en": "Morale Damage Taken", "pillar": "culture", "desc": "该数值影响了单位在【战斗】中承受的【士气】损伤。", "desc_en": "This impacts the amount of damage to Morale a unit takes in Combat."}, {"id": "foreign_culture", "zh": "外国文化", "en": "Foreign Culture", "pillar": "culture", "desc": "这是在【国家】内部没有任何【人群】的【文化】的【文化地位】。", "desc_en": "This is the Cultural Status of a Culture that has no Pops at all inside the Country."}, {"id": "graphical_culture", "zh": "外观文化", "en": "Graphical Culture", "pillar": "culture", "desc": "用于呈现游戏内图形与视觉效果的主要【文化】。", "desc_en": "The main Culture used for the representation of the in-game graphics and visuals."}, {"id": "foreign_language", "zh": "外语", "en": "Foreign Language", "pillar": "culture", "desc": "对【国家】来说既非【通用语言】也非【礼仪语言】的【语言】就是外语。", "desc_en": "A Language that is neither the Common Language nor the Liturgical Language of a Country will be considered a Foreign Language."}, {"id": "isolated_language", "zh": "孤立语言", "en": "Isolated Language", "pillar": "culture", "desc": "一种【语言】不与其他【语言】共【语族】时会被视为【孤立】语言。", "desc_en": "A Language is Isolated when it does not share a Language Family with other Languages."}, {"id": "religion", "zh": "宗教", "en": "Religion", "pillar": "culture", "desc": "宗教是归属于某一【宗教组】的信仰体系。每个【人】都具有宗教属性并能【皈依】其他宗教，每个【国家】都有【主导宗教】。\n\n同一【宗教组】下的不同宗教视彼此为【异端】，而不同【宗教组】之间的宗教视彼此为【异教】。此外，某些宗教会对特定宗教产生特殊关系修正。", "desc_en": "A Religion is any system of beliefs that belongs to a Religion Group. Every Person has a Religion (and may be Converted to a different one), and every Country has a Primary Religion.\n\nReligions in the same Religion Group consider each other to be Heretic, while Religions in different Religion Groups consider each other to be Heathen. Additionally, Religions may have specific opinions about other Religions."}, {"id": "religious_figure", "zh": "宗教人士", "en": "Religious Figure", "pillar": "culture", "desc": "宗教人士是一名在全世界游走的【角色】，并给其定居的【宗教】带来宗教奖励。尽管一个国家在同一时间只能直接追随单个【宗教学派】，但可通过邀请其他学派的宗教人士来境内定居以汲取他们身上的灵感，从而获得一定加成。宗教人士可以是以下类型中任一类型。\n（详见速查典：religious_figures）", "desc_en": "A religious figure is a Character that travels the earth bringing religious bonuses to places they settle. They can be hired by countries of the appropriate Religion. If our religion has a Religious School, we can only follow one directly, but we can invite religious figures of other schools to draw inspiration from them and gain some of their benefits. A religious figure can be any of the types below.\n(See ledger: religious_figures)"}, {"id": "religious_aspect", "zh": "宗教信条", "en": "Religious Aspect", "pillar": "culture", "desc": "一些【宗教】可以通过信条，使每个信仰该【宗教】的【国家】能够发展具有本国特色的宗教。", "desc_en": "Some Religions have aspects that further specialize the details of each Country's version of the Religion."}, {"id": "religious_order_standing", "zh": "宗教修会地位", "en": "Religious Order Standing", "pillar": "culture", "desc": "某一【宗教骑士团】在其活动所在【国家】拥有的影响力。该地位会随修会的【热忱】提升，也会随它在该国除首个【据点】外每多拥有一座据点而增加，同时与该修会的【圣召】产生的所有全国性效果成正比——无论是虔信修会带来的赐福，还是堕落修会带来的负担，都受此影响。", "desc_en": "How much a Religious Order matters in a Country. It starts from the country's share of the order's Holdings, is raised or lowered by Clergy Satisfaction and by order members serving as ruler, regent, cabinet members or commanders, and is then scaled by the order's Zeal. Standing scales the country-wide effects of the order's Calling, up to a maximum of 200%."}, {"id": "religious_order_type", "zh": "宗教修会类型", "en": "Religious Order Type", "pillar": "culture", "desc": "【宗教骑士团】所属的广泛传统。修会的类型决定其可遵循的【圣召】、可在何处及由谁创建、是否能自行召集【征召兵】。同时也决定了维持修会【据点】所需的消耗。", "desc_en": "The broad tradition a Religious Order belongs to. An order's Type decides which Callings it may follow, where and by whom it can be founded, and whether it musters Levies of its own. It also sets what the order's Holdings consume to sustain themselves."}, {"id": "religious_war", "zh": "宗教圣战", "en": "Religious War", "pillar": "culture", "desc": "宗教圣战由同信仰国家组成的【国际组织】对【异教】国家发动。游戏中最著名的例子是基督教和伊斯兰教【宗教】的十字军和吉哈德。", "desc_en": "A religious war is declared by an International Organization of countries of the same faith to a Heathen country. The most prominent examples in the game are the Crusades and Jihads of the christian and muslim Religions."}, {"id": "religious_status", "zh": "宗教地位", "en": "Religious Status", "pillar": "culture", "desc": "一种【宗教】与【主导宗教】相比较后有以下几种分类。\n• 【主导宗教】\n• 【异端】\n• 【异教】", "desc_en": "This is how a Religion is categorized compared to Primary Religion.\n• Primary Religion\n• Heretic\n• Heathen"}, {"id": "religious_opinion", "zh": "宗教好感", "en": "Religious Opinion", "pillar": "culture", "desc": "每种【宗教】对其他【宗教】都具备宗教好感。这影响了一个【宗教】的【国家】对另一个【宗教】的【国家】的【好感】，同时也影响了【人群】的【人群满意度】。", "desc_en": "Every Religion has a Religious Opinion of every other Religion. This impacts the Opinion a Country with one Religion has of a Country of another Religion, and it also impacts the Pop Satisfaction of a Pop."}, {"id": "religious_school", "zh": "宗教学派", "en": "Religious School", "pillar": "culture", "desc": "神圣的经典或许是绝对正确的，但对于如何让法律和规范最贴合经典，已经形成了不同的学派。\n一个【国家】遵循哪一个学派将影响其未来的道路。", "desc_en": "The Holy Scripture may be infallible, but distinct schools of thought have developed on how laws and norms are best aligned with it.\nWhich school a Country follows will affect its path ahead."}, {"id": "religious_influence", "zh": "宗教影响力", "en": "Religious Influence", "pillar": "culture", "desc": "该数值反映了一个【国家】与【主导宗教】互动并影响其事务的能力。根据【宗教】的不同，其用途也不同，而【国家】获取它的方式也不同。", "desc_en": "It is a value of the ability that a Country has to interact with and influence matters of its Primary Religion. Depending on the Religion, the uses it will have will be different, as well as the ways for a Country to acquire it."}, {"id": "religious_focus", "zh": "宗教焦点", "en": "Religious Focus", "pillar": "culture", "desc": "某些【宗教】拥有【国家】可以聚焦的属性，能提供额外增益。一旦完成足够多的焦点，【宗教】就可以改革。", "desc_en": "Some Religions have attributes that a Country can focus on to gain extra benefits. Once enough focuses have been completed, the Religion can reform."}, {"id": "religion_group", "zh": "宗教组", "en": "Religion Group", "pillar": "culture", "desc": "宗教组是一系列具有相似特性的【宗教】的集合。它们通常视彼此为迷途而非邪恶，但这不会阻止它们彼此发动【战争】。", "desc_en": "A Religion Group is a set of Religions that are similar, and may view each other as merely wrong instead of evil. This will not stop them from starting Wars against each other."}, {"id": "religious_unity", "zh": "宗教统一度", "en": "Religious Unity", "pillar": "culture", "desc": "宗教统一度指的是信奉官方【宗教】的【人口】占【国家】总人口的百分比。", "desc_en": "Religious unity is the percentage of the Country's Population that follows the official state Religion. Each Pop counts in proportion to the Control of its Location, so newly conquered or poorly controlled land has little effect on it."}, {"id": "religious_head", "zh": "宗教领袖", "en": "Religious Head", "pillar": "culture", "desc": "这是被认为掌管并代表整个【宗教】教派的【角色】。", "desc_en": "It is the Character considered to be in charge, and representative of, a whole Religion denomination."}, {"id": "religious_order", "zh": "宗教骑士团", "en": "Religious Order", "pillar": "culture", "desc": "效忠于【宗教】的兄弟会，可遍及多个【国家】，而非只听命于单一的统治者。修会以其【热忱】为存亡之本，遵循某种塑造其行为的【圣召】，并在各【地点】建立【据点】扩大其影响范围。其扎根的地点将建立religious order power short，而它的religious order loyalty short决定了对当地统治者的态度。", "desc_en": "A brotherhood sworn to a Religion that can spread across many Countries rather than answering to any single ruler. An order lives or dies by its Zeal, follows a Calling that shapes how it behaves, and plants Holdings in Locations to extend its reach. Its Standing wherever it takes root, for good or ill, follows from that same Zeal."}, {"id": "sect", "zh": "宗派", "en": "Sect", "pillar": "culture", "desc": "宗派是佛教的众多分支之一，每个宗派都侧重于不同的教义，以及如何遵循佛陀之道和达到觉悟的方法。", "desc_en": "A Sect is one of the many branches of buddhist, each one focusing on different teachings and ways of following the path of the Buddha to reach enlightenment."}, {"id": "court_dialect", "zh": "宫廷方言", "en": "Court Dialect", "pillar": "culture", "desc": "【国家】【宫廷语言】的主要【方言】。", "desc_en": "The main Dialect of a Country's Court Language."}, {"id": "court_language", "zh": "宫廷语言", "en": "Court Language", "pillar": "culture", "desc": "country with icon政府的language with icon。\n\n某些语言可能会影响不同【阶层】的【阶层满意度】：\n• 贵族阶层偏好language power with icon较高的语言。\n• 教士阶层偏好liturgical language with icon。\n• 平民阶层偏好common language with icon。\n• 使用我们【首都】的market language with icon会提高【出售效率】。\n\n宫廷语言的【语言力量】会随着国家【主流文化】【人群】的【政治力量】总量增加。\n\n我们可以将宫廷语言更改为：\n• 【通用语言】\n• 【礼仪语言】\n• 【优势方言】\n• 【首都】的【市场语言】\n• 【已接纳文化】的语言\n• 统治者的语言\n• 宗族领袖的语言\n• 【国际组织领袖】的【宫廷语言】\n• 【宗主国】的【宫廷语言】", "desc_en": "The language with icon of government in a country with icon.\n\nCertain Languages may affect the Estate Satisfaction of different Estates:\n• The nobles estate prefer high language power with icon.\n• The clergy estate prefer the liturgical language with icon.\n• The peasants estate prefer the common language with icon.\n• Using the market language with icon of our Capital will increase the Selling Efficiency.\n\nThe Court Language receives an increase in its Language Power relative to the total Political Power of Pops belonging to the Primary Culture of the Country.\n\nWe can change our Court Language to:\n• Common Language,\n• Liturgical Language,\n• Dominant Dialect,\n• The Market Language of our Capital,\n• The language of an Accepted Culture,\n• Our ruler's language,\n• Our dynasty head's language,\n• The Court Language of an International Organization Leader,\n• The Court Language of our Overlord."}, {"id": "tolerance", "zh": "容忍度", "en": "Tolerance", "pillar": "culture", "desc": "宗教容忍度代表信仰某一特定【宗教】在一个社会中受到尊重或歧视的程度。每个【国家】对【主导宗教】、【异端】和【异教】有三种不同的容忍度。\n\n正值的容忍度将提高【人群】的【人群满意度】并改善信仰同一宗教国家的【外交好感】。相反，负值的容忍度将增加【叛乱度】并恶化外交好感。", "desc_en": "Tolerance represents how respectfully the population of a certain Religion is treated in a society. Every Country has a different Tolerance value towards its Primary Religion, towards Heretics, and towards Heathens.\n\nA positive Tolerance value increases the Pop Satisfaction of Pops, as well as the Diplomatic Opinion towards Countries of that Religion. Reversely, a negative Tolerance increases Unrest and lowers Diplomatic Opinions."}, {"id": "canonization", "zh": "封圣", "en": "Canonization", "pillar": "culture", "desc": "一个【国家】的前【统治者】可以被封圣，即成为【圣人】——但有些信仰需要先得到【宗教领袖】的批准。封圣会取悦教士阶层，并根据该【角色】在世时的能力立即赋予【国家】【正统性】和【威望】。", "desc_en": "A former Ruler of a Country can be canonized, that is, made into a Saint, but some faiths require the Religious Head's approval first. Canonization will please the clergy estate and instantly confer Legitimacy and Prestige upon the Country, scaled according to how able the Character was when they were alive."}, {"id": "accepted_culture", "zh": "已接纳文化", "en": "Accepted Culture", "pillar": "culture", "desc": "每个【国家】都可以有几种与【主流文化】同等待遇的【文化】。\n\n国家可以不受惩罚接纳的文化数量各不相同，并且可通过部分【革新】来增加。\n\n属于已接纳文化的【人群】可在不具备特定【法律】的情况下被动员为【陆军征召兵】或【海军征召兵】。\n\n属于已接纳文化的pops with icon能获得10%的pop satisfaction with icon加成。", "desc_en": "Each Country can have a handful of Cultures that are treated entirely like the Primary Culture.\n\nThe exact amount of cultures a country can afford to accept without penalties is variable, and can be increased by some Advances.\n\nPops belonging to an Accepted Culture can be raised as Army Levies and Naval Levies without requiring any special Law.\n\npops with icon belonging to an Accepted Culture will see their pop satisfaction with icon increased by 10%."}, {"id": "imperial_religion", "zh": "帝国宗教", "en": "Imperial Religion", "pillar": "culture", "desc": "帝国宗教决定了【神圣罗马帝国】的【成员】需要信奉什么【宗教】才能有资格当选【领袖】。帝国宗教也可以是一整个【宗教组】，或完全废除这一政策，这样一来，国家宗教将不再成为投票过程中的决定性因素。", "desc_en": "The Imperial Religion determines what Religion a Member has to follow to be able to be elected to become the Leader of the Holy Roman Empire. It is also possible that the Imperial Religion can either be a Religion Group or can be completely abolished, making religion a non-deciding factor in the voting process."}, {"id": "average_morale", "zh": "平均士气", "en": "Average Morale", "pillar": "culture", "desc": "这是一个【单位】下所有【军团】或【舰船】的平均【士气】。", "desc_en": "This is the average Morale of all Regiments or Ships in a Unit."}, {"id": "katun", "zh": "廿纪年", "en": "K'atun", "pillar": "culture", "desc": "廿纪年是玛雅人的纪年，相当于19.7年。旧廿纪年的结束和新廿纪年的开始伴随着许多仪式和节庆，是统治者和人民非常重要的日期。\n\n当前廿纪年结束时，如果我们投入了足够多的资源准备庆典，我们会获得10年的廿纪年大捷庆典。另一方面，如果没有准备，我们会获得10年的廿纪年厄运惩罚。【宗教影响力】达到90会被视为准备充分。", "desc_en": "A K'atun is a measure of time of the mayan people, it corresponds to 19.7 years. The end of one K'atun and start of a new one was marked by many ceremonies and festivities, making the occasion a truly important date for rulers and their people.\n\nIf by the time the current K'atun ends we have invested enough resources to prepare for the celebrations, we will gain katun celebration for 10 years. On the other hand, if we are not ready we might gain katun celebration bad for 10 years. We will be fully ready once our Religious Influence is at least 90."}, {"id": "heathen", "zh": "异教", "en": "Heathen", "pillar": "culture", "desc": "在一个【国家】中，与【主导宗教】属于不同【宗教组】的所有【宗教】将被视为异教。\n\n基于该国家的【异教容忍度】，异教【人群】通常有更低的【人群满意度】，与异教国家进行【外交】活动通常也会更加困难。", "desc_en": "Any Religion of a different Religion Group than the Primary Religion in a Country will be considered heathen.\n\nDepending on the Tolerance of Heathens in a Country, heathen Pops will generally have lower Pop Satisfaction, and conducting Diplomacy with heathen Countries may prove more difficult."}, {"id": "heathenry_tolerance", "zh": "异教容忍度", "en": "Tolerance of Heathens", "pillar": "culture", "desc": "异教容忍度代表了【异教】信徒在某一【国家】所受到的社会与政治歧视。它降低了异教【人群】的【人群满意度】，并影响了一个国家对异教国家的【外交好感】。\n\n异教容忍度通常处于极低水平，但通过特定【法律】、【特权】和【社会价值观】可改变这一数值。", "desc_en": "The Tolerance of Heathens represents the social and political discrimination Heathens suffer in a Country. It impacts the Pop Satisfaction of heathen Pops, and modifies a Country's Diplomatic Opinion towards heathen Countries.\n\nTolerance of Heathens is generally very low by default, and can be modified by certain Laws, Privileges, and Societal Values."}, {"id": "heretic", "zh": "异端", "en": "Heretic", "pillar": "culture", "desc": "与【国家】【主导宗教】同【宗教组】的其余所有【宗教】都会被视为异端。\n\n根据国家的【异端容忍度】，异端【人群】通常会有较低的【人群满意度】，与异端国家进行【外交】也会更加困难。", "desc_en": "Any Religion that shares Religion Group with the Primary Religion in a Country will be considered heretical.\n\nDepending on the Tolerance of Heretics in a Country, heretic Pops will generally have lower Pop Satisfaction, and conducting Diplomacy with heretic Countries may prove more difficult."}, {"id": "heretic_tolerance", "zh": "异端容忍度", "en": "Tolerance of Heretics", "pillar": "culture", "desc": "异端容忍度代表了同教异宗的【异端】信徒在某一【国家】所受到的社会与政治歧视。它影响了异端【人群】的【人群满意度】，同时影响一国对异端国家的【外交好感】。\n\n异端容忍度通常处于较低水平，但通过特定【法律】、【特权】和【社会价值观】可改变这一数值。", "desc_en": "The Tolerance of Heretics represents the social and political discrimination Heretics suffer in a Country. It impacts the Pop Satisfaction of heretic Pops, and modifies a Country's Diplomatic Opinion towards heretic Countries.\n\nTolerance of Heretics is generally low by default, and can be modified by certain Laws, Privileges, and Societal Values."}, {"id": "conquistador", "zh": "征服者", "en": "Conquistador", "pillar": "culture", "desc": "征服者是被指派征服异域土地，建立我们【国家】的新【附属国】的【角色】。", "desc_en": "A Conquistador is a Character who has been assigned the task to conquer a foreign land and create a new Subject of our Country."}, {"id": "institution", "zh": "思潮", "en": "Institution", "pillar": "culture", "desc": "每个【时代】都有三种不同的思潮，它们将在符合条件的【地点】诞生，然后在地图上传播。当【国家】【接纳】它们后，它们将为该时代解锁新的【革新】。\n\n如果一种思潮在我们【国家】的传播速率不达预期，我们可以尝试推广思潮。", "desc_en": "Each Age has three different institutions that will appear in a fitting Location on the map. They will then spread over the map, and as Countries Embrace them, they unlock new Advances for that age.\n\nIf we find that an Institution does not spread quickly enough to our Country, we can try to study institutions."}, {"id": "war_participation", "zh": "战争参与度", "en": "War Participation", "pillar": "culture", "desc": "这是衡量一个【国家】在【战争】进程中贡献多少的数值。主要通过【战斗】、【封锁】和【围攻】提供。", "desc_en": "This is how much a Country has contributed to the progress of the War. This is primarily done through Battles, Blockades and Sieges."}, {"id": "frontage", "zh": "战斗宽度", "en": "Frontage", "pillar": "culture", "desc": "在【战斗】中，同一时间仅有限数量的【军团】或【舰船】可以交战，这被称为战斗宽度。一些【地形】或【植被】糟糕的【地点】会进一步降低战斗宽度。一些类型的【子单位】会占用较少的宽度，而一些会占用较多的宽度。", "desc_en": "In a Combat, only a limited amount of Regiments or Ships can fight at the same time, and this is called frontage. Some Locations with harsher Topography or Vegetation may reduce the frontage further. There are also some types of Subunits that may use less frontage than others, and some that may use more frontage."}, {"id": "damage_taken", "zh": "承伤", "en": "Damage Taken", "pillar": "culture", "desc": "在【战斗】中，【军团】或【舰船】会承受【士气】和【兵力】的双重损伤。该数值取决于【战斗力】、【兵力】和敌人的其他统计数据，而【经验】、【兵力承伤】或【士气承伤】等属性可以使其降低。", "desc_en": "During a Battle, a Regiment or Ship will take damage both to their Morale and Strength. The amount depends on the Combat Power, Strength, and other statistics of the enemy, while attributes like Experience, Strength Damage Taken, or Morale Damage Taken can reduce it."}, {"id": "artistic_skill", "zh": "技艺", "en": "Artistic Skill", "pillar": "culture", "desc": "这种能力是影响【艺术家】创作的【艺术品】的【艺术品质】的最大因素。", "desc_en": "This skill is the biggest influence on the Art Quality of the Work of Art that an Artist can create."}, {"id": "cultural_maintenance", "zh": "投资文化", "en": "Investing in Culture", "pillar": "culture", "desc": "这笔钱将用于【艺术家】，因此他们可以创造更好的【艺术品】。这也会直接增加我们的【国家】的【威望】。", "desc_en": "This money is spent on Artists, so that they can create better Work of Art. It also directly increases the Prestige of our Country."}, {"id": "holding", "zh": "据点", "en": "Holding", "pillar": "culture", "desc": "【宗教骑士团】所占据的【地点】，比如修道院或骑士团分会。据点会强化它所在的地点，是骑士团在其赞助者【国家】境内religious order power short的基础。在较小的国家里，据点的影响更大，因为每一处据点在当地都更为显要。", "desc_en": "A Location claimed by a Religious Order, such as a monastery or chapter house. A Holding strengthens the Location it sits in and is the foundation of the order's standing within its host Country. Holdings count for more in smaller realms, where each one looms larger over the land."}, {"id": "exploration", "zh": "探索", "en": "Exploration", "pillar": "culture", "desc": "探索是由一名【探险家】领导的任务，目的是【发现】【海军范围】内一片未测绘的海洋或陆地【地区】。\n\n每次探索都有启动成本，这一成本将随着探索区域距【首都】的距离而增加，随【海军范围】而减少。【探险家】的【军事能力】决定了其推进探索的速度。\n\n每个探索都具有月度【杜卡特】花费，这一花费将随【探险家】的【行政能力】而减少。\n\n【探索进度】达到最大时，该【地区】将被【发现】，【探险家】将会返回。", "desc_en": "An exploration is a mission led by an Explorer with the intention of Discovering an uncharted Area of land or sea within Naval Range.\n\nEvery exploration has a progress cost, increased by the distance from Capital, but reduced by Naval Range. The speed at which an Explorer works through this progress is dependent on their Military Ability.\n\nEach exploration has a monthly Ducats cost, which an Explorer will reduce proportionately to their Administrative Ability.\n\nOnce the exploration reaches the end of its Exploration Progress, the Area will be Discovered, and the Explorer will return."}, {"id": "exploration_progress", "zh": "探索进度", "en": "Exploration Progress", "pillar": "culture", "desc": "每个【地区】需要满足一项成本才能被完全【探索】。该数值由众多因素决定，但主要取决于【探险家】的能力。", "desc_en": "Each Area has a cost to be fulfilled before it is fully Explored. This depends on a lot of factors, but primarily on the skill of the Explorer."}, {"id": "expedition", "zh": "探险", "en": "Expedition", "pillar": "culture", "desc": "探险是由【国家】派遣的航行，旨在探索并发现海外的新大陆。", "desc_en": "An Expedition is a voyage sent out by a Country and led by one of its Characters, traveling from waypoint to waypoint until it reaches its destination or comes to grief along the way.\n\nEvery Expedition is of one of five types:\n• Exploration Expeditions chart unknown waters and discover new lands.\n• Commercial Expeditions open distant markets and carry cargo home to our own.\n• Military Expeditions project our strength far beyond our borders.\n• Religious Expeditions undertake pilgrimages and recover holy relics.\n• Diplomatic Expeditions carry embassies to the courts of distant rulers."}, {"id": "explorer", "zh": "探险家", "en": "Explorer", "pillar": "culture", "desc": "探险家是一种具有有利于【探索】的【特质】的【角色】。", "desc_en": "An explorer is a Character who has certain Traits which are useful when they are assigned on an Exploration."}, {"id": "engagement", "zh": "接战", "en": "Engagement", "pillar": "culture", "desc": "当combat with icon开始时，位于前排sections with icon的各支regiments with icon会每小时对initiative with icon进行掷骰检定，直到进入接战。处在【战斗】中【军团】将持续造成伤害。撤退的单位将脱离接战状态并且无法再返回同一场【战斗】。\n\n每个【阵位】中能够同时接战的部队，其数量存在上限，以frontage with icon表示。", "desc_en": "When a combat with icon starts, regiments with icon in the front sections with icon roll initiative with icon every day until they become engaged. When a Regiment is engaged in Combat, it deals damage. When a unit withdraws, it stops being engaged and will not rejoin the same Combat.\n\nOnly a certain amount of frontage with icon can be engaged at once in a Section."}, {"id": "embrace", "zh": "接纳", "en": "Embrace", "pillar": "culture", "desc": "当一个【国家】有足够多的【人口】居住于某个【思潮】已完全传播的【地点】时，该【国家】就能接纳这一思潮。接纳思潮意味着国家已经完全理解这一【思潮】，并且能够【研究】该思潮解锁的【革新】。", "desc_en": "A Country can embrace an Institution when enough of Population of a Country lives in Locations where it has fully spread. This means that the country has fully understood the Institution, and can Research Advances that rely on it."}, {"id": "curia", "zh": "教廷", "en": "Curia", "pillar": "culture", "desc": "教廷是圣座的行政主体，因此也是天主教教会本身的行政主体。任何天主教【国家】都可以与教廷互动并支付【宗教影响力】以发起【教廷行动】。", "desc_en": "The Curia is the administrative body of the Holy See and therefore of the catholic Church itself. Any catholic Country can interact with the Curia and spend Religious Influence to propose a Curia Action."}, {"id": "culture", "zh": "文化", "en": "Culture", "pillar": "culture", "desc": "文化是共享亲近感的一群【人】。\n\n每种文化都有一种【语言】，可能与其他文化相同。\n\n每种文化都有自己的【文化传统】和【文化影响】。不同文化对彼此有不同【文化好感】。\n\n每个【国家】都有一种【主流文化】，并可能还有几种【已接纳文化】或【相容文化】。所有其他的文化都被视为【受忽视文化】。文化可以被其他文化【同化】。\n\n数种文化属于一个或多个【文化组】。", "desc_en": "A Culture is a group of People who share a sense of kinship.\n\nEach Culture possesses a Language, which it may share with other Cultures.\n\nEach Culture has a Cultural Tradition, and a Cultural Influence. Different Cultures have changing Cultural Opinions of each other.\n\nEach Country has a Primary Culture, and may have several Accepted Cultures and/or Tolerated Cultures in addition. All other Cultures in the country are considered Ignored Cultures. Cultures can be Assimilated by other Cultures.\n\nMany Cultures belong to one or more Culture Groups."}, {"id": "cultural_tradition", "zh": "文化传统", "en": "Cultural Tradition", "pillar": "culture", "desc": "这是【文化】在【文化战争】中的防御力，代表这一文化的传统对其人民的影响力。\n\n传统的月度变化取决于相关的【建筑】、【社会价值观】、【革新】以及大量其他因素。", "desc_en": "This is the defense power of a Culture in the context of Culture War, representing how strongly this culture's traditions resonate with its people.\n\nTradition has a monthly change dependent on relevant Buildings, Societal Values, Advances, and many other factors."}, {"id": "cultural_status", "zh": "文化地位", "en": "Cultural Status", "pillar": "culture", "desc": "每个【国家】对任一【文化】的文化地位有以下类别：\n• 【主流文化】\n• 【已接纳文化】\n• 【受忽视文化】\n• 【相容文化】\n• 【外国文化】", "desc_en": "Every Culture is viewed as one of these by a Country:\n• Primary Culture\n• Accepted Culture\n• Ignored Culture\n• Tolerated Culture\n• Foreign Culture"}, {"id": "cultural_opinion", "zh": "文化好感", "en": "Cultural Opinion", "pillar": "culture", "desc": "每种【文化】对其他文化都具备文化好感。这影响了一种文化的【国家】对另一种文化的国家的【好感】，也影响了【人群】的【人群满意度】。", "desc_en": "Every Culture has a Cultural Opinion of every other Culture. This impacts the Opinion a Country with one Culture has of a Country of another Culture, and it also impacts the Pop Satisfaction of a Pop."}, {"id": "cultural_capacity", "zh": "文化容量", "en": "Cultural Capacity", "pillar": "culture", "desc": "【国家】将一个【文化】提升为【已接纳文化】所花费的文化容量取决于这些文化对【主流文化】的【文化好感】，以及该文化人群相对于主流文化的人口对比。", "desc_en": "The cost for a Country to have a Culture as an Accepted Culture depends on their Cultural Opinion of the Primary Culture and the size of that culture in relation to the Primary Culture."}, {"id": "cultural_influence", "zh": "文化影响", "en": "Cultural Influence", "pillar": "culture", "desc": "这是【文化】在【文化战争】中的攻击力，展示它对其他文化的影响力以及文化边界之外的影响力。\n\n当一件【艺术品】完工时会提供月度增长，此外【威望】、特定【建筑】、【革新】、【法律】以及其他许多方面的资源也会提供月度增长。但是要注意，它也有自然的月度衰减。", "desc_en": "This is the attack power of a Culture in the context of Culture War, representing how impressive it appears to other cultures, and the reach it has beyond its own borders.\n\nIt has a monthly increase upon the completion of a Work of Art and has some monthly increase from many sources such as Prestige, and certain Buildings, Advances, Laws, and many others. But beware, it also has a natural monthly decay."}, {"id": "culture_war_power", "zh": "文化战争力量", "en": "Culture War Power", "pillar": "culture", "desc": "该数值是一个进攻【文化】的【文化影响】对抗目标【文化】的【文化传统】时的强度。\n\n拥有高文化战争力量会影响诸如【同化】，【整合】，【间谍网】，【外交】甚至【围攻】的进度。", "desc_en": "This is the strength of an attacking Culture's Cultural Influence against a target Culture's Cultural Tradition.\n\nHaving a high Culture War Power impacts processes like Assimilation, Integration, Spy Networks, Diplomacy, and even Siege."}, {"id": "culture_group", "zh": "文化组", "en": "Culture Group", "pillar": "culture", "desc": "文化组是一系列具有相似特征的【文化】的集合。它们可能具有相同传承、相似传统或仅仅是地域临近。\n\n一个【文化】可能归属于一个或多个文化组，也有可能是不属于任何文化组的孤立文化。\n\n如果两个【国家】的【主流文化】共享至少一个文化组，它们之间的【好感】将获得少量加成。该加成不可叠加。\n\n一些【文化组】能够进行【统合】。", "desc_en": "A Culture Group is a set of Cultures that are similar in some way, whether through shared heritage, similar traditions, or just regional proximity.\n\nA Culture may belong to any number of Culture Groups, though they may also be isolated enough to not belong to any.\n\nCountries whose Primary Cultures share at least one Culture Group will have a small Opinion bonus of each other, though it does not stack if they share multiple.\n\nSome Culture Groups can eventually be Unified."}, {"id": "cultural_unity", "zh": "文化统一度", "en": "Cultural Unity", "pillar": "culture", "desc": "文化统一度指的是【主流文化】【人口】占【国家】总人口的百分比。", "desc_en": "Cultural unity is the percentage of the Country's Population that is of the Primary Culture. Each Pop counts in proportion to the Control of its Location, so newly conquered or poorly controlled land has little effect on it."}, {"id": "dialect", "zh": "方言", "en": "Dialect", "pillar": "culture", "desc": "【方言】是【语言】的变体。它主要影响【角色】、【地点】等事物的名称。", "desc_en": "A Dialect is a variation on a Language. It mostly affects the names of things like Characters and Locations."}, {"id": "age", "zh": "时代", "en": "Age", "pillar": "culture", "desc": "游戏被划分为多个时代，通常每个世纪对应一个时代。每个时代都有独特的规则和机制，以及自己的【革新】树。\n\n（详见速查典：age）\n\n在每个时代开始时，我们需要在【行政】、【外交】和【军事】间选择一个焦点，这影响了我们【国家】在该时代的革新树。", "desc_en": "The game is divided in multiple ages, usually one per century. Each age has its own rules and mechanics, and each has its own tree of Advances that can be progressed through.\n\n(See ledger: age)\n\nAt the start of each age, we select our focus between Administrative, Diplomatic, or Military Focus, which affects how our Country's advance tree will be for that age."}, {"id": "terra_incognita", "zh": "未知之地", "en": "Terra Incognita", "pillar": "culture", "desc": "在【国家】通过【探索】或其他来源【发现】一个【地点】前，它在地图上无法看到，国家也无法与之互动，它被称为未知之地。", "desc_en": "Before a Location has been Discovered by a Country through an Exploration or other sources, it is not visible on the map, nor can it be interacted with by that country, and is referred to as Terra Incognita, Latin for unknown land."}, {"id": "doom", "zh": "末日值", "en": "Doom", "pillar": "culture", "desc": "末日值是由纳瓦特尔【宗教】的【国家】使用的特殊负面资源。\n\n拥有【地点】，尤其是【城镇】，将不可避免地增加末日值。\n\n拥有高水平的末日值将降低属国忠诚度和全局阶层满意度均衡点，但会提高稳定度衰减。\n\n通过某些行动可以降低末日值，如：\n——在【战斗】\n中杀死【战争对手】的部队——劫掠高【发展度】\n\n的【地点】末日值到达最大时，【统治者】及其所有【宗族】成员都将被献祭，并由一个新【统治者】取而代之。", "desc_en": "Doom is a special currency used by Countries with the nahuatl Religion.\n\nOwning Locations—especially Urban Locations—passively increases Doom.\n\nHaving a high Doom value decreases Subject Loyalty and global estate target satisfaction but increases stability decay.\n\nThere are a number of ways that decrease Doom, including:\n- Killing War Enemy troops in Combat\n- Looting Locations with high Development\n\nWhen the maximum Doom is finally reached, the Ruler and their entire Dynasty are sacrificed, and replaced with a new Ruler."}, {"id": "cardinal", "zh": "枢机", "en": "Cardinal", "pillar": "culture", "desc": "枢机是天主教教会的代表，其地位仅次于【教宗】。枢机通过建造枢机座堂这一特殊【建筑】被指派到特定【地点】，并且向【拥有】该【地点】的【国家】宣誓效忠。\n\n【国家】可以使用枢机参与【教廷行动】。", "desc_en": "A Cardinal is a representative of the catholic Church, just immediately behind the Pope. Cardinals are assigned to Locations via the construction of a special Building called seat of cardinal, and they will be loyal to the Country that Owns that Location.\n\nA Country may use its Cardinals to participate in Curia Actions."}, {"id": "true_faith_tolerance", "zh": "正统信仰容忍度", "en": "Primary Religion Tolerance", "pillar": "culture", "desc": "正统信仰容忍度代表了【主导宗教】信徒在某一【国家】受到的优待。它影响了主导宗教【人群】的【人群满意度】，同时也影响同宗国家之间的【外交好感】。\n\n正统信仰容忍度通常是默认为正的，同时可以通过特定【法律】、【特权】和【社会价值观】可提高这一数值。", "desc_en": "The Primary Religion Tolerance represents how much a Country favors the followers of its Primary Religion. It impacts the Pop Satisfaction of Pops of the Primary Religion, and modifies a Country's Diplomatic Opinion towards brethren Countries.\n\nPrimary Religion Tolerance is generally positive by default, and can be increased even further by certain Laws, Privileges, and Societal Values."}, {"id": "naval_damage", "zh": "海军伤害", "en": "Naval Damage", "pillar": "culture", "desc": "该数值影响了【舰船】在【战斗】中可以达到或造成的伤害。", "desc_en": "This impacts how much damage Ships can take or do during Combat."}, {"id": "purity", "zh": "清净", "en": "Purity", "pillar": "culture", "desc": "清净衡量着我们【国家】在神道教教义下的纯洁程度。接触血液和死亡这等不洁之物，如在【战斗】或在瘟疫中损失【人口】会降低清净。进行一些宗教活动将提高清净，如【圣地】巡礼或切腹自尽。", "desc_en": "It is the indication of how pure our Country is according to shinto. Purity is lost by contact with anything impure, such as killing and losing People in Battles, or epidemics, as death and blood are impure. It is gained through performing religious acts, such as pilgrimages to Holy Sites or ritual suicide."}, {"id": "offered_omens", "zh": "潜在神谕", "en": "Offered Omens", "pillar": "culture", "desc": "我国同时能祈求的【神谕】数量，取决于我们的【宗教】和【宗教信条】的潜在神谕修正。", "desc_en": "The number of Omens our country can have summoned at the same time. Set by the Omens Offered modifier from our Religion and Religious Aspects."}, {"id": "artillery_bonus", "zh": "炮兵增益", "en": "Artillery Bonus", "pillar": "culture", "desc": "炮兵【军团】可以使用火炮轰击【防御工事】。强度取决于他们的【炮兵火力】和【要塞】的等级。", "desc_en": "Artillery Regiments have the strength to bombard Fortifications with their guns. The strength depends on their Artillery Barrage and the level of the Fort."}, {"id": "artillery_barrage", "zh": "炮兵火力", "en": "Artillery Barrage", "pillar": "culture", "desc": "【围攻】期间，如果该数值大于【要塞】等级，攻击方就能获得增益！", "desc_en": "If this is higher than the level of the Fort during a Siege, it can give a bonus to the attacker!"}, {"id": "zeal", "zh": "热忱", "en": "Zeal", "pillar": "culture", "desc": "【宗教骑士团】的命脉。热忱会在和平时期消退，可以通过圣战和在信仰边疆的服役得到重振；热忱耗尽的骑士团将会解散。充满热忱的骑士团无论在哪里运作，都能拥有更大的religious order power short，并培养出更为能干的领袖，而一个缺少热忱的骑士团只能产生虚弱的领导者。", "desc_en": "The lifeblood of a Religious Order. Zeal drifts each month toward a target set by the order's Holdings and its standing across the lands it operates in; an order whose Zeal runs dry is dissolved. A zealous order wields greater Standing wherever it operates and produces far more capable leaders, while a spent one raises only feeble ones."}, {"id": "patriarch", "zh": "牧首", "en": "Patriarch", "pillar": "culture", "desc": "牧首是某些基督教【宗教】的最高级别主教。每个【宗教】可以有超过一个牧首，统治着自己的牧首区。", "desc_en": "Patriarchs are the highest-ranking bishops in certain christian Religions. There can be more than one of them in each Religion, ruling over their own patriarchate."}, {"id": "pentarchy", "zh": "牧首区", "en": "Pentarchy", "pillar": "culture", "desc": "五大牧首区代表东正教的传统权力中心。每个作为五大牧首区席位的【地点】都会为拥有该地的【国家】提供不同的【修正】，而一旦某个【国家】拥有全部五个席位，这些【修正】将会翻倍。", "desc_en": "The Pentarchy represents the traditional seats of power of orthodox. Each of the Locations that serve as a seat of the Pentarchy will give a different Modifier to the Country that owns it, and once a Country owns all five seats those Modifiers will be doubled."}, {"id": "conversion", "zh": "皈依", "en": "Conversion", "pillar": "culture", "desc": "这是【人群】随着时间推移改换【宗教】的过程。【内阁】是【国家】推动皈依最有效的途径。当然，【法律】、【特权】、【革新】和【社会价值观】也对其起着重要作用。", "desc_en": "This is the process by which Pops change from one Religion to another over time. The Cabinet is the most reliable medium for a Country to influence Conversion, but Laws, Privileges, Advances, and Societal Values also play a substantial role."}, {"id": "tolerated_culture", "zh": "相容文化", "en": "Tolerated Culture", "pillar": "culture", "desc": "每个【国家】都可能拥有少数被良好对待的【文化】，这些文化的地位略低于【主流文化】，但高于【受忽视文化】。\n\n一个国家在不受到文化惩罚的情况下能够包容的文化数量是可变的，可以通过某些【革新】得到提升。\n\n属于相容文化的【人群】可在不具备特定【法律】的情况下被动员为【陆军征召兵】或【海军征召兵】。\n\n属于相容文化的pops with icon能获得5%的pop satisfaction with icon加成。", "desc_en": "Each Country can have a handful of Cultures that are treated better than Ignored Cultures but not as good as Primary Culture.\n\nThe exact amount of cultures a country can afford to tolerate without penalties is variable, and can be increased by some Advances.\n\nPops belonging to a Tolerated Culture can be raised as Army Levies and Naval Levies without requiring any special Law.\n\npops with icon belonging to an Tolerated Culture will see their pop satisfaction with icon increased by 5%."}, {"id": "research", "zh": "研究", "en": "Research", "pillar": "culture", "desc": "研究【革新】需要时间，一个【国家】同时只能研究一项革新。当我们的【研究进度】达到革新的花费时，我们就获得了革新的增益。\n\n我们研究advances with icon的速度主要取决于我们的liturgical language with icon的力量，我们的pops with icon的平均literacy with icon，我们的教士阶层的【阶层满意度】，以及我们【接纳】的institutions with icon数量。", "desc_en": "Researching an Advance takes time, and a Country can only research one advance at a time. We get the benefit of the advance when our Research Progress reaches the cost of the advance.\n\nThe speed at which we progress towards new advances with icon depends mainly on the power of our liturgical language with icon, the average literacy with icon of our pops with icon, the Estate Satisfaction of our clergy estate, and the number of institutions with icon we have Embraced."}, {"id": "research_progress", "zh": "研究进度", "en": "Research Progress", "pillar": "culture", "desc": "我们的【研究】进度主要取决于我们的liturgical language with icon的力量，我们pops with icon的平均literacy with icon，我们教士阶层的【阶层满意度】，以及我们【接纳】的institutions with icon的数量。", "desc_en": "Our Research Progress depends mainly on the power of our liturgical language with icon, the average literacy with icon of our pops with icon, the Estate Satisfaction of our clergy estate, and the number of institutions with icon we have Embraced."}, {"id": "liturgical_dialect", "zh": "礼仪方言", "en": "Liturgical Dialect", "pillar": "culture", "desc": "【国家】【礼仪语言】的主要【方言】。", "desc_en": "The main Dialect of a Country's Liturgical Language."}, {"id": "liturgical_language", "zh": "礼仪语言", "en": "Liturgical Language", "pillar": "culture", "desc": "这是【国家】官方【宗教】的正式【语言】。天主教等宗教有固定的礼仪语言且不允许更改，但其他宗教允许国家做出更改。国家的礼仪语言的【语言力量】会影响该国【研究】新【革新】的速度。", "desc_en": "This is the official Language that a Country uses for their official Religion. Some religions, like catholic, have a fixed Liturgical Language that can not be changed, but other religions allow countries to change it. The Language Power of the Liturgical Language of a Country impacts the speed of how quickly they Research new Advances."}, {"id": "god", "zh": "神", "en": "God", "pillar": "culture", "desc": "神、女神或神祇是一种由特定宗教作为崇拜焦点的超自然存在，通常被赋予对宇宙或人类存在的某些方面的掌控权。", "desc_en": "A God, Goddess, or Deity, is a supernatural being serving as a focus of worship for any particular religion, and usually assigned powers of control over certain aspects of the universe or human existence."}, {"id": "god_emperors", "zh": "神皇", "en": "God Emperors", "pillar": "culture", "desc": "神皇是由于其事迹拥有无比神圣性而在希腊多神教【宗教】中得到承认的【角色】。成为神皇的过程被称为封圣。", "desc_en": "A God Emperor is a Character that is recognized in a hellenistic Religion by having an extraordinary degree of holiness through their deeds. The process to become a God Emperor is known as canonization."}, {"id": "omen", "zh": "神谕", "en": "Omen", "pillar": "culture", "desc": "神谕是希腊多神教【宗教】中与【众神】相联结的超自然现象，可通过祈求神谕行动召唤预兆。其神力随【统治者】的【能力】的高低而增减。", "desc_en": "Omens are phenomena in the hellenism religion Religion associated with Gods. They are summoned with select omen god and select omen. Their power is increased by the Ability of the Ruler."}, {"id": "movement_speed", "zh": "移动速度", "en": "Movement Speed", "pillar": "culture", "desc": "该数值决定了【单位】在地图上的移动速度。", "desc_en": "This value determines how fast a Unit moves across the map."}, {"id": "excommunication", "zh": "绝罚", "en": "Excommunication", "pillar": "culture", "desc": "绝罚是【统治者】的一种国际地位，附带严重的宗教和外交惩罚。同【宗教】的所有【国家】对被绝罚【国家】减少-50的【好感】，并对其获得被绝罚的统治者【宣战理由】。除此之外，被绝罚【国家】还会获得以下惩罚，直至更换统治者：\n每月宗教影响力 -0.1、威望 -0.2、政府力量 -0.1、对教宗关系 -100", "desc_en": "Excommunication is an international status of a Ruler with a severe religious and diplomatic penalty. All Countries of the same Religion gain -50 Opinion of the excommunicated Country, and the cb excommunication Casus Belli against it. Atop of this, the excommunicated Country receives the following penalties until their next ruler:\nMonthly Religious Influence -0.1, Prestige -0.2, Gov Power -0.1, Papal Relations -100"}, {"id": "merged_culture_group", "zh": "统合文化组", "en": "Unified Culture Group", "pillar": "culture", "desc": "某些【文化组】可以被统合为单独且统一的【文化】。\n\n一个国家可以选择该国【主流文化】所属的其中一支【文化组】进行统合，从而创建一个新【文化】。对于前【主流文化】和【已接纳文化】的【人群】，如果这些文化属于同一【文化组】且使用相同的【语言】，那么他们都将在统合结束时一并同化为新文化。\n\n统合文化组在【同化】属于该文化组的文化时拥有显著优势。\n\n一支【文化组】只能进行一次统合。", "desc_en": "Some Culture Groups can be Unified into a single Culture.\n\nA country can Unify one of their Primary Culture's Culture Groups, which will cause a new Culture to be created. Pops whose Culture belongs to the group assimilate into the new Culture in proportion to how accepted they are, how close their Language is, and the Control and Pop Satisfaction where they live. Other Countries whose Primary Culture belongs to the group are invited to join the new Culture, the more readily the more they favor the unifier and the closer their Language.\n\nUnified Culture Groups have a significant bonus to Assimilating Cultures of that Culture Group.\n\nA Culture Group can only be Unified once."}, {"id": "roman_borders", "zh": "罗马疆界", "en": "Roman Borders", "pillar": "culture", "desc": "这些是象征罗马帝国权力巅峰的土地。包括以下区域：意大利区域、法兰西区域、伊比利亚区域、大不列颠区域、巴尔干区域、安纳托利亚区域、新月沃土区域、埃及区域和马格里布区域。", "desc_en": "These are the lands that denote the height of power of the Roman Empire. The regions included are; italy region, france region, iberia region, great britain region, balkan region, anatolia region, crescent region, egypt region and maghreb region."}, {"id": "autocephalous_patriarchate", "zh": "自主教会", "en": "Autocephalous Patriarchate", "pillar": "culture", "desc": "自主教会是同属东方基督教【宗教】的一群【国家】，其教会的领袖不受任何其他同【宗教】教会的管辖。自主教会的【领袖】可获得额外的增益，成为成员国也有好处。一旦有成员【国家】实力超越了【领袖】，这时或许独立出去创建自己的教区更加有利。如果教区内有【圣地】，还可以将教区的圣座迁移到那里以获得额外的好处。", "desc_en": "An Autocephalous Patriarchate is a group of Countries of the same eastern christian Religion that have as the head of their Church one bishop who does not answer to any other within the Religion. The Leader of the Autocephalous Patriarchate is conferred extra benefits, and being a member can have benefits too, until the member Country outgrows the Leader, at which time it may be beneficial to branch out and create their own. If the patriarchate has a Holy Site within it, then the seat of that patriarchate can be relocated there for extra benefits."}, {"id": "work_of_art", "zh": "艺术品", "en": "Work of Art", "pillar": "culture", "desc": "艺术品是【艺术家】创作的某些事物。艺术品被创作后，会直接增加艺术家所工作【国家】的【主流文化】的【文化影响】。艺术品存放于特定【地点】，但如果该地点被【战争对手】【占领】，它可能会被摧毁或夺取。\n只要一个【国家】持有艺术品，就能为该国的【威望】和【文化传统】带来持续增益。", "desc_en": "A work of art is something that an Artist has created. When the art is created, it will directly increase the Cultural Influence of the Primary Culture of the Country that the artist is working in. Art is present in a Location but can be destroyed or captured if that location becomes Occupied by any War Enemy.\nHaving art in our Country benefits our Prestige and Cultural Tradition."}, {"id": "art_quality", "zh": "艺术品质", "en": "Art Quality", "pillar": "culture", "desc": "【艺术品】的品质影响了它可以提供的【威望】和【文化传统】。\n\n艺术品按质量划分具有下列等级，从低到高为：\n• art_quality_bad\n• art_quality_below_average\n• art_quality_average\n• art_quality_above_average\n• art_quality_good\n• art_quality_very_good\n• art_quality_great\n• art_quality_best", "desc_en": "The quality of the Works of Art impacts how much Prestige and Cultural Tradition it can provide.\n\nA Work of Art can have the following levels of quality, from lowest to highest:\n•  art_quality_bad\n•  art_quality_below_average\n•  art_quality_average\n•  art_quality_above_average\n•  art_quality_good\n•  art_quality_very_good\n•  art_quality_great\n•  art_quality_best"}, {"id": "artist", "zh": "艺术家", "en": "Artist", "pillar": "culture", "desc": "艺术家是创作【艺术品】的【角色】。艺术家可以是以下任一类型。\n（详见速查典：artist）", "desc_en": "An artist is a Character that creates Works of Art. An artist can be any of the types below.\n(See ledger: artist)"}, {"id": "artist_salary", "zh": "艺术家薪水", "en": "Artist Salary", "pillar": "culture", "desc": "这是【艺术家】会赚取的【杜卡特】数额。", "desc_en": "The amount of Ducats an Artist will earn."}, {"id": "honor", "zh": "荣辱", "en": "Honor", "pillar": "culture", "desc": "荣辱衡量了我们【国家】在人民心中荣耀与否。\n\n维持国家【清净】高于75会提高【荣辱】，清净较低则会降低荣辱。\n\n其他宗教和外交行动也可以影响它。", "desc_en": "How honorable our Country is in the eyes of our people.\n\nMaintaining the Purity of our country above 75 will increase our Honor while having low Purity will decrease it.\n\nOther religious and diplomatic actions may also affect it."}, {"id": "language", "zh": "语言", "en": "Language", "pillar": "culture", "desc": "每种【文化】都有一种可能与其他【文化】相同的【语言】。该【语言】具有【语言力量】，以及决定了【角色】姓名的多种【方言】。\n\n【国家】可以有一种【宫廷语言】）、一种【礼仪语言】，并且它的【通用语言】和【主流文化】相同。\n\n一些语言属于同一个【语族】，而其他一些则是【孤立】的。", "desc_en": "Each Culture has a Language they may share with other Cultures. The Language has a Language Power, and any number of Dialects which determine Character names.\n\nA Country can have a Court Language, a Liturgical Language, and shares its Common Language with its Primary Culture.\n\nSome languages belong to a Language Family, whereas some others are Isolated."}, {"id": "language_power", "zh": "语言力量", "en": "Language Power", "pillar": "culture", "desc": "语言力量表示一种【语言】的影响力、影响范围和声望。它是与世界上最强大的语言相对的百分比。\n\n影响其计算的因素包括：使用该语言作为【宫廷语言】的【国家】中【主流文化】【人群】的【政治力量】，以及使用该语言作为【礼仪语言】的国家中【主导宗教】教士的数量。\n\n语言力量较高的【礼仪语言】可以加快【研究】的速度，而语言力量较高的【宫廷语言】可以增加贵族的【阶层满意度】。", "desc_en": "Language Power represents the reach, influence, and prestige of a Language. It is expressed as a percentage relative to the most powerful Language in the world.\n\nIt is calculated by the total Political Power of Pops with the Primary Culture in Countries where it is the Court Language, and the number of Clergy following the Primary Religion in Countries where it is the Liturgical Language.\n\nHaving a Liturgical Language with high Language Power increases the speed of Research, while a Court Language with high Language Power increases the Estate Satisfaction of the Nobility."}, {"id": "harmony", "zh": "调和", "en": "Harmony", "pillar": "culture", "desc": "调和是衡量【国家】是否符合道法平衡的标准，需要在阳面失衡（正调和）与阴面失衡（负调和）之间保持平衡。国家主要通过【事件】将该数值推向前者或后者，并应尽量达到调和平衡。", "desc_en": "Harmony is a measure of how well the Country is following the principles of the Dào, having to balance between being influenced by Negative Harmony or Positive Harmony. The country will get many effects nudging it towards one or the other, mainly through Events, and should try to keep Balanced Harmony."}, {"id": "movement", "zh": "运动", "en": "Movement", "pillar": "culture", "desc": "运动是指一个【地点】爆发的新【运动类型】。这些地点将成为每项【运动类型】的中心。", "desc_en": "A Movement is when a new Movement Type breaks out in a Location. These serve as epicenters for each Movement Type."}, {"id": "movement_modifier", "zh": "运动修正", "en": "Movement Modifier", "pillar": "culture", "desc": "作用于【运动】的【修正】。这会作用于所有受运动影响的【地点】。", "desc_en": "A Modifier that applies to the Movement. These will apply to each Location a movement affects."}, {"id": "movement_definition", "zh": "运动类型", "en": "Movement Type", "pillar": "culture", "desc": "运动概括了在人群中传播的思想。这会对它接触到的每个【人群】产生各种影响。", "desc_en": "A Movement encapsulates ideas moving through a population. This can have various effects on each Pop it touches."}, {"id": "common_language", "zh": "通用语言", "en": "Common Language", "pillar": "culture", "desc": "这是【国家】的【主流文化】的【语言】。如果这同时是【宫廷语言】，那么平民阶层会感到高兴。", "desc_en": "This is the Language of the Primary Culture in a Country. If this is the Court Language then the peasants estate will be happy."}, {"id": "section", "zh": "阵位", "en": "Section", "pillar": "culture", "desc": "在一场combat with icon中，交战双方各自部署四个阵位。其中，【中军】、左【侧翼】和右【侧翼】组成前线阵列，【预备队】则采纳后方支援位。\n\n【战斗】过程中，部署在前线阵位的【军团】或【舰船】主动与对应阵位的敌方单位【接战】。若对应阵位处于空缺，这些单位可自由选择其他前线阵位实施攻击——具备优秀【侧翼攻击能力】的单位将享受额外伤害加成。\n\n当作战单位因【士气】崩溃而撤退或全灭时，【预备队】将通过combat speed with icon检定，尝试向前线推进填补空缺。当任意交战方的所有前线阵位失去全部作战单位时，将自动判定该场【战斗】结束。", "desc_en": "Each side in a combat with icon has four Sections: three at the front of the Combat (Center, left Flank, and right Flank), and one at the back, the Reserves.\n\nDuring combat, Regiments or Ships in the front Sections will attempt to Engage enemies in the opposite section. If the opposite Section is empty, they can attack any other front Section, where a unit with a good Flanking Ability can do extra damage.\n\nIf units get destroyed or withdraw due to too low Morale, units from the Reserves will attempt to move up to replace them by rolling combat speed with icon. The Combat ends when there are no more units in the front Sections of one side."}, {"id": "advance", "zh": "革新", "en": "Advance", "pillar": "culture", "desc": "革新象征着人类知识领域内可以实现的思想、发明、技术和其他进步。\n\n一个【国家】在同一时间只能【研究】一项革新，其研究速度取决于该国的research progress with icon。\n\n随着每个【时代】的到来，各个【国家】将陆续能够研究新的革新。大多数革新在【接纳】对应institutions with icon之后便能够研究，但一些革新仅供特定【国家】标签、【文化】或【宗教】的国家研究。\n\n国家研发新advances with icon的速度主要取决于该国的liturgical language with icon力量、pops with icon的平均literacy with icon、教士阶层阶层的【阶层满意度】以及我们所【接纳】的institutions with icon数量。", "desc_en": "Advances represent ideas, inventions, technologies, and other areas of human knowledge.\n\nOnly one Advance can be Researched at a time, and the speed at which a Country can research them depends on their research progress with icon.\n\nWith every Age, new Advances become available for Countries to discover. Some are exclusive to specific Countries, Cultures, or Religions, but most simply require having Embraced the appropriate institutions with icon.\n\nThe speed at which we progress towards new advances with icon depends mainly on the power of our liturgical language with icon, the average literacy with icon of our pops with icon, the Estate Satisfaction of our clergy estate, and the number of institutions with icon we have Embraced."}, {"id": "disloyal_subjects", "zh": "不忠的属国", "en": "Disloyal Subjects", "pillar": "diplomacy", "desc": "【附属国】对【宗主国】的【属国忠诚】低于50时，就会变为不忠的属国。\n\n在这种情况下，它将不再加入【宗主国】的【战争】并且不能被【吞并】。", "desc_en": "When a Subject has less than 50 Subject Loyalty towards its Overlord, it becomes a Disloyal Subject.\n\nWhen in such a state, it will no longer help in the Wars of its Overlord and cannot be Annexed."}, {"id": "event", "zh": "事件", "en": "Event", "pillar": "diplomacy", "desc": "事件是指游戏过程中在符合条件的情况下发生在一个【国家】的事情。它们通常带有一个【效果】并讲述一段游戏内故事。\n一些【国家】拥有【动态历史事件】。", "desc_en": "Events are occurrences which happen to a Country throughout the game if the conditions for them are met. They usually have an Effect attached to them and tell a piece of ingame narrative.\nSome Countries have access to Dynamic Historical Events."}, {"id": "event_option", "zh": "事件选项", "en": "Event Option", "pillar": "diplomacy", "desc": "所有【事件】都拥有至少一项可选项。如果事件是【动态历史事件】，会有一项【史实选项】。", "desc_en": "Every Event has at least one option that the player can choose. If the event is a Dynamic Historical Event, it may have a Historical Option."}, {"id": "favors", "zh": "人情", "en": "Favors", "pillar": "diplomacy", "desc": "人情代表一个【国家】向另一【国家】许诺或亏欠的恩惠。\n人情可视作请求另一【国家】执行某行动的资源。如果亏欠太多人情，拒绝这些请求可能导致【信任度】甚至【外交声誉】丧失。", "desc_en": "Favors represent how much one Country has promised, or otherwise owes, to another Country.\nFavors can be spent to ask the other Country to do something. If favors get too unbalanced, refusing to do these things can cause a loss of Trust or even Diplomatic Reputation.\nFavors are tracked separately in each direction, and each direction is capped. They also decay a little every month, so they cannot be hoarded indefinitely."}, {"id": "guarantee", "zh": "保障独立", "en": "Guarantee", "pillar": "diplomacy", "desc": "这种【条约】下，一个【国家】对另一【国家】保障独立，承诺在他们于【战争】中被攻击时提供保护。", "desc_en": "This is a Treaty where one Country is guaranteeing the other Country, promising to protect them if they would be attacked in a War."}, {"id": "trust", "zh": "信任度", "en": "Trust", "pillar": "diplomacy", "desc": "信任度代表一个【国家】认为另一【国家】对自己坦诚相待的可能性。\n无论友邦或敌国，信任度是促成长久协议的关键因素。", "desc_en": "Trust represents how likely one Country finds it that another Country will act honorably towards them.\nWhether friend or foe, Trust is a crucial component in forging lasting agreements."}, {"id": "trust_equilibrium", "zh": "信任度均衡点", "en": "Trust Equilibrium", "pillar": "diplomacy", "desc": "信任度均衡点代表另一【国家】的【信任度】趋向于的目标数值。信任度是达成长久协议的关键要素。", "desc_en": "Trust equilibrium represents the amount Trust with another Country will drift towards. Trust is a crucial component in forging lasting agreements."}, {"id": "spy_network_fog", "zh": "信息迷雾", "en": "Intelligence Fog", "pillar": "diplomacy", "desc": "其他【国家】及其治下【地点】的部分信息默认处于隐藏状态。直到在该国建立足够强大的【间谍网】后，你才能解锁更详尽的情报，包括【人口】构成、经济产值、军备实力等数据。", "desc_en": "Some information about foreign Countries and their Locations is hidden unless you have a sufficient Spy Network in that country. Building a stronger spy network reveals more detailed data, including Population composition, economic output, military strength, and more."}, {"id": "union", "zh": "共主邦联", "en": "Union", "pillar": "diplomacy", "desc": "共主邦联是两个或更多【国家】因【王室联姻】而拥有共同【统治者】时形成的【条约】类型。这一状态下的国家类似共同防御【同盟】，在一方受到攻击时将召唤其余联合统治方加入战争。国家可以通过【法律】改变共主邦联的运作模式。共主邦联内最重要的成员被称为联统主导国，而其他的成员则被称为被联统国。", "desc_en": "A union is a type of Treaty that happens when two or more Countries have come to have the same Ruler due to Royal Marriages. This functions like a defensive Alliance in that they will come to each other's help automatically if they are attacked, but Laws can be added to them to change how the union works. The most important member in the union is called the Senior Partner, while the rest of countries in a union are the Junior Partners."}, {"id": "great_power", "zh": "列强", "en": "Great Power", "pillar": "diplomacy", "desc": "【列强】是指通过【革新】、【人口】、土地面积、【发展度】和其他因素，成为世界上最强大国家之一的【国家】，因此只需颐指气使即可影响其他国家。\n\n拥有最高【列强分数】的数个【国家】将成为【列强】。列强总数的变化取决于排名第一的列强的【列强分数】与剩余国家相比较的情况。\n\n【附属国】和正在进行独立战争的【国家】不能成为列强。", "desc_en": "A Great Power is a Country that has accumulated enough Great Power Points by dominating areas of high economic value to project its influence across the world.\n\nA Country dominates an Area when it controls at least two-thirds of the area's ownable Locations, counting Subjects at a reduced rate. Each area is worth 1–20 Great Power Points depending on its potential tax base relative to the world median.\n\nOnce a Country crosses the Great Power Points threshold it gains extra Diplomatic Capacity, Diplomats, Power Projection, Prestige, and mercenary range, as well as the ability to Enforce Peace, Intervene in Wars, and Threaten War anywhere in the world."}, {"id": "great_power_points", "zh": "列强点数", "en": "Great Power Points", "pillar": "diplomacy", "desc": "列强点数衡量一个【国家】支配了世界上多少经济领土。【国家】通过控制（【附属国】以较低倍率计入）一个【地区】至少三分之二的可拥有【地点】累积点数。每个地区根据其潜在税基与世界中位数的对比价值1到10点数。\n\n累积足够多的点数可以成为【区域强权】或【列强】。", "desc_en": "Great Power Points measure how much of the world's economic territory a Country dominates. A Country earns points by controlling at least two-thirds of the ownable Locations in an Area, counting Subjects at a reduced rate. Each area is worth 1-20 points based on its potential tax base relative to the world median.\n\nAccumulate enough points to become a Regional Power or Great Power."}, {"id": "power_projection", "zh": "力量投射", "en": "Power Projection", "pillar": "diplomacy", "desc": "力量投射较高的【国家】可以剥削较低的国家。如果我国的力量投射比另一国家高，那么我们就可以在他们的【地点】建造贸易站、奴隶集散场、布道所或其他特定建筑。我们的力量投射越高，【特许殖民地】将地点纳入统治的速度越快。同时，对别国保持力量投射优势还能降低我们对其发动【战争】的【稳定度】花费并降低【厌战度】。", "desc_en": "Countries with higher Power Projection can exploit nations with less. If ours is higher than another nation's, then we will be able to build a trade office, slave center, missionary building, or other specific buildings in their Locations. The higher our Power Projection is, the quicker our Colonial Charters can take control over locations. Having a higher Power Projection than another country also reduces the Stability cost of declaring War upon them, as well as the War Exhaustion."}, {"id": "dynamic_historical_event", "zh": "动态历史事件", "en": "Dynamic Historical Event", "pillar": "diplomacy", "desc": "这些是条件合适的情况下，会在指定时间段发生于特定【国家】的历史【事件】。", "desc_en": "These are historical Events that will happen to a specific Country within a specified time period if the conditions are right for it."}, {"id": "coalition", "zh": "包围网", "en": "Coalition", "pillar": "diplomacy", "desc": "对某一【国家】的【敌意】超出阈值的【国家】可能会决定加入针对该国的包围网。要加入包围网，国家需要对目标的【敌意】超过50，【好感】低于‑50，处于外交范围内，且不能与目标国处于战争、停战或联合统治状态，也不能是目标的附属国（朝贡国除外）。如果目标国攻击任意成员，所有成员将防御彼此，并可集体向目标国发动【战争】。与目标国处于战争状态时，成员不得退出包围网；但在和平状态下，若其【敌意】降至30以下，则会自动脱离。若包围网领袖退出，或目标国不复存在，包围网将立即解散。", "desc_en": "Countries whose Antagonism towards a particular Country has exceeded acceptable bounds may decide to join a Coalition targeting that country. To join, a country requires Antagonism above 50 and Opinion below −50 towards the target, must be within diplomatic range, and cannot be at war, in a truce, or in a union with the target — nor a subject of the target (tributaries excepted). Members will defend each other if the target attacks one of them, and may collectively declare War on the target. A member cannot leave while at war with the target, but will automatically depart if their Antagonism falls below 30 while at peace with the target. A Coalition dissolves immediately if its leader leaves, or if the target country ceases to exist."}, {"id": "alliance", "zh": "同盟", "en": "Alliance", "pillar": "diplomacy", "desc": "同盟是两个【国家】间的【条约】，处于同盟的【国家】不得相互宣战，并且在处于【战争】时可以召唤对方加入【战争】。", "desc_en": "An alliance is a Treaty between two Countries. Countries that are allied will not be able to declare War upon each other and can also be called to help in each other's Wars."}, {"id": "annexation", "zh": "吞并", "en": "Annexation", "pillar": "diplomacy", "desc": "【宗主国】对其【附属国】之一实现完全接管就是吞并。\n\n【宗主国】会获得【附属国】【拥有】的所有【地点】，【核心】和【角色】。【附属国】将不再作为【国家】存在。\n\n附属国可以使用阻挠吞并【内阁行动】减缓吞并进度，或者直接用特殊的反抗吞并【宣战理由】发动【战争】。\n\n【不忠的属国】不能被吞并。", "desc_en": "When an Overlord completely takes over one of its Subjects.\n\nThe Overlord will gain all of the Subject's Owned Locations, Cores, and Characters. The Subject will no longer exist as a Country.\n\nThe subject can slow the progress with the frustrate annexation Cabinet Action, or declare War with their special cb resist annexation Casus Belli.\n\nA Disloyal Subject cannot be annexed."}, {"id": "international_organization", "zh": "国际组织", "en": "International Organization", "pillar": "diplomacy", "desc": "一些【国家】以某种协议而组成的联合，有时候是为了对抗另一个【国家】。", "desc_en": "A group of Countries that have banded together in some kind of agreement, sometimes targeting another Country."}, {"id": "international_organization_modifier", "zh": "国际组织修正", "en": "International Organization Modifier", "pillar": "diplomacy", "desc": "作用于【国际组织】的【修正】。", "desc_en": "A Modifier that applies to the International Organization."}, {"id": "international_organization_variable", "zh": "国际组织变量", "en": "International Organization Value", "pillar": "diplomacy", "desc": "在不同的【国际组织】机制下，国际组织变量可对应不同的概念。在某些类型的组织中，它代表国际组织【领袖】的权威，例如神圣罗马帝国或中华天朝。而在另一些类型的组织中，如宗派，它则象征国际组织本身的影响力。此外，在其他特定类型的国际组织机制中，该变量可能承担不同的功能。", "desc_en": "Values in an International Organization can be used to represent different mechanics depending on the International Organization. In some cases, it represents the authority of the Leader of the organization, like in the Holy Roman Empire or the Middle Kingdom. In others, like the Sect, it represents the influence of the International Organization itself. There may be other uses for the values, and it will depend on each International Organization type."}, {"id": "international_organization_type", "zh": "国际组织类型", "en": "International Organization Type", "pillar": "diplomacy", "desc": "国际组织类型定义了【国际组织】的整体架构，例如可与其进行的交互行动或其领导权结构。\n\n每个国际组织都属于以下类型之一。\n（详见速查典：international_organization_type）", "desc_en": "The International Organization Type of an International Organization defines its overall structure, such as the interactions that can be had with it, or its leadership structure.\n\nEach International Organization belongs to one of the types below.\n(See ledger: international_organization_type)"}, {"id": "international_organization_leader", "zh": "国际组织领袖", "en": "International Organization Leader", "pillar": "diplomacy", "desc": "【国际组织】会有一个【国家】作为其【领袖】。每个【国际组织】不尽相同，但通常来说是【国际组织】内最强大的【国家】。\n\n一些拥有投票制度的组织会通过选举决定【领袖】【国家】，有些依靠其他制度决定领导权，还有些根本没有【领袖】。", "desc_en": "An International Organization may have a Country as its Leader. Each International Organization is different, but in general, it is the most powerful Country in the International Organization.\n\nSome organizations have a system to vote for the Country that has to be the Leader, while others rely on other systems to define their leadership, and others may have no Leader at all."}, {"id": "opinion", "zh": "好感", "en": "Opinion", "pillar": "diplomacy", "desc": "好感衡量了一个【国家】对另一个【国家】亲密或仇恨的程度。好感和【信任度】的差别在于，高好感度将防止一个【国家】对你产生敌意，但需要信任度才能相互合作。", "desc_en": "This is how much a Country likes or dislikes another Country. The difference between Trust and opinion is that a high opinion will stop a Country from being hostile, but we would need trust to be able to work together."}, {"id": "threat", "zh": "威胁", "en": "Threat", "pillar": "diplomacy", "desc": "这代表一个【国家】对另一国家的担忧程度。更强大的邻国会拥有较高的威胁等级。", "desc_en": "This describes how worried a Country is about another country. A more powerful neighbor will have a high threat level."}, {"id": "isolate", "zh": "孤立", "en": "Isolate", "pillar": "diplomacy", "desc": "孤立【国家】不允许其他任何国家在其【市场】【出口】或【进口】【商品】。他们或许会给予某些国家无视这些规则的专营权利。", "desc_en": "A Country that is isolated will not allow any other country to Export or Import Goods in their Markets. They may give some countries exclusive rights to ignore these rules."}, {"id": "overlord", "zh": "宗主国", "en": "Overlord", "pillar": "diplomacy", "desc": "宗主国是拥有任何数量【附属国】作为下属的【国家】。\n\n它会在【战争】中保护每一个【附属国】，作为回报，它通常会收取【属国赋税】，并从【附属国】中抽取一定比例的【列强分数】。确切规则取决于每个【附属国】的【属国类型】。\n\n任意宗主国反过来都有可能是其他【国家】的【附属国】，允许形成【附属国】‑宗主国关系的长链。", "desc_en": "An Overlord is a Country that has any number of Subjects as its subordinates.\n\nIn return for protecting each Subject in Wars, it typically receives Subject Taxation, and exacts a certain percentage of the Subject's Great Power Score. The exact rules are dependent on each Subject's Subject Type.\n\nAny Overlord may in turn be the Subject of other Countries, allowing long chains of Subject-Overlord relationships."}, {"id": "rival", "zh": "宿敌", "en": "Rival", "pillar": "diplomacy", "desc": "【国家】可以通过宣布宿敌表达对其他国家的敌对。宿敌会开放一些额外敌对行动，例如制造【宣战理由】和干预他们的【战争】。\n\n宿敌国家不会接受【同盟】等友善【条约】，而拥有共同宿敌的【国家】将更容易签署【条约】。\n\n宿敌关系不是双向的，这意味着被宣布宿敌的国家并不必须、也不会自动回宣宿敌。宣布另一国家为宿敌的【国家】会被视为前者的【敌人】。\n\n只有【列强分数】接近且【好感】较低的【国家】才能宣为宿敌，【国家】的宿敌上限取决于其【国家等级】。", "desc_en": "Countries can declare their hostility towards other countries by declaring them as Rivals. Countries have some additional hostile actions against their rivals, like the ability to fabricate a Casus Belli and the option to intervene in their Wars.\n\nA Rival Country will not accept friendly Treaties like Alliances, but Countries with common rivals will have an easier time signing Treaties between them.\n\nRivalry is not reciprocal, meaning that it is not necessary nor automatic for a Country to rival back the ones that have rivaled it. A Country that has declared another as its Rival is known as its Enemy.\n\nOnly Countries with similar Great Power Score and not very good Opinion can be declared Rivals, and the maximum number of Rivals a Country can have depends on its Country Rank."}, {"id": "situation", "zh": "局势", "en": "Situation", "pillar": "diplomacy", "desc": "局势是本游戏所使用的一系列最重要的历史事件，这些事件将影响多个【国家】，并且将在一段时间持续生效。\n\n一些最重要的局势有黑死病和宗教改革。\n\n传统时代（I）的局势包括：\n• 百年战争\n• 归尔甫派和吉伯林派\n• 土耳其人的崛起\n• 南北朝时代\n• 德里的衰亡\n\n文艺复兴时代（II）的局势包括：\n• 黑死病\n• 胡斯战争\n• 红巾军起义\n• 帖木儿的崛起\n• 西方教会大分裂\n\n探索时代（III）的局势包括：\n• 大瘟疫\n• 意大利战争\n• 宗教改革\n• 战国时代\n• 托德西利亚斯条约\n\n宗教改革时代（IV）的局势包括：\n• 脱利腾大公会议\n• 宗教战争\n\n绝对主义时代（V）的局势包括：\n• 哥伦布大交换\n• 海盗黄金时代\n• 小冰期\n\n革命时代（VI）的局势包括：\n• 殖民地独立革命\n• 人民起义", "desc_en": "A Situation is what the game uses for the most important historical incidents that involve more than one Country, and/or are happening over a period of time.\n\nSome of the most important Situations include the black death and Reformation.\n\nThe Situations of the age 1 traditions:\n• Hundred Years' War\n• Guelphs and Ghibellines\n• Rise of the Turks\n• Nanbokuchō Jidai\n• Fall of Delhi\n\nThe Situations of the age 2 renaissance:\n• Black Death\n• Hussite Wars\n• Red Turban Rebellions\n• Rise of Timur\n• Western Schism\n\nThe Situations of the age 3 discovery:\n• Great Pestilence\n• Italian Wars\n• The Reformation\n• Sengoku Jidai\n• Treaty of Tordesillas\n\nThe Situations of the age 4 reformation:\n• Council of Trent\n• War of Religions\n\nThe Situations of the age 5 absolutism:\n• Columbian Exchange\n• Golden Age of Piracy\n• Little Ice Age\n\nThe Situations of the age 6 revolutions:\n• Colonial Revolution\n• People's Uprising"}, {"id": "subject_loyalty", "zh": "属国忠诚", "en": "Subject Loyalty", "pillar": "diplomacy", "desc": "每个【附属国】都有一项对【宗主国】的属国忠诚。该数值从0到100，一旦数值降至50以下，【附属国】会变为【不忠的属国】。\n\n该数值直接由【独立倾向】影响，并且可以通过煽动不忠【内阁行动】进一步降低。", "desc_en": "Every Subject has a Subject Loyalty towards their Overlord. Ranging from 0 to 100, once it drops below 50 the Subject will become a Disloyal Subject.\n\nIts value is directly impacted by Liberty Desire, and can be further decreased with the sow disloyalty Cabinet Action."}, {"id": "subject_type", "zh": "属国类型", "en": "Subject Type", "pillar": "diplomacy", "desc": "每个【附属国】都有一项属国类型，从根本上概述了其必须在【战争】和【继承法】等方面遵守的规则。\n\n属国类型也决定了【附属国】必须交给【宗主国】的【属国赋税】和被榨取的【列强分数】。", "desc_en": "Every Subject has a Subject Type, which essentially outlines the rules that it must follow in regard to aspects like War and Succession Law.\n\nSubject Types also dictate the Subject Taxation and Great Power Score that each Subject must surrender to its Overlord."}, {"id": "imperial_circle", "zh": "帝国行政圈", "en": "Imperial Circle", "pillar": "diplomacy", "desc": "【神圣罗马帝国】成员组成的区域性组织。【皇帝】可以通过【行政圈领袖】直接对整个【帝国行政圈】采取特定行动。", "desc_en": "A regional grouping of Holy Roman Empire members. The Emperor can target certain actions directly at an entire Imperial Circle through the Circle Leader."}, {"id": "loyal_subjects", "zh": "忠诚的属国", "en": "Loyal Subjects", "pillar": "diplomacy", "desc": "【附属国】对【宗主国】的【属国忠诚】高于50，即是忠诚的附属国。\n\n在这种情况下，它会加入【宗主国】的【战争】，并且可以被【吞并】。", "desc_en": "When a Subject has more than 50 Subject Loyalty towards its Overlord, it becomes a Loyal Subject.\n\nWhen in such a state, it will join the Wars of its Overlord and may be Annexed."}, {"id": "fow", "zh": "战争迷雾", "en": "Fog of War", "pillar": "diplomacy", "desc": "遮蔽地图【发现】部分的遮蔽物被称为【战争迷雾】。\n\n潜伏在【战争迷雾】中的其他【国家】【单位】是【隐匿】。\n\n【地点】始终对其【控制者】可见。此外，一个【国家】总是可以看见他们【拥有】的【核心】，即使它们被【战争对手】【占领】。\n\n【同盟】，【附属国】和【宗主国】会共享视野。\n\n一些【地点】将始终处于【战争迷雾】中，比如森林【植被】或山地【地形】。\n\n带有海峡【地形】的【海域】只会阻碍其他【海域】的视野。", "desc_en": "The shroud that obscures Discovered parts of the map is called the Fog of War.\n\nUnits belonging to other Countries are Hidden while they lurk in the Fog of War.\n\nA Location is always visible to its Controller. Furthermore, a Country can always see into Cores that they Own, even if they are Occupied by an War Enemy.\n\nAllies, Subjects, and Overlords share their vision with each other.\n\nSome Locations will always be in the Fog of War, for example those with forest Vegetation or mountains Topography.\n\nSeazones with the narrows Topography will only obstruct vision from other Seazones."}, {"id": "antagonism", "zh": "敌意", "en": "Antagonism", "pillar": "diplomacy", "desc": "敌意值反映了其他【国家】如何看待我们，影响他们对我们的【好感】。如果他国对我们的敌意较高，那些视我们与其利益相关的国家将更不愿意开展【外交】，并可能采取不利于我方的行动。敌意的产生源于国家间在【社会价值观】、【政体】、【宗教】、【文化】及【语言】等方面的差异。某些行为可能也会在特定【地点】引发“敌意动荡”，对周边国家产生不同程度的影响，具体影响取决于这些国家对该区域及敌意发起国的关注程度。“敌意震荡”的效果通常会随时间逐渐消退。", "desc_en": "Antagonism indicates how other Countries are likely to view us, affecting their Opinion of us. If they feel a lot of antagonism towards us, countries which consider us as relevant to their interests will be less inclined to engage in Diplomacy and may act against our interests. Antagonism is caused by basic differences between countries' Societal Values, Government Types, Religion, Culture, and Language. Some actions can also cause an antagonism 'bomb' in a Location that affects the countries near it to varying degrees depending on how much they care about that location and about the antagonizing country. These antagonism 'bomb' effects will generally dissipate with time."}, {"id": "antagonism_received_modifier", "zh": "敌意获得", "en": "Antagonism Received", "pillar": "diplomacy", "desc": "这描述了【战争】等敌对外交行动如何加剧我国面临的【敌意】。", "desc_en": "This is how much hostile diplomatic actions like War will impact our Antagonism."}, {"id": "treaty", "zh": "条约", "en": "Treaty", "pillar": "diplomacy", "desc": "条约是两个或更多【国家】之间签署的外交协定。条约可以具有时限，也可以持续生效直至一方变动。\n条约包括【同盟】、【军事通行权】、【停战】和其他通过【外交】行动取得的协定。", "desc_en": "A Treaty is a signed diplomatic state of affairs between two or more Countries. They could be for a limited time, or until further notice.\nTreaties include Alliances, Military Access, Truce, and many more than can be created from Diplomacy."}, {"id": "disaster", "zh": "灾难", "en": "Disaster", "pillar": "diplomacy", "desc": "灾难是影响单个【国家】的重要破坏性事件，它们可能会持续很长一段时间，直到国家成功将其克服。\n\n部分最重要的灾难包括金色安布罗斯共和国和德里的解体。", "desc_en": "A Disaster is an important and disruptive incident affecting a single Country, and they could last or remain active over a long period of time, until the country manages to overcome it.\n\nSome of the most important Disasters include ambrosian republic disaster and dissolution of delhi."}, {"id": "liberty_desire", "zh": "独立倾向", "en": "Liberty Desire", "pillar": "diplomacy", "desc": "独立倾向代表了一个【附属国】当前从【宗主国】独立的渴望，直接影响着【属国忠诚】。\n\n它的值在‑100到+100之间，但每月会向0衰减。\n\n该值也会在某些附属国互动中充当资源。", "desc_en": "Liberty Desire represents a Subject's current drive for independence from its Overlord, and it affects Subject Loyalty.\n\nIts value is from -100 to +100, but it has a monthly decay towards 0.\n\nThe value is also used as a currency in some Subject Interactions."}, {"id": "hre_emperor", "zh": "皇帝", "en": "Emperor", "pillar": "diplomacy", "desc": "皇帝是【神圣罗马帝国】的【领袖】。皇帝的职责是保护【成员】免受内部和外部威胁。", "desc_en": "The Emperor is the Leader of the Holy Roman Empire. It is the duty of the Emperor to protect the Members from external and internal threats."}, {"id": "divine_emperors", "zh": "神皇", "en": "Divine Emperors", "pillar": "diplomacy", "desc": "在采纳帝皇崇拜信条的希腊多神教【宗教】中，事迹拥有非凡神圣性的【角色】会被认可为神皇。成为神皇的过程被称为封圣。", "desc_en": "A Divine Emperor is a Character that is recognized in a hellenistic Religion following the Imperial Cult aspect by having an extraordinary degree of holiness through their deeds. The process to become a Divine Emperor is known as canonization."}, {"id": "situation_tension", "zh": "紧张度", "en": "Tension", "pillar": "diplomacy", "desc": "用以衡量意大利战争的冲突烈度。该指数每月被动上涨；如果联盟领袖主动发起战争，数值上涨速度会进一步加快。紧张度越高，各联盟领袖越倾向于主动开战，相邻两场战争的间隔也会随之缩短。\n\n如果某一联盟经由和平协议宣告解散，紧张度将大幅下降。", "desc_en": "Measures how inflamed the italian wars have become. It rises passively each month and faster when League leaders are actively at war. Higher Tension makes all League leaders more aggressive and shortens the time between their wars.\n\nTension drops significantly when a League is dissolved via a peace deal."}, {"id": "alliance_bloc", "zh": "联盟集团", "en": "Alliance Bloc", "pillar": "diplomacy", "desc": "联盟集团是【列强】和【区域强权】通过【同盟】结成的联合体。【国家】的盟友越强，其联盟集团饱和度越高，这会提高维持每个【同盟】的【外交容量】成本。\n\n【列强】盟友贡献1.0饱和度，【区域强权】盟友贡献0.5。该成本随加入集团的每个强大【同盟】提高，防止单个【国家】建立起压倒性的强大【同盟】网络。", "desc_en": "An alliance bloc is a coalition of Great Powers and Regional Powers bound together by Alliances. The more powerful allies a Country has, the higher its alliance bloc saturation, which increases the Diplomatic Capacity cost of each Alliance it maintains.\n\nA Great Power ally contributes 1.0 to saturation; a Regional Power ally contributes 0.5. These costs rise for every powerful Ally added to the bloc, discouraging any single Country from accumulating an overwhelming network of powerful Allies."}, {"id": "victory_card", "zh": "胜利卡", "en": "Victory Card", "pillar": "diplomacy", "desc": "胜利卡是【国家】在地图上征服整个【地区】的目标。当整个地区被【拥有】、【控制】并且成为【核心】，国家会获得【分数】。", "desc_en": "A Victory Card is a goal to conquer an entire Area on the map for a Country. When the entire area is Owned, Controlled, and a Core, the country will gain Score."}, {"id": "free_city", "zh": "自由市", "en": "Free City", "pillar": "diplomacy", "desc": "这些是围绕单一、人口稠密的城市建立起来的微型政治实体。在神圣罗马皇帝的保护下，这些城市作为神圣罗马帝国的行政中心。", "desc_en": "These are miniscule political entities which are based around a single, populous city. Protected by the Emperor, these cities serve as administrative hubs within the Holy Roman Empire."}, {"id": "elector", "zh": "选举者", "en": "Elector", "pillar": "diplomacy", "desc": "这些是享有选举【国际组织】下任【领袖】这一【特殊地位】的【成员】。", "desc_en": "These are the Members who enjoy the Special Status which allows them to decide who will be the next Leader of an International Organization."}, {"id": "hre_electoral_college", "zh": "选帝侯团", "en": "Electoral College", "pillar": "diplomacy", "desc": "选帝侯团由神圣罗马帝国的选帝侯组成。\n\n金玺诏书法律根据以下因素影响选帝侯投票：\n——建立【国家等级】的影响力\n——【好感】的影响力减半\n——【列强分数】的影响力变为四倍", "desc_en": "The Electoral College consists of the Elector of the Holy Roman Empire.\n\nThe law of the golden bull influences the way Elector cast their vote due to the following factors:\n- the influence of the Country Rank is established\n- the influence of Opinion is halved\n- the influence of the Great Power Score is quadrupled"}, {"id": "spy_network", "zh": "间谍网", "en": "Spy Network", "pillar": "diplomacy", "desc": "该变量描述了一个【国家】通过线人、奸细和变节者组成的网络对另一国家进行渗透的程度，进而反映出对目标国内部情报的掌握情况。它可被视作一种用于执行各种地下外交行动的资源。", "desc_en": "This describes the extent to which a Country has infiltrated another with a network of informants, double agents, and general turncoats, and thus how much inside knowledge they have of that country. It can be used to perform a variety of insidious diplomatic actions."}, {"id": "subject", "zh": "附属国", "en": "Subject", "pillar": "diplomacy", "desc": "附属国是从属于【宗主国】的【国家】。\n\n它通常在【外交】上受到限制，以换取【战争】中的保护。\n\n附属国也需要缴纳【属国赋税】，并且有一定比例的【列强分数】被【宗主国】抽取。此外，附属国不会成为【列强】。确切规则取决于【属国类型】。\n\n附属国对其【宗主国】有【属国忠诚】和【独立倾向】，二者都表明了他们对其从属关系的当前立场，典型的属国立场有【忠诚】和【不忠】。\n\n任何附属国反过来都可能是其他【国家】的【宗主国】，允许附属国‑【宗主国】关系的长链。\n\n有些附属国是【非主权附属国】。", "desc_en": "A Subject is any Country that is subordinate to an Overlord.\n\nIt typically has limitations on its Diplomacy in return for protection in a War.\n\nSubjects may also suffer Subject Taxation, and have a certain percentage of their Great Power Score exacted by their Overlord. Additionally, a subject may not become a Great Power. The exact rules are dependent on the Subject Type.\n\nSubjects have Subject Loyalty towards their Overlord, and a Liberty Desire - both of which indicate their current stance on their subordination, for example whether they are Loyal or Disloyal.\n\nAny subject may in turn be the Overlord of other Countries, allowing long chains of Subject-Overlord relationships.\n\nSome subjects are Non-Sovereign Subjects."}, {"id": "subject_territory_connectivity", "zh": "附属国领土连通度", "en": "Subject Territory Connectivity", "pillar": "diplomacy", "desc": "附属国领土连通度代表【附属国】领土与其【宗主国】之间的连通程度，数值从0到100不等。\n\n陆地连接从100开始，根据各个地区的平均【控制力】，每经过一个地区都会失去分数。完全控制的地区不会失去连通度；毫无控制的地区每个降低20。\n\n海上连接由三项因素决定：附属国起始港的【海权】存在、港口之间的海军距离以及宗主国的目的港的【海权】存在。【属国类型】可以增加或减少容许的路径距离。\n\n无连接得分为0。\n\n更高的连通度会提高【属国忠诚】。", "desc_en": "Subject Territory Connectivity measures how well connected a Subject's territory is to its Overlord, scored from 0 to 100.\n\nA land connection starts at 100 and loses points for each area traversed based on how low its average Control is. Areas with full control cost nothing; areas with no control reduce the score by up to 20 per area.\n\nA maritime connection is scored from three components: the Maritime Presence at the subject's exit port, the naval distance between the ports, and the Maritime Presence at the overlord's arrival port. Subject Type can increase or reduce the tolerated path distance.\n\nNo connection scores 0.\n\nHigher connectivity increases its Subject Loyalty."}, {"id": "hidden", "zh": "隐匿", "en": "Hidden", "pillar": "diplomacy", "desc": "位于【战争迷雾】内的【单位】对于其他【国家】来说是【隐匿】的。\n\n当一个【单位】处于隐匿状态，其他【国家】甚至不会意识到它的存在，更不用说了解它的编制了。\n\n隐匿的【单位】没有直接的【战斗】加成，但伏击通常会给予战略优势。", "desc_en": "A Unit positioned inside the Fog of War is Hidden to other Countries.\n\nWhen a Unit is hidden, other Countries will not even be aware of its existence, let alone have info on its composition.\n\nHidden Units receive no direct Combat bonus, but ambushes can often give a strategic edge."}, {"id": "hegemony", "zh": "霸权", "en": "Hegemony", "pillar": "diplomacy", "desc": "可以在多个不同领域建立霸权，每个领域中拥有最高等级的【列强】可被认定为霸权，并获得若干的显著增益。\n（详见速查典：hegemony）", "desc_en": "Hegemony is established in different fields, where the Great Power with the greatest level in each field will be proclaimed to be the Hegemon, earning some nice bonuses.\n(See ledger: hegemony)"}, {"id": "non_sovereign_subject", "zh": "非主权附属国", "en": "Non-Sovereign Subject", "pillar": "diplomacy", "desc": "非主权附属国类型的【附属国】不能脱离【宗主国】行动，因此在【外交】上受到限制，不能独立进行【战争】。", "desc_en": "A Non-Sovereign Subject is a type of Subject that cannot act independently of its Overlord and thus has limited capacity to conduct Diplomacy and cannot fight Wars independently."}, {"id": "revolutionary", "zh": "革命", "en": "Revolutionary", "pillar": "diplomacy", "desc": "【革命】是一个【国家】在革命时代（VI）可能面临的一次独特的社会变革。经历了大革命并未能成功捍卫绝对统治权的国家将变为【革命】国家，并解锁强大的【行动】、【改革】和【法律】。作为代价，非【革命】国家将视该国为潜在敌人。", "desc_en": "The Revolution is a unique transformation of the society of a Country during the age 6 revolutions. States which go through the revolution disaster and fail to defend their absolute state might become Revolutionary, granting them access to powerful Actions, Reforms and Laws at the cost of becoming a potential target of non-Revolutionary states."}, {"id": "revolutionary_target", "zh": "革命目标", "en": "Revolutionary Target", "pillar": "diplomacy", "desc": "这是革命运动跳动的心脏，也是最强大的【革命】【国家】。", "desc_en": "This is the beating heart of the Revolution and the most powerful Revolutionary Country."}, {"id": "fleet_basing_rights", "zh": "驻港权", "en": "Fleet Basing Rights", "pillar": "diplomacy", "desc": "驻港权允许一个国家的【舰船】使用另一国家的【港口】，从而扩大了其探索范围，并且可以在外进行【修理】。", "desc_en": "Fleet basing rights allow one country's Ports to be used by another country's Ships, thus extending the range that they can explore and allowing them to Repair away from home."}, {"id": "central_bank", "zh": "中央银行", "en": "Central Bank", "pillar": "economy", "desc": "中央银行是【国家】发行【政府债券】的【首都】【建筑】。它能提供债券容量，降低【债券利息】，并增加发行的每笔债券的规模。", "desc_en": "A central bank is a Building in the Capital that lets a Country issue Government Bonds. It provides bond capacity, reduces Bond Interest, and increases the size of each bond issued."}, {"id": "trading_market", "zh": "交易市场", "en": "Trading Market", "pillar": "economy", "desc": "交易市场是你不【拥有】任何领土，但从foreign buildings with icon获得merchant capacity with icon的market with icon。\n\n这意味着你无需在意该【市场】的good with icon需求、【食物】供应和【人口】，但你可以使用在那里的【贸易容量】来盈利或供应domestic markets with icon。", "desc_en": "A Trading Market is a market with icon in which you do not Own any territory, but have merchant capacity with icon from your foreign buildings with icon.\n\nThis means that you do not necessarily care about the good with icon needs of that Market, its Food supply, or its Population, but you can use your Trade Capacity there to make profit, or to supply your domestic markets with icon."}, {"id": "population", "zh": "人口", "en": "Population", "pillar": "economy", "desc": "一个【地点】的人口是生活在那里的【人群】总数。", "desc_en": "The population of a Location is the total amount Pops living there."}, {"id": "population_growth", "zh": "人口增长", "en": "Population Growth", "pillar": "economy", "desc": "一个【地点】中【人群】的人口增长与一个月内出生和死亡的人口差有关。缺乏【食物】、疾病传播、【围攻】或其他灾难都可能增加死亡人数。", "desc_en": "The Population Growth of the Pops in a Location is connected to how many are born in a month compared to how many died. A lack of Food, the spread of disease, a Siege, or other calamities may increase the number of people that die."}, {"id": "population_capacity", "zh": "人口容量", "en": "Population Capacity", "pillar": "economy", "desc": "该数值是一个【地点】可以支持的【人口】数量。如果【人口】高于该数值将不再增加，如果过高甚至可能减少。", "desc_en": "This is the amount of Population a Location can support. If the Population is higher than this, it will not be able to grow more, and if it is too high it may even decrease."}, {"id": "gdp_per_capita", "zh": "人均GDP", "en": "GDP per capita", "pillar": "economy", "desc": "人均国内生产总值由【国家】的总【收入】除以总【人口】得出。", "desc_en": "The Gross Domestic Product per capita is the total Income of a Country divied by its total Population."}, {"id": "pop", "zh": "人群", "en": "Pop", "pillar": "economy", "desc": "人群是一群同【社会阶级】、同【宗教】、同【文化】的【人】的集合。他们有各类【商品】需求，而他们的【人群满意度】会影响他们居住的【地点】。", "desc_en": "A Pop is a group of People of the same Social Class, Religion, and Culture. They have needs for various Goods, and their Pop Satisfaction impacts the Location they live in."}, {"id": "pop_satisfaction", "zh": "人群满意度", "en": "Pop Satisfaction", "pillar": "economy", "desc": "这代表了【人群】对目前的生活有多满意。它受以下因素影响：\n• 所属阶层的【阶层满意度】\n• 所在【地点】的【叛乱度】\n• 对其【宗教】的【容忍度】\n• 是否是【已接纳文化】\n• 是否满足【人群需求】\n• 【人群需求】的【市场价格】\n• 【国家】主流【文化】对其【文化】的【文化好感】", "desc_en": "This is how happy the Pop is with its situation in life. It is influenced by the following factors:\n• Estate Satisfaction\n• Unrest of the Location\n• The Tolerance of its Religion\n• If it is Accepted Culture or not\n• Access to Pop Needs\n• The Market Price of the Pop Needs\n• The Cultural Opinion of its Culture by the Culture of the Country"}, {"id": "pop_needs", "zh": "人群需求", "en": "Pop Needs", "pillar": "economy", "desc": "pop with icon有一份他们生活所需goods with icon的清单。这取决于他们的【社会阶级】，【文化】，【宗教】和他们生活的位置。比如说，贵族的需要要比【下层阶级】高得多。如果不能满足这些需求，他们的pop satisfaction with icon就会受到影响。\n\n【人群】需求的【商品】数量会随其所在【地点】的development with icon提高而增加。", "desc_en": "A pop with icon has a list of goods with icon they need for their life, which depends on their Social Class, Culture, Religion, and where they live. For instance, nobles have much higher demands than the Lower Class. If they cannot fulfill these needs, their pop satisfaction with icon will suffer.\n\nThe amount of Goods demanded by a Pop increases with the development with icon of the Location where they live."}, {"id": "pop_food_consumption", "zh": "人群食物消耗", "en": "Pop Food Consumption", "pillar": "economy", "desc": "这是一个【人群】每月消耗的【食物】数量。", "desc_en": "This is how much Food a Pop will consume each month."}, {"id": "price", "zh": "价格", "en": "Price", "pillar": "economy", "desc": "花费指的是【国家】为某项活动所付的支出。花费可以是【杜卡特】、【人力】、【稳定度】影响，或其他事物。", "desc_en": "A price is something that a Country pays for an activity. A price can be Ducats, Manpower, impact on Stability, or other things."}, {"id": "price_impact", "zh": "价格影响", "en": "Price Impact", "pillar": "economy", "desc": "属于【人群】的【人群需求】的【商品】【市场价格】对其【人群满意度】有直接影响。", "desc_en": "The Market Price of the Goods that is the Pop Needs of a Pop has a direct impact of its Pop Satisfaction."}, {"id": "supply", "zh": "供给", "en": "Supply", "pillar": "economy", "desc": "这是一个【市场】内，由【建筑】所生产、由【原材料】所采集，以及从其他市场【进口】的某种【商品】的总量。", "desc_en": "This is the quantity of the Good that is produced from Buildings, gathered as Raw Goods, or Imported into the Market."}, {"id": "market_balance", "zh": "供需结余", "en": "Market Balance", "pillar": "economy", "desc": "【商品】的供需结余指的是这件【商品】在特定market with icon内的supply with icon与demand with icon的差额。", "desc_en": "The Market Balance of a Good is the difference between the supply with icon and the demand with icon of that Good inside a market with icon."}, {"id": "creditworthiness", "zh": "信誉", "en": "Creditworthiness", "pillar": "economy", "desc": "信誉代表【国家】偿还【负债】的可信赖程度，范围从0至100，50为中性。更高的数值会降低所有【贷款】的【利息】利率，使外国贷方更愿意提供贷款，更低的数值会提高利率，使贷方不愿出借贷款。【破产】会对信誉产生极大影响，但会随时间缓慢恢复。", "desc_en": "Creditworthiness measures how reliably a Country repays its Debts. It ranges from 0 to 100 with 50 as neutral. Higher values reduce the Interest rate on all Loans and make foreign lenders more willing to offer credit; lower values raise interest rates and make lenders reluctant. Going Bankrupt causes a large drain on creditworthiness that recovers slowly over time."}, {"id": "bond_interest", "zh": "债券利息", "en": "Bond Interest", "pillar": "economy", "desc": "未回购【政府债券】每月需支付的【利息】利率。与【阶层】贷款利息不同，这一花费由国库支出且没有收款方——代表主权债务的持续成本。", "desc_en": "The monthly Interest rate paid on outstanding Government Bonds. Unlike Estate loan interest, this cost is a drain on the treasury with no recipient — it represents the ongoing cost of sovereign debt."}, {"id": "tariffs", "zh": "关税", "en": "Tariffs", "pillar": "economy", "desc": "关税是由【市场所有者】对进出其【市场】的外国【商人】的【商品】贸易征收的费用。它使受影响的贸易路线利润降低，并为【市场所有者】产生每月【收入】。\n\n负关税即为【补贴】：【市场所有者】不征收费用，反而支付金钱提高这些路线的吸引力，以每月花费【杜卡特】的方式吸引贸易流入。\n\n可以在贸易政策界面设定每种【商品】的关税和补贴比率，可以设为自动化，也可以通过【关税豁免】免除特定国家的关税。", "desc_en": "A Tariff is a fee charged by the Market Owner on Goods trade into or out of a Market by foreign Merchants. It makes affected routes less profitable and generates monthly Income for the Market Owner.\n\nA negative tariff is a Subvention: instead of charging a fee, the Market Owner pays to make those routes more attractive, drawing trade in at a monthly Ducats cost.\n\nTariff and subvention rates are set per Good in the Trade Policies view, can be automated, and may be waived for specific countries via Tariff Exemptions."}, {"id": "tariff_exemption", "zh": "关税豁免", "en": "Tariff Exemption", "pillar": "economy", "desc": "关税豁免是一种外交协议，一个【国家】免除对另一国家商人征收的【关税】。被豁免国的商人在授予国的【市场】进行贸易时，无需支付常规的进口或出口费用。\n\n关税豁免可以通过【外交】界面授予或申请，也可由某些【属国类型】关系赋予。", "desc_en": "A tariff exemption is a diplomatic agreement where one Country waives its Tariffs for another country's merchants. Merchants from the exempt country trade through the granting country's Markets without paying the usual import or export fees.\n\nTariff exemptions can be granted or requested through the Diplomacy screen, or conferred by certain Subject Type arrangements."}, {"id": "peasants", "zh": "农民", "en": "Peasants", "pillar": "economy", "desc": "这些人代表了我们统治的普通民众。他们大多依靠自给农业为生，居住在我们的村庄里。", "desc_en": "These represent the common people over whom we rule. Most of them live on subsistence farming, or in our villages."}, {"id": "selling_food", "zh": "出售食物", "en": "Selling Food", "pillar": "economy", "desc": "【省份】有【食物】盈余，并且无法再储存更多时，会在当地【市场】进行出售。只有省份未被【围攻】时可行。\n\n【省份】每月只能等同于【省份】【食物储备】总容量的【食物】。", "desc_en": "When a Province has a surplus of Food and can not store any more of it, they will sell it at their local Market. This is only possible if the province is not under Siege.\n\nA Province can only buy each month as much Food at once as the total capacity of the Food Stockpile of the Province."}, {"id": "distributing_food", "zh": "分发食物", "en": "Distributing Food", "pillar": "economy", "desc": "这将使位于相邻【地点】的【海军】向不能从其当前【地点】或附近【补给站】获取【食物】的任何【陆军】运送【食物】。", "desc_en": "This will send Food from the Navy to any Army in an adjacent Location that can not get Food from its current Location or a nearby Supply Depot."}, {"id": "interest", "zh": "利息", "en": "Interest", "pillar": "economy", "desc": "这是每笔【贷款】都有的费用，按月支付给【贷方】。", "desc_en": "This is a fee that each Loan has, which is paid each month to the Lender."}, {"id": "produced_goods", "zh": "制成品", "en": "Produced Goods", "pillar": "economy", "desc": "这是一种由【人群】在【建筑】中工作生产出的【商品】。在许多情况下，这些建筑需要【原材料】或其他制成品才能发挥作用。", "desc_en": "This is a type of Goods that is produced by Pops working in a Building. In many cases, those buildings require Raw Goods or other Produced Goods to function."}, {"id": "laborers", "zh": "劳工", "en": "Laborers", "pillar": "economy", "desc": "这些人代表了在我们的【城镇】和【乡村】从事体力劳动谋生的民众。他们耕种土地，生产、收获和采集作为国家支柱的【原材料】，或在工厂里从事非技术性劳动。", "desc_en": "These represent the people who work manual labour in our Urban Locations and Rural Locations. They work the land to create, harvest and gather the Raw Goods that are the backbone of the country, or work as unskilled labour in mills."}, {"id": "rgo_pops", "zh": "劳工或奴隶", "en": "Laborers or Slaves", "pillar": "economy", "desc": "这些是可以通过工作收集【原材料】的【社会阶级】。\n\n• 劳工\n• 奴隶", "desc_en": "These are the Social Classes that can work gathering Raw Goods.\n\n• laborers\n• slaves"}, {"id": "rgo", "zh": "原产", "en": "R.G.O.", "pillar": "economy", "desc": "原料生产可缩写为原产。每个【地点】都可以通过矿场、农场、采集场、林场或狩猎场生产一种【原材料】。\n\n每等级的原产可以【雇佣】至多1000名【劳工或奴隶】，最高原产等级取决于地点【发展度】、【革新】和其他因素。", "desc_en": "Initials of Resource Gathering Operations. Each Location has a Raw Good that is created from Mines, Farms, Gathering Operations, Forestry, or Hunting Grounds.\n\nEach level of R.G.O. can Employ up to 1,000 Laborers or Slaves, while the maximum level depends on Development, Advances, and other things."}, {"id": "raw_materials", "zh": "原材料", "en": "Raw Goods", "pillar": "economy", "desc": "每个【地点】【生产】一种原材料。它【生产】的数量取决于该【地点】已经被开发了多少。原材料和【制成品】的不同之处在于它们不需要【建筑】而是完全依赖于【劳工或奴隶】。但是，也有一些原材料可以由【建筑】生产出来。", "desc_en": "Every Location Produces one type of Raw Good. The amount that it Produces depends on how much that Location has been developed. What differs raw materials from Produced Goods is that they do not require Buildings to be produced, and rely solely on Laborers or Slaves. There are some Raw Goods, though, that can also be produced by Buildings."}, {"id": "sell_price", "zh": "售出价格", "en": "Sell Price", "pillar": "economy", "desc": "【商品】在一个【地点】的售出价格。\n如果【市场接入度】较低，售出价格可能会低于【市场价格】。", "desc_en": "The price at which Goods are sold in a Location.\nThe Sell Price can be lower than the Market Price if there is low Market Access."}, {"id": "merchant", "zh": "商人", "en": "Merchant", "pillar": "economy", "desc": "商人是在特定【市场】中活跃，忠于某一【国家】的群体，他们利用自身的【贸易优势】和【贸易容量】，与其他【市场】进行【商品】【贸易】，旨在获取利润。", "desc_en": "Merchants are a company loyal to a Country that are present in a Market and can use their Trade Advantage and Trade Capacity to Trade Goods with another Market in the hope of a profit."}, {"id": "merchant_fraction", "zh": "商人转移", "en": "Merchant Transfer", "pillar": "economy", "desc": "商人转移是一种外交协议，【国家】将其部分【贸易容量】转用于惠及另一国的【市场】。这会迫使出让国的一部分【商人】经由接收国的市场进行贸易，从而提升接收国的贸易量。\n\n商人转移通过附属国互动在【宗主国】与其【附属国】之间建立。", "desc_en": "A merchant transfer is a diplomatic agreement where one Country diverts a portion of its Trade Capacity to benefit another country's Market. This compels some of the granting country's Merchants to trade through the recipient's market, boosting the recipient's trade volume.\n\nMerchant transfers are established between Overlords and their Subjects through subject interactions."}, {"id": "goods", "zh": "商品", "en": "Goods", "pillar": "economy", "desc": "商品可以是由农牧、采集、开采、伐木或狩猎取得的【原材料】，也可以是主要在城镇中生产的【制成品】，\n\n商品中的【食物商品】同样也是【食物】的一大来源。", "desc_en": "Goods can be either Raw Goods that are farmed, gathered, mined, logged, or hunted for, or Produced Goods which are primarily created in towns or cities.\n\nThe Food Goods are also a source of Food."}, {"id": "stockpile", "zh": "商品储备", "en": "Stockpile", "pillar": "economy", "desc": "这是当前某一【市场】储备的【商品】数量。当【供给】高于【需求】时，储备将得到补充；反之则将消耗。市场内的【建筑】、【建造】、【单位】和【人群】将使用储备来满足自身需求。", "desc_en": "This is the quantity of the Good that is currently stored in warehouses in the Market. It increases if Supply is higher than Demand, but will decrease if the opposite. Buildings, Constructions, Units, and Pops in the market will use the stockpile for their needs."}, {"id": "goods_demand", "zh": "商品需求", "en": "Goods Demand", "pillar": "economy", "desc": "这是【建造】、【生产方式】、【人群需求】或其他任何需要所需的【商品】。", "desc_en": "These are the Goods that are required for a Construction, a Production Method, Pop Needs or anything else that requires goods."}, {"id": "domestic_market", "zh": "国内市场", "en": "Domestic Market", "pillar": "economy", "desc": "国内市场是涵盖由你直接管辖locations with icon的market with icon。这类【市场】负责统筹治下【地点】的所有必需品调配，包括政府construction with icon、buildings with icon维护、pop needs with icon以及food with icon供应。\n\n确保国内市场【商品】供应充足是【国家】稳定运转的前提。一旦关键【商品】出现短缺，可能会致使【建筑】项目停工，或是【军团】招募中断。", "desc_en": "A Domestic Market is a market with icon in which you own locations with icon. Your Locations depend on their Market to buy all the stuff they need, be it for government construction with icon, buildings with icon, pop needs with icon, or food with icon.\n\nEnsuring the supply of Goods in your Domestic Markets is paramount for the running of your Country, since you might not be able to build Buildings or recruit Regiments if the necessary Goods are missing."}, {"id": "foreign_market", "zh": "国外市场", "en": "Foreign Market", "pillar": "economy", "desc": "国外市场是你既不【拥有】任何领土，也不拥有任何merchant capacity with icon的market with icon。这意味着你无法与这些市场建立trade with icon，但你仍可以使用trade range with icon内其他【市场】的【贸易容量】与其进行贸易。", "desc_en": "A Foreign Market is a market with icon in which you do not Own any territory, nor have any merchant capacity with icon. That means you cannot conduct trade with icon from them, but you can still trade with them using your Trade Capacity in other Markets within trade range with icon."}, {"id": "treasury", "zh": "国库", "en": "Treasury", "pillar": "economy", "desc": "这是【国家】拥有的【杜卡特】数额。如果变为负数，会自动借一笔【贷款】。如果无法再借取【贷款】，国家会【破产】。", "desc_en": "This is the amount of Ducats a Country has. If it goes negative, a Loan will automatically be taken. If no more Loans can be taken, the country will go Bankrupt."}, {"id": "soldiers", "zh": "士兵", "en": "Soldiers", "pillar": "economy", "desc": "这些人代表了作为【人力】为我们的【陆军】和【守军】服役，以及作为【水手】为我们的【海军】服役的普通民众。", "desc_en": "These represent the common people that provide the Manpower for our Armies and Garrisons as well as Sailors for our Navies."}, {"id": "diplomatic_expense", "zh": "外交支出", "en": "Diplomatic Expense", "pillar": "economy", "desc": "这是从我们【国库】支付给其他【国家】的金钱，或通过【条约】，或通过武力。", "desc_en": "Whether by Treaty or by force, this is the amount being extracted from our Treasury by other Countries."}, {"id": "diplomatic_income", "zh": "外交收入", "en": "Diplomatic Income", "pillar": "economy", "desc": "这是其他【国家】支付给我们【国库】的收入，无论他们是否愿意。", "desc_en": "This is the amount entering our Treasury from other Countries, whether they like it or not."}, {"id": "foreign_building", "zh": "外国建筑", "en": "Foreign Building", "pillar": "economy", "desc": "这是属于非【地点】【拥有者】【国家】的【建筑】。", "desc_en": "This is a Building that belongs to a Country different from the Owner of the Location."}, {"id": "slaves", "zh": "奴隶", "en": "Slaves", "pillar": "economy", "desc": "这些人代表了被剥夺财产的人，他们为主人采集【原材料】或在【种植园】工作，无论是自然繁衍还是在【市场】中购得，他们都被视为商品。", "desc_en": "These represent dispossessed people working gathering Raw Goods or at Plantations for their masters, being treated as commodities either by their birth, or by acquisition in trade Markets."}, {"id": "slavery", "zh": "奴隶制", "en": "Slavery", "pillar": "economy", "desc": "奴隶作为商品在市场上交易，但市场的出货量不能超过其背后奴隶人口的总数。雇佣奴隶的建筑会消耗这一供应，奴隶会随时间推移获得自由，除非他们遭受着奴隶制建筑的控制。", "desc_en": "slaves are traded on the market as the slaves good, but a market can only ship as many as there are slave pops backing it. Buildings that employ slaves draw on this supply, and slaves are freed over time unless held by a slavery building."}, {"id": "subject_taxation", "zh": "属国赋税", "en": "Subject Taxation", "pillar": "economy", "desc": "属国赋税是【宗主国】从各个【附属国】获取的【杜卡特】。确切数额取决于【附属国】的经济基础，然后根据【属国类型】的规则按比例收取。", "desc_en": "Subject Taxation is the Ducats that an Overlord receives from their Subjects. The exact amount is based on the Economy of the Subject, and is then scaled by the rules in the Subject Type."}, {"id": "market", "zh": "市场", "en": "Market", "pillar": "economy", "desc": "市场是【商品】进行买卖交易的场所。\n它以【市场中心】为基础，将根据【市场接入度】和【市场保护】涵盖其他地点。\n市场内的所有地点将专门通过本市场的【商品储备】进行买卖。\n\n【市场】会根据其与你的关联程度以不同颜色标识：\n\n根据你与它们的关系，【市场】可以被分类为四类：【国内市场】、【交易市场】、【国外市场】或【遥远市场】。", "desc_en": "A Market is where Goods are bought and sold.\nIt is based in a Market Center, but includes other locations based on their Market Access and Market Protection.\nAll these locations will exclusively buy from and sell to this market's Stockpile.\n\nMarkets are color-coded depending on how relevant they are to you:\n\nDepending on your relation with them, Markets can be Domestic Markets, Trading Markets, Foreign Markets, or Distant Markets."}, {"id": "market_center", "zh": "市场中心", "en": "Market Center", "pillar": "economy", "desc": "市场中心代表【市场】集中进行经济行为的一处【地点】。该地点的【拥有者】将从中获得一些优势，其中最重要的是，该国能控制谁有资格进入该市场。", "desc_en": "The Location that a Market is centered upon. The Owner of this location gets some benefits from it, but most importantly, they can control who can have access to this market."}, {"id": "market_price", "zh": "市场价格", "en": "Market Price", "pillar": "economy", "desc": "某一【商品】在【市场中心】交易时的价格。\n市场价格会逐渐向【目标价格】调整。\n基于【市场接入度】，其他地点的本地【售出价格】可能会与市场价格不同。", "desc_en": "The price at which a certain Good is traded at the Market Center.\nThe market price is incrementally adjusted towards the Target Price.\nThe Sell Price in other locations may differ from the market price, based on Market Access."}, {"id": "market_attraction", "zh": "市场吸引力", "en": "Market Attraction", "pillar": "economy", "desc": "这一变量影响一个【市场中心】吸引【地点】，以使其参与【市场】的推动力。\n\n它会与【市场保护】相互抵消。", "desc_en": "This impacts how much pull a Market Center has over a Location to make it a part of its Market.\n\nIt is countered by Market Protection."}, {"id": "market_value", "zh": "市场总值", "en": "Market Value", "pillar": "economy", "desc": "这是【市场】中所有月度交易的汇总值。它用于估算该市场的总财富。", "desc_en": "This is the aggregated value of all monthly transactions in a Market. It serves as an estimation of its total wealth."}, {"id": "market_owner", "zh": "市场所有者", "en": "Market Owner", "pillar": "economy", "desc": "【市场】的市场所有者是【拥有】其【市场中心】的【国家】。市场所有者可以摧毁或迁移【市场】，并阻止其他【国家】在其中进行交易。", "desc_en": "The Market Owner of a Market is the Country that Owns its Market Center. The Market Owner can destroy or relocate the Market, and prevent other Countries from trading in it."}, {"id": "market_access", "zh": "市场接入度", "en": "Market Access", "pillar": "economy", "desc": "市场接入度是一个【地点】在【市场】中进行贸易的便利程度。这一变量取决于地点到【市场中心】的距离。\n\n市场接入度的重要体现在三个方面：\n\n• 接入度较高的【市场】拥有更高的market attraction with icon。这意味着【地点】会倾向于加入最近的【市场】。\n\n• 各个【地点】根据其市场接入度依次从【市场】购买goods with icon和food with icon。\n\n• 低市场接入度降低了buildings with icon的【产出】和rgo with icon的利润，从而损害了本地产业。\n\n海洋和【河流】能提高市场接入度，修建【道路】、海军建筑，或是建立一个新【市场】也能改善接入度。", "desc_en": "Market Access represents how easily a Location can interact with its Market, and depends on the distance to the Market Center.\n\nMarket Access is important in three key ways:\n\n• Locations will have higher market attraction with icon towards Markets with higher access. That means that Locations will tend to belong to the closest Market.\n\n• Locations in a Market buy goods with icon and food with icon in order of their Market Access.\n\n• Low Market Access harms local industry by reducing the Output of buildings with icon, and the profit of rgo with icon\n\nMarket Access propagates better over seas and Rivers, and can be improved by constructing Roads and Naval Buildings, or by creating a new Market."}, {"id": "market_language", "zh": "市场语言", "en": "Market Language", "pillar": "economy", "desc": "这是【市场中心】大多数市民所使用的【语言】。\n\n说当地市场语言的市民不会【同化】为不说该市场语言的【文化】。", "desc_en": "This is the Language spoken by the majority of the burghers in the Market Center.\n\nburghers who already speak their market's Market Language are reluctant to give it up. Their Assimilate rate toward cultures that don't share that language is reduced in proportion to the location's Market Access — strong commercial ties slow assimilation, while weak ties barely affect it."}, {"id": "market_food", "zh": "市场食物", "en": "Market Food", "pillar": "economy", "desc": "每个【省份】都会在所属【市场】【购买食物】或【出售食物】，价格取决于市场【商品储备】中的食物数量。省份【拥有者】在交易中产生的花费或利润，意味着食物盈余省份会为拥有者带来【收入】，而赤字省份会带来【支出】。\n\n你可以建立【食物商品】【贸易】，在市场间运送食物。", "desc_en": "Every Province will either Buy Food or Sell Food in the Market they belong to, at a price that depends on the amount of Food stored in the Market Stockpile. The Owner of the Province will be the one affected by the cost or profit of the transaction, meaning that Provinces with a surplus of Food will add to the Income of the Owner, while deficits will result in Expenses.\n\nYou can create Trades of Food Goods to move Food between Markets."}, {"id": "burghers", "zh": "市民", "en": "Burghers", "pillar": "economy", "desc": "这些人代表了【国家】的商业阶层，统治着经济和金融。他们大多数居住于【城镇】，通过在那里的生产性【建筑】提升财富。", "desc_en": "These represent the mercantile strata of the Country, economics and finances being their reign. They are based mostly in Urban Locations, where they promote wealth with productive Buildings."}, {"id": "burgher_trade", "zh": "市民贸易", "en": "Burghers Trading", "pillar": "economy", "desc": "市民会尝试通过【贸易】来满足其【城镇】所在【市场】的【商品】需求。", "desc_en": "The burghers will attempt to address needs for Goods in the Market that their Urban Location is located in, by doing their own Trades."}, {"id": "taxable_profit", "zh": "应税利润", "en": "Taxable Profit", "pillar": "economy", "desc": "【建筑】或【原产】产生的【杜卡特】中受【赋税】影响的部分，【控制力】亦会纳入考量。", "desc_en": "This is the amount of Ducats created by a Building or R.G.O. that is affected by Taxes, taking Control into account."}, {"id": "building", "zh": "建筑", "en": "Building", "pillar": "economy", "desc": "建筑是某一【地点】中特定【建筑类型】的唯一形态。\n\n建筑具有多种功能，诸如增加制成【商品】的【供给】和解锁独特【单位类型】等。建筑的运作效率取决于它们【雇佣】了多少【人群】。\n\n大多数建筑的前期建造需要花费【杜卡特】，随后会在该【地点】的对应【市场】对某一【商品】产生额外的【需求】。如果一座建筑出现亏损，它的【拥有者】可能需要对其进行【补贴】。\n\n【阶层】也可能建造建筑。\n\n建筑可以被拆除。\n\n一座建筑有单个或多个【生产方式】可供更改，这会影响其产出。", "desc_en": "Buildings are unique examples of Building Types in a Location.\n\nBuildings have a wide variety of different functions, from increasing the Supply of manufactured Goods to unlocking unique Unit Types. Their efficiency is based on how many Pops are currently Employed there.\n\nMost buildings have an upfront construction cost in Ducats, and thereafter place additional Demand upon certain Goods in the Location's Market. If a building runs at a loss, its Owner may Subsidize it.\n\nEstates may also construct buildings.\n\nBuildings can also be destroyed.\n\nA building has one or more Production Methods that can be changed, which impacts its output."}, {"id": "building_category", "zh": "建筑类别", "en": "Building Category", "pillar": "economy", "desc": "【建筑类型】被分为不同的类别，这主要是为了识别哪些建筑类型是相似的。", "desc_en": "Building Types are grouped in different Categories, which is primarily to identify which ones are similar."}, {"id": "building_type", "zh": "建筑类型", "en": "Building Type", "pillar": "economy", "desc": "建筑类型是【建筑】的蓝图，并从属于一种【建筑类别】。【建筑】的大多数功能取决于其所属的建筑类型。", "desc_en": "A Building Type is the blueprint of a Building, and belongs to a Building Category. Most of a Building's features are dependent on what Building Type it is."}, {"id": "building_maintenance", "zh": "建筑维护费", "en": "Building Maintenance", "pillar": "economy", "desc": "不生产【商品】的【建筑】会为其【拥有者】产生维护费。该费用取决于建筑所用【商品】的【市场】价格，且会受到所有者【王室力量】的影响。", "desc_en": "Buildings that do not produce Goods incur an upkeep cost for their Owner. The cost depends on the Market Price of the Goods used by the building, and is affected by the Crown Power of the owner."}, {"id": "subsidy_expense", "zh": "建筑补贴", "en": "Building Subsidies", "pillar": "economy", "desc": "有些【建筑】可能并不是盈利的，但我们出于某些原因需要它们生产的【商品】。这些建筑可以得到【补贴】。", "desc_en": "Some Buildings may not be profitable, but we need the Goods they produce for other reasons. Those buildings can be given a Subsidy."}, {"id": "total_population", "zh": "总人口", "en": "Total Population", "pillar": "economy", "desc": "这是生活在一个【国家】的【人群】总数。", "desc_en": "This is the total amount of Pops that live in a Country."}, {"id": "expansion_volatility", "zh": "扩建波动性", "en": "Expansion Volatility", "pillar": "economy", "desc": "当【建筑】扩建时，其投入品需求和产出品供给的增加，都会对【市场】内的【价格】产生影响。\n\n【价格】变动的剧烈程度，取决于这些变化相对于【市场】现有供需的比例。当新的建筑等级在较大幅度上改变平衡时，价格可能会剧烈波动，从而大幅降低【利润】，并使扩建行为带有风险。\n\n扩建波动性通过预判【价格】将如何波动（基于当前目标价格和现行【生产方式】），计算【建筑】提升一级时其后6个月内的【利润】变化，来预先评估风险。", "desc_en": "When a Building is expanded, the added demand from its inputs and the added supply from its outputs both push on Prices within the Market.\n\nHow sharply Prices move depends on how large these changes are relative to the existing supply and demand of the Market. When a new building level shifts that balance by a wide margin, prices might turn unstable and swing aggressively, which can reduce Profit substantially and make expansion risky.\n\nExpansion Volatility estimates this risk in advance by projecting how Prices would swing (based on current target prices and current Production Method) if the Building were raised one level and calculating the change in Profit over the next 6 months."}, {"id": "establishment", "zh": "投产度", "en": "Establishment", "pillar": "economy", "desc": "新建成的【建筑】处于未投产状态。在建筑投产度达到阈值前，建筑产能受限，吞吐量缩水。当投产度高于阈值后，建筑即可满效率运转，并依据自身投产度获得【生产效率】加成，最多可于满投产度时达到+30%。建筑【投产度】每月自然累积，并于建筑关停时流失。", "desc_en": "Newly constructed Buildings start unestablished. Below the establishment threshold, they operate at reduced throughput, both consuming fewer inputs and producing less output. Once the threshold is reached, the building operates at full capacity and begins earning a bonus to Production Efficiency proportional to how established it is, growing up to ++30% at full establishment. Establishment is gained each month and is lost if the building closes."}, {"id": "starving", "zh": "挨饿", "en": "Starving", "pillar": "economy", "desc": "当一个【省份】的【省份食物】没有剩余【食物】时，【人群】将开始挨饿并死亡。\n\n这给予以下影响：\n人口增长 -5%/月、补给上限 -25%、移民吸引力 -1.0、上层阶级容量 -50%、降级速度 +50%", "desc_en": "When a Province has no Food left in the Provincial Food, the Pops will starve and die.\n\nThis gives the following effect:\nPop Growth -5%/mo, Supply Limit -25%, Migration -1.0, Upper Class Cap -50%"}, {"id": "exploration_expense", "zh": "探索花费", "en": "Exploration Cost", "pillar": "economy", "desc": "【探索】任务有一项维护花费，可以通过某些【革新】、【法律】和【特权】，以及【探险家】的【行政能力】能力降低。", "desc_en": "Exploration missions have a maintenance cost that can be reduced by some Advances, Laws, and Privileges, as well as by the Explorer's Administrative Ability ability."}, {"id": "expense", "zh": "支出", "en": "Expense", "pillar": "economy", "desc": "这些是国家的运行成本。它包括【陆军】、【海军】、【贸易】、【艺术家】、【防御工事】、【特许殖民地】等的每月支出。", "desc_en": "These are the running costs of a country. This includes paying for Armies, Navies, Trades, Artists, Fortifications, Colonial Charters, and more each month."}, {"id": "income", "zh": "收入", "en": "Income", "pillar": "economy", "desc": "这是【国家】每月得到的【杜卡特】。它包括来自每个【阶层】的【赋税】，以及来自【贸易】的收入。", "desc_en": "This is the Ducats that a Country gets each month. It includes Taxes from each Estate and income from Trades."}, {"id": "gathering_food", "zh": "收集食物", "en": "Gathering Food", "pillar": "economy", "desc": "正在收集食物的【海军】将从它有【食物获取权】的邻近【地点】取得【食物】，以填满【食物容量】。【海军】随后可以在需要时【分发食物】。", "desc_en": "A Navy that is Gathering Food will take Food from all adjacent Locations it has Food Access to, to fill its Food Capacity. The Navy can then Distribute Food when needed."}, {"id": "government_bond", "zh": "政府债券", "en": "Government Bond", "pillar": "economy", "desc": "政府债券是【国家】发行的一种长期【负债】形式。与【阶层】【贷款】不同，债券没有到期日，也永远不会自动偿还。【国家】会收到先期支付的金钱，并无限期按月支付【债券利息】，直到选择以面值购回债券。", "desc_en": "A government bond is a form of long-term Debt issued by a Country. Unlike an Estate Loan, a bond has no expiry date and is never repaid automatically. The Country receives gold upfront and pays a monthly Bond Interest indefinitely until choosing to redeem the bond by paying back the face value."}, {"id": "clergy", "zh": "教士", "en": "Clerics", "pillar": "economy", "desc": "我们【国家】的精神领袖们，神职【人群】控制着我们的宗教传统，并教育我们的人民了解我们信仰的奥秘。", "desc_en": "The spiritual leaders of our Country, the clergy Pops constitute the group that keeps our religious traditions in check and educates our people in the mysteries of our faith."}, {"id": "common_goods", "zh": "普遍商品", "en": "Common Goods", "pillar": "economy", "desc": "某些【商品】，如石料或黏土可以在任何地方产出而不需要【原产】，被视作普遍商品。之后这些普遍商品会被提供给【市场】。", "desc_en": "Some Goods like stone or clay can be produced everywhere without the need for an R.G.O., and this is considered a common good. As normal Goods, they are then provided to the Market."}, {"id": "min_tax", "zh": "最低税率", "en": "Min Tax", "pillar": "economy", "desc": "这是可以从一个【阶层】获取【赋税】的最低比例。", "desc_en": "This is the lowest percentage of Tax that can be taken from an Estate."}, {"id": "max_tax", "zh": "最高税率", "en": "Max Tax", "pillar": "economy", "desc": "这是可以从一个【阶层】获取【赋税】的最高比例。", "desc_en": "This is the largest percentage of Tax that can be taken from an Estate."}, {"id": "monthly_income_trade_and_tax", "zh": "月度商税收入", "en": "Monthly Trade & Tax Income", "pillar": "economy", "desc": "这是将每月从【贸易】和【赋税】获得的【收入】合计得出的数值。", "desc_en": "This is the monthly Income from Trading and Taxes combined."}, {"id": "effective_supply", "zh": "有效供给", "en": "Effective Supply", "pillar": "economy", "desc": "该数值取决于【市场】内的【商品】【供给】，但减去了【进口】的影响。", "desc_en": "This is based on the Supply of a Good in a Market but the impact of Imports is reduced."}, {"id": "effective_demand", "zh": "有效需求", "en": "Effective Demand", "pillar": "economy", "desc": "该数值取决于【市场】内的【商品】【需求】，但减去了【出口】的影响。", "desc_en": "This is based on the Demand of a Good in a Market but the impact of Exports is reduced."}, {"id": "uncontrolled_wealth", "zh": "未受控财富", "en": "Uncontrolled Wealth", "pillar": "economy", "desc": "地点产出财富中未被国家控制力覆盖的部分，即 地点财富 × (1 − 控制力)。这部分财富不会消失，而是按阶层份额直接流入当地阶层金库，进而资助阶层在低控制力（<75%）地点建造高阶建筑、膨胀政治力量的阶层建筑以及私人军团。", "desc_en": "Location wealth not captured by control (Wealth × (1 - Control)), flowing directly into local estate gold pools."}, {"id": "local_food", "zh": "本地食物", "en": "Local Food", "pillar": "economy", "desc": "这是一处【地点】贡献给【省份食物】的【食物】总量。如果该值为负，此地点将直接从其所在【省份】的其他地点获取食物。\n\n每个地点都会基于其【自给农业】和【食物生产效率】生产一定量的食物，但大部分食物产出自拥有【食物商品】的地点。\n\n每个地点也会根据居住在此的【人口】产生一定的【人群食物消耗】。\n\n【城镇】的本地食物产出通常为负，但只要保证省份食物整体充裕，这将不是问题。", "desc_en": "This is the amount of Food that a Location contributes to the Provincial Food. If it is negative, the Location will simply take Food from other Locations in its Province.\n\nEvery Location produces some Food depending on its Subsistence Agriculture and its Food Productivity, but the bulk of the Food production happens in Locations with Food Goods.\n\nEvery Location will also have some Pop Food Consumption depending on the Population living therein.\n\nUrban Locations will often have negative Local Food balances, but that is not a problem as long as the Provincial Food is positive."}, {"id": "gold", "zh": "杜卡特", "en": "Ducats", "pillar": "economy", "desc": "杜卡特代表流动财富，是每个【国家】的主要货币形式。【国家】当前拥有的杜卡特数额就是其【国库】。\n\n杜卡特可以通过【阶层】和【附属国】的【赋税】产生，可以花费在几乎一切事项上，从建造【建筑】到维持【陆军】。它通过买卖【食物】和【商品】易手，可以用来投入【稳定度】和【宫廷】。", "desc_en": "Representing liquid wealth, it is the primary form of currency in every Country. The amount of Ducats that a Country currently owns is its Treasury.\n\nDucats can be generated through Taxes from Estates and Subjects, and are spent on almost everything, from constructing Buildings to maintaining Armies. They change hands through the purchase and sale of Food and Goods, and can be invested into Stability and the Court."}, {"id": "food_consumption", "zh": "每日食物消耗", "en": "Daily Food Consumption", "pillar": "economy", "desc": "这是【军团】每天会消耗多少【食物】。", "desc_en": "This is how much Food a Regiment will consume each day."}, {"id": "monthly_food", "zh": "每月食物", "en": "Monthly Food", "pillar": "economy", "desc": "领土内未被人群食用的所有【食物】会被贡献给【省份食物】贮藏。", "desc_en": "Any Food that is not consumed by the Pops in a territory is contributed to the Provincial Food storage."}, {"id": "merchant_maritime_power", "zh": "海上贸易优势", "en": "Maritime Trade Advantage", "pillar": "economy", "desc": "海上贸易优势代表了一国的【海军】有效保护与影响海上贸易的能力。它决定了一个【国家】在某【市场】的近岸【海域】拥有的【海上存在】产生的【贸易优势】数值。", "desc_en": "Your Maritime Trade Advantage represents the ability of your Navies to effectively protect and influence seaborne trade. It determines the amount of Trade Advantage that a Country generates from having Maritime Presence in the coastal Seazones of a Market."}, {"id": "sound_toll", "zh": "海峡通行费", "en": "Sound Toll", "pillar": "economy", "desc": "世界上有一些海峡，控制者可以从穿行于其中的【贸易】身上收取一定费用。例如：\n• 厄勒海峡\n• 伊兹密特湾\n\n每处收费海峡都与一处陆地【地点】相关联，你需要控制该地点才能成为海峡的控制者，并且这项【收入】受到你对该【地点】的【控制力】影响。", "desc_en": "There are some straits in the world where the controller can exact a fee from Trades traveling past it. For example:\n• oresund\n• gulf izmit\n• strait hormuz\n\nEach Sound Toll is linked to a specific land Location you need to own in order to be the controller of the strait, and the Income generated from the toll is scaled by your Control in that Location."}, {"id": "society_of_pops", "zh": "游群社会", "en": "Society of Pops", "pillar": "economy", "desc": "游群社会是凭借【人群】存在的【国家】，无需【拥有】整个【地点】。", "desc_en": "A Society of Pops is a Country that exists by virtue of its Pops, and does not need to Own entire Locations."}, {"id": "price_stability", "zh": "物价稳定性", "en": "Price Stability", "pillar": "economy", "desc": "物价稳定性由当前【时代】决定，决定了【目标价格】受【供给】和【需求】影响的最大限度。", "desc_en": "Price Stability is determined by the current Age and decides how much the Target Price is affected by Supply and Demand."}, {"id": "disease", "zh": "疫病", "en": "Disease", "pillar": "economy", "desc": "疫病会对我们的【人口】造成严重破坏。不同疫病有不同的【爆发】概率、方式、传播可能性和死亡率。通过提高【防疫能力】可以减轻它们的可怕影响。", "desc_en": "A disease can wreak havoc on our People. Different diseases have different specified chances of an Outbreak, method, and likelihood of transmission and mortality rate. Their terrible effects can be reduced with Disease Resistance."}, {"id": "disease_outbreak", "zh": "疫病爆发", "en": "Disease Outbreak", "pillar": "economy", "desc": "当一种【疫病】在特定【地点】爆发时，它可以通过各种方式从那里传播出去……在这一过程中，它可能会也可能不会产生受害者。", "desc_en": "When a Disease breaks out in a particular Location, it can then spread from there by various means...and it may or may not claim victims along the way."}, {"id": "target_price", "zh": "目标价格", "en": "Target Price", "pillar": "economy", "desc": "目标价格由【供给】、【需求】和【物价稳定性】共同决定。\n它作为基础价格的乘数随时变动。在极度过剩时，其数值将与【物价稳定性】相等；而在极度紧缺时，其数值取【物价稳定性】的倒数。", "desc_en": "Target Price is determined by Supply, Demand, and Price Stability.\nAs a proportion of the base price, it will scale between Price Stability at overwhelming supply; and 1 / Price Stability at overwhelming demand."}, {"id": "provincial_food", "zh": "省份食物", "en": "Provincial Food", "pillar": "economy", "desc": "这是【省份】储备的【食物】数量。如果【每月食物】为负，省份食物最终会消耗殆尽。如果有赤字，省份会从当地【市场】【购买食物】，如果有盈余，会【出售食物】。\n\n未被【地点】【人群】食用的【食物】会贡献给省份食物贮藏。\n\n该省份的所有领土都可以从贮藏中提取食物来养活其居民。该省份的【陆军】也可以食用贮藏的食物，否则他们将承受【损耗】。", "desc_en": "This is the amount of Food that a Province has stored. If the Monthly Food is negative, it will eventually be depleted. If there is a deficit, the province will Buy Food from the local Market and if there is a surplus, it will Sell Food.\n\nAny Food that is not consumed by the Pops in a Location is contributed to the Provincial Food storage.\n\nAll territories in the Province can draw from this storage to feed their inhabitants. Armies in the province can also consume stored food if they would otherwise suffer Attrition."}, {"id": "bankrupt", "zh": "破产", "en": "Bankrupt", "pillar": "economy", "desc": "【国家】选择破产会清空所有【负债】。然而，这会带来为期5年的严苛【修正】惩罚。\n【国家】在资金枯竭且无法借取更多【贷款】时也会被迫破产。", "desc_en": "A Country choosing to go bankrupt will clear all its Debt. However, this will bring a 5-year period of harsh Modifiers.\nA Country can also be forced into bankruptcy if it runs out of money while unable to take more Loans."}, {"id": "pop_type", "zh": "社会阶级", "en": "Social Class", "pillar": "economy", "desc": "每个【人群】都被定义为属于以下社会阶级之一。\n（详见速查典：pop_type）", "desc_en": "Each Pop is defined to belonging to one of the social classes from below.\n(See ledger: pop_type)"}, {"id": "embargo", "zh": "禁运", "en": "Embargo", "pillar": "economy", "desc": "禁运会阻止一个【国家】在你的【市场】中进行贸易。被禁运的国家无法派商人到你的市场网络中买卖【商品】，从而切断其与你的贸易路线的联系。\n\n禁运可通过外交手段授予或解除。", "desc_en": "An embargo prevents a Country from trading in your Markets. Embargoed nations cannot send merchants to buy or sell Goods in your market network, cutting off their access to your trade routes.\n\nEmbargoes can be granted or removed through diplomacy."}, {"id": "plantation", "zh": "种植园", "en": "Plantation", "pillar": "economy", "desc": "这些特定【建筑】建造的目的是为了开发某些特定类型的【原材料】，例如棉花、糖和烟草。\n\n对于这些建筑，我们特别需要奴隶。", "desc_en": "These are specific Buildings that need to be built to exploit some specific types of Raw Goods like cotton, sugar, and tobacco.\n\nFor these buildings we would specifically need slaves."}, {"id": "tax_base", "zh": "税基", "en": "Tax Base", "pillar": "economy", "desc": "税基是一个【地点】可能受【赋税】影响的【财富】总量，这直接取决于该地区的【控制力】情况。没有【控制力】的财富会直接流向【阶层】，无法被征税。\n\n【财富】依据各【阶层】在该【地点】的【财富份额】进行分配。随后，各个【阶层】根据其【税率】从所获财富中按比例上缴部分至【国库】。", "desc_en": "The Tax Base is the total amount of Wealth that can be affected by Taxes in a Location, which directly depends on its Control. Wealth without Control goes directly to the Estates, and cannot be taxed.\n\nWealth is divided among the Estates according to their Wealth Share in the Location. Every Estate then pays a portion of that Tax Base to the Treasury according to the Tax Rate imposed on them."}, {"id": "tax_efficiency", "zh": "税收效率", "en": "Tax Efficiency", "pillar": "economy", "desc": "这代表了我们【国家】在征收【赋税】时的效率。它影响了对【阶层】征税时【国库】收到的赋税数量。", "desc_en": "This is how efficient our Country is at collecting Tax. It affects the amount of Taxes that reach the Treasury when taxing the Estates."}, {"id": "tax_rate", "zh": "税率", "en": "Tax Rate", "pillar": "economy", "desc": "你向一个【阶层】征收的【赋税】占其【最高税率】的百分比。", "desc_en": "The percentage of the Max Tax an Estate pays as Taxes."}, {"id": "tax_base_ratio", "zh": "税率", "en": "Tax Ratio", "pillar": "economy", "desc": "每一处【地点】都会将自身全部【财富】计入你的【经济基础】。但【杜卡特】仅来自你征收的【税基】，比例偏低就意味着这个国家看似强盛，实际能调用的资金很少，经济产出始终没能流入国库。\n\n这个缺口由【控制力】填补。一处【地点】的损失的【税基】与其【财富】成正比，因此最大的收益来自于在控制力偏低的富裕【地点】提升控制力。这不需要新建建筑或扩大【人群】，只需要更牢固地掌控你已经产出的财富。", "desc_en": "Every Location adds its full Wealth to your Economic Base. Ducats, however, come only from the Tax Base you collect, so a low ratio is the mark of a country that looks powerful but funds little, its economy never reaching the treasury.\n\nThe gap is Control. A Location loses Tax Base in proportion to its Wealth, so the biggest gains come from raising control on rich Locations wherever control is low. It needs no new buildings or Pops, only a firmer grip on wealth you already produce."}, {"id": "economical_base", "zh": "经济基础", "en": "Economic Base", "pillar": "economy", "desc": "这取决于一个【国家】的总【财富】和【人口】，与【控制力】无关。\n\n【附属国】的数量和已接纳的【思潮】也会增加该数值，来自【利息】或【外国建筑】的任何【收入】同样如此。", "desc_en": "This is based on the total Wealth and Population of a Country, regardless of Control.\n\nThe number of Subjects and Institutions embraced also increases it, as well as any Income from Interest, Tariffs or Foreign Buildings."}, {"id": "budget", "zh": "结余", "en": "Balance", "pillar": "economy", "desc": "每月结余取决于【国家】【收入】和【支出】的总额。这一结果影响了国家的【国库】。", "desc_en": "The monthly Balance is based on the total amount of Incomes and Expenses that a Country has. The result impacts the country's Treasury."}, {"id": "subsistence_agriculture", "zh": "自给农业", "en": "Subsistence Agriculture", "pillar": "economy", "desc": "未被一处【原产】或【建筑】雇佣的【劳工或奴隶】将被视为从事自给农业。相对于以原料生产生产【食物商品】，他们将以较小的效率产生食物，这些食物往往勉强能够使他们自给自足。所有【闲置】人口均视为以某种简单的方式收集【食物】，哪怕该【地点】的【原材料】并非与【食物】直接相关。", "desc_en": "Laborers or Slaves that are not employed in an R.G.O. or a Building work in Subsistence Agriculture. They will generate food in smaller quantities than Resource Gathering Operations working Food Goods, often barely enough to cater for their own needs. All Available population is assumed to be doing this simpler form of gathering of Food even if the Location has a Raw Good which is not directly related to Food."}, {"id": "supply_limit", "zh": "补给上限", "en": "Supply Limit", "pillar": "economy", "desc": "这是一个【地点】在不导致【陆军】产生额外【每日食物消耗】的情况下，能补给的【单位损耗权重】上限。", "desc_en": "This is the maximum Unit Weight that a Location can supply without causing additional Daily Food Consumption to the Army."}, {"id": "supply_depot", "zh": "补给站", "en": "Supply Depot", "pillar": "economy", "desc": "【陆军】可以在【敌方】【地点】建造补给站，并在这些【地点】储存【食物】。补给站可为距离2地块范围内的【友方】军队提供补给。", "desc_en": "Armies can create Supply Depots in Hostile Locations, where they can deposit and store Food. Friendly armies can then draw on that supply up to 2 Locations away."}, {"id": "subvention", "zh": "补贴", "en": "Subvention", "pillar": "economy", "desc": "补贴即是一种负【关税】：【市场所有者】不向外国【商人】收取费用，反而支付资金以提高某种【商品】进出【市场】的贸易路线的吸引力，从而吸引更多【贸易】，但每月需消耗国库【杜卡特】。\n\n与【关税】一样，可以在贸易政策界面设置每种【商品】的补贴比率。该机制与建筑【补贴】无关。", "desc_en": "A subvention is a negative Tariff: instead of charging foreign Merchants a fee, the Market Owner pays to make a Good's trade routes into or out of the Market more attractive, drawing more Trade at a monthly Ducats cost to the treasury.\n\nSubvention rates are set per Good in the Trade Policies view, alongside Tariffs. This is unrelated to a building Subsidy."}, {"id": "subsidy", "zh": "补贴", "en": "Subsidy", "pillar": "economy", "desc": "当一座【建筑】无法盈利时，它就不会购买需要的【商品】，也不会起任何作用。【国家】可以选择补贴一座【建筑】，每月支付它足够的【杜卡特】以维持生存。", "desc_en": "When a Building is not profitable, it will not buy the Goods it needs, and will not function. A Country can elect to subsidy a Building, paying it enough Ducats each month to survive."}, {"id": "subsidization", "zh": "补贴", "en": "Subsidization", "pillar": "economy", "desc": "一些生产【建筑】的亏损可以被【拥有者】进行【补贴】。这样的建筑可能产生的任何【杜卡特】损失都会直接从【国家】的【结余】中支付，使其能正常运营。", "desc_en": "Some production Buildings may have their financial losses Subsidized by their Owner. Any Ducats losses that such a building may be incurring will be paid directly from the Country's Balance, allowing it to operate as normal."}, {"id": "literacy", "zh": "识字率", "en": "Literacy", "pillar": "economy", "desc": "这代表了我们【人群】的读写能力。它总体上是有益的，因为我们国家的平均识字率对【研究进度】有积极影响，但也提高了人群需求的【市场价格】对【人群满意度】的影响。", "desc_en": "This is how well our Pops can read and write. It is mostly beneficial, as the average literacy in our country impacts our Research Progress positively, but it also increases the impact from the Market Price of their needs on the Pop Satisfaction."}, {"id": "debt", "zh": "负债", "en": "Debt", "pillar": "economy", "desc": "这是国家的【贷款】总额，包括剩余的所有【利息】。如果负债过高，【国家】会【破产】。", "desc_en": "This is the total amount of Loans a country has, including any remaining Interest. If this debt grows too large, the Country will go Bankrupt."}, {"id": "wealth", "zh": "财富", "en": "Wealth", "pillar": "economy", "desc": "【地点】的财富是指其【原产】和【建筑】通过向【市场】出售其【商品】所获得的综合利润。如果【地点】中有市民存在，【市民贸易】也可能增加地点的财富。\n\n【地点】的财富根据【地点】内各【阶层】的【财富份额】比例进行分配。地点财富乘以【控制力】得出【地点】的【税基】，这是政府可征税的【杜卡特】。没有【控制力】的财富会直接流向【阶层】，无法被征税。", "desc_en": "The Wealth of a Location is the combined profit of its R.G.O. and Buildings from selling their Goods to the Market. If there are burghers present in the Location, Burghers Trading may also increase the Location Wealth.\n\nThe Wealth of a Location is divided among the Estates according to their Wealth Share in the Location. Location Wealth multiplied by Control forms the Tax Base of a Location, which is the Ducats that can be taxed by the government. Wealth without Control goes directly to the Estates, and cannot be taxed."}, {"id": "wealth_share", "zh": "财富份额", "en": "Wealth Share", "pillar": "economy", "desc": "【地点】的【财富】根据【地点】中各【阶层】的相对【人口】进行分配。贵族的人均份额远高于市民，而市民的人均份额又远高于平民.\n\n根据该【地点】的本地平民自主权水平，平民阶层的一部分份额会转移给贵族阶层。", "desc_en": "The Wealth of a Location is distributed among the Estates according to their relative Population in the Location. nobles get a much bigger share per capita than burghers, which in turn get a much bigger share per capita than peasants.\n\nDepending on the local peasant enfranchisment in a Location, a percentage of the share of the peasants estate is transferred to the nobles estate."}, {"id": "wealth_impact", "zh": "财富影响", "en": "Wealth Impact", "pillar": "economy", "desc": "财富影响是指一个【阶层】每月【杜卡特】收入与每月支出之间的比率。\n\n数值高于100%意味着该阶层收入大于支出，从而能够积累财富并投资于【建筑】和【道路】。较低的财富影响会使阶层变得谨慎，限制其仅为自己的【阶层力量】进行建设，并限制其愿意提供的资金数额。", "desc_en": "Wealth Impact is the ratio between an Estate's monthly Ducats income and its monthly expenses.\n\nA value above 100% means the estate earns more than it spends, letting it accumulate wealth and invest in Buildings and Roads. A low Wealth Impact makes an estate cautious, restricting it to building only for its own Estate Power and limiting how much it is willing to fund."}, {"id": "buying_food", "zh": "购买食物", "en": "Buying Food", "pillar": "economy", "desc": "【省份】【食物】较低时，会选择在当地【市场】购买更多食物。只有省份未被【围攻】时可行。\n\n【省份】只能每月购买等同于【省份】【食物储备】总容量的【食物】。", "desc_en": "When a Province has a low amount of Food, they will buy more at their local Market. This is only possible if the province is not under Siege.\n\nA Province can only buy each month as much Food at once as the total capacity of the Food Stockpile of the Province."}, {"id": "nobles", "zh": "贵族", "en": "Nobles", "pillar": "economy", "desc": "这些人代表了血统毋庸置疑的富人和有权势者。领导【国家】的【角色】大多出身于这类【人群】。", "desc_en": "These represent the rich and powerful, with a lineage that can not be doubted. This is the Pops that provide the main Characters to lead the Country."}, {"id": "loan", "zh": "贷款", "en": "Loan", "pillar": "economy", "desc": "贷款是向【贷方】借取的【杜卡特】数量，每月需要偿还【利息】。当【国家】立即需要【杜卡特】时，贷款能帮得上忙。借取贷款会提高【国家】【负债】。", "desc_en": "A loan is the amount of Ducats that has been lent from the Lender and will need to be repaid with a monthly Interest. A loan can be helpful when a Country needs Ducats immediately. Taking a loan will increase the Debt of the Country."}, {"id": "loan_capacity", "zh": "贷款容量", "en": "Loan Capacity", "pillar": "economy", "desc": "这代表了一个【国家】可以在其内部来源【借贷】多少钱。【阶层】可以投资该数值，并获得【国家】为这些贷款支付的所有【利息】。一些【建筑】、【革新】或【政府改革】也可以影响到这一数值。", "desc_en": "This is how much money that a Country can Lend from its internal sources. The Estates can invest in this, and will earn all the Interest that a Country pays from these loans. Some Buildings, Advances or Government Reforms can impact this as well."}, {"id": "trade", "zh": "贸易", "en": "Trade", "pillar": "economy", "desc": "贸易指的是goods with icon在markets with icon之间的流动。【商品】在一个【市场】买入，然后在另一个市场卖出，希望能给贸易的所有者带来【贸易利润】。贸易所需的【贸易容量】取决于【市场】之间的距离以及贸易所处理的【商品】数量。\n\ntrade income with icon会根据estate power with icon分配给王室和estates with icon。基于crown power with icon的相对比例，只有属于王室的那一份会进入【国库】。", "desc_en": "Trade refers to the movement of goods with icon between markets with icon. Goods are bought in one Market and then sold in another, hopefully giving a Trade Profit to the owner of the trade. The amount of Trade Capacity required for the trade depends both on the distance between the Markets and the amount of Goods that the trade is handling.\n\ntrade income with icon is split between the Crown and the estates with icon according to their estate power with icon. Only the percentage of crown power with icon goes to the Treasury."}, {"id": "merchant_power", "zh": "贸易优势", "en": "Trade Advantage", "pillar": "economy", "desc": "在同一个【市场】中，各个【国家】的贸易优势决定了谁能优先获得【出口】权。\n\n如果市场内的【商品】【供给】有限，会按该市场内各个【国家】的贸易优势进行依次交割。", "desc_en": "The Trade Advantage of Countries in a Market determines who will be able to get their Exports fulfilled first.\n\nIf there is a limited amount of Supply of Goods in a Market they get distributed by the Trade Advantage that each Country has in that Market."}, {"id": "trade_profit", "zh": "贸易利润", "en": "Trade Profit", "pillar": "economy", "desc": "贸易利润主要取决于【商品】在【出口市场】和【进口市场】间的【市场价格】差额。此外，维护成本会削减利润，同时一些贸易活动可能还需被迫缴纳【海峡通行费】。", "desc_en": "The profit of trade primarily depends on the difference between the Market Prices of the Goods in the Export Market and the Import Market. There is also a maintenance cost that will reduce the profit, and some trades may be forced to pay a Sound Toll."}, {"id": "merchant_capacity", "zh": "贸易容量", "en": "Trade Capacity", "pillar": "economy", "desc": "这代表了一个【国家】可以在一个【市场】内【出口】或【进口】多少商品。\n\n在一个【市场】中，建立一项【贸易】所使用的【贸易容量】取决于该市场与其他【市场】的距离，以及这项【贸易】所转移的【商品】数量。", "desc_en": "This represents how much a Country can Export and/or Import from a Market.\n\nEach Trade created from this Market uses Trade Capacity depending on the distance to the other Market, and the volume of Goods that Trade is doing."}, {"id": "trade_orders", "zh": "贸易指令", "en": "Trade Orders", "pillar": "economy", "desc": "贸易指令允许你分配【贸易容量】自动【进口】或【出口】特定【商品】，无需设置目的地。AI会每天选择最优路线。", "desc_en": "Trade Orders allow you to manipulate your Trade Capacity in a Market by defining precise conditions for it to operate.\n\nYou can create very specific Orders, like Exporting one Good to one specific Market; or more generic ones, like Importing Food from any available Market. Orders at the top of the list will receive Trade Capacity first. By default, any Trade Capacity that is not being used by an Order will return to the general  Automation.\n\nSee the Link('hints', 'selected hint = hint trade orders', ' Trade Orders') Hint to learn more."}, {"id": "trade_expense", "zh": "贸易支出", "en": "Trade Expense", "pillar": "economy", "desc": "这是花费在【贸易】上的金钱，用来从【市场】购买【商品】，以及支付【贸易路线维护费】。", "desc_en": "This is the money spent on Trades, buying Goods from Markets, and the cost of the Trade Route Maintenance."}, {"id": "trade_income", "zh": "贸易收入", "en": "Trade Income", "pillar": "economy", "desc": "这是向markets with icon出售goods with icon时所得的trades with icon收入。\n\n贸易收入会根据estate power with icon分配给王室和estates with icon。基于crown power with icon的相对比例，只有属于王室的那一份会进入【国库】。", "desc_en": "This is the money gained from trades with icon when selling goods with icon to markets with icon.\n\nTrade income is split between the Crown and the estates with icon according to their estate power with icon. Only the percentage of crown power with icon goes to the Treasury."}, {"id": "trade_range", "zh": "贸易范围", "en": "Trade Range", "pillar": "economy", "desc": "定义了一个【国家】无需额外成本的贸易距离。处于贸易范围内的路线没有额外的运输惩罚。超出范围的路线仍可运行，但运输成本会随着超出范围上限的程度而增加。\n\n更大的贸易范围能使长途路线——例如来自新世界的殖民地商品或来自亚洲的香料——的花费更容易承担，因为每条路线有更多比例被纳入了免费区间。\n\n贸易范围主要通过【革新】来提升，不过一些【法律】、【特权】和【改革】也会对其产生影响。", "desc_en": "Defines how far a Country can trade without extra cost. Routes within Trade Range have no additional transport penalty. Routes that exceed it remain possible, but transport costs increase with the distance beyond the range limit.\n\nA larger Trade Range makes long-haul routes — such as colonial goods from the New World or spices from Asia — more affordable by pushing more of each route into the free zone.\n\nTrade Range can be increased primarily through Advances, although some Laws, Privileges and Reforms may affect it too."}, {"id": "merchant_maintenance", "zh": "贸易路线维护费", "en": "Trade Route Maintenance", "pillar": "economy", "desc": "这代表了在【市场】间进行【贸易】的花费。贸易不是免费的，因为商船和车队需要维护，商人自己也需要获得薪水。\n\n贸易维护费随距离提高，并且受到【海峡通行费】的影响。", "desc_en": "This represents the cost of establishing Trades between Markets. Trading is not free, as the ships, wagons, and caravans need to be maintained, and the merchants themselves need to be paid.\n\nTrade Maintenance increases with distance, and is affected by the existence of Sound Tolls."}, {"id": "tax", "zh": "赋税", "en": "Tax", "pillar": "economy", "desc": "我们可以向国内的各个【阶层】征税，这将增加我们的【国库】，但高额的赋税会降低他们的【阶层满意度】。\n\n可征税的【财富】数额取决于为【阶层】创造【财富】的【地点】的【控制力】。", "desc_en": "We can elect to collect taxes from our Estates. This will increase our Treasury, but higher taxes will decrease their Estate Satisfaction.\n\nThe amount of Wealth that can be taxed depends on the Control of the Locations generating Wealth for the Estates."}, {"id": "migration", "zh": "迁徙", "en": "Migration", "pillar": "economy", "desc": "【人群】将从一个【地点】到另一个之间迁移，前提是他们感觉他们会获得更好的生活。一些【阶层】的人群将不被允许自由迁移，这取决于【国家】给予的【阶层特权】。人群通常只在同【市场】内迁移，除非他们迁移到一个【特许殖民地】，或因【事件】迁移。", "desc_en": "Pops will migrate from one Location to another, if they feel that they would get a better life. Pops from some Estates may not be allowed to migrate freely, depending on what Estate Privileges that Country may have enacted. Pops usually only migrate within the same Market, unless they are migrating to a Colonial Charter, or migrating due to an Event."}, {"id": "migration_attraction", "zh": "迁徙吸引力", "en": "Migration Attraction", "pillar": "economy", "desc": "生活于负移民吸引力【地点】的【人群】会希望迁移到同【市场】内最高移民吸引力的【地点】。某些类型的【人群】，例如奴隶，被永久限制迁移，而另一些如平民，只可以在【阶层特权】允许时进行迁移。", "desc_en": "When Pops live in a Location with negative Migration Attraction, they will want to move to the Location with the highest Migration Attraction in the same Market. Some types of Pops like slaves are permanently restricted from migrating, while others like peasants may only move if they are allowed to by their Estate Privileges."}, {"id": "inflation", "zh": "通货膨胀", "en": "Inflation", "pillar": "economy", "desc": "通货膨胀代表游戏中所有价格的提高。为提高【收入】而进行【铸币】会提高通货膨胀，我们可以通过【内阁行动】来使其降低。", "desc_en": "Inflation represents the increase in all prices in the game. It is increased by Minting more gold to increase our Income, and we can reduce it by a Cabinet Action."}, {"id": "distant_market", "zh": "遥远市场", "en": "Distant Market", "pillar": "economy", "desc": "遥远市场是位于你的所有domestic markets with icontrade range with icon外的market with icon，因此你无法与其建立任何trade with icon。", "desc_en": "A Distant Market is a market with icon that lies beyond the trade range with icon of all of your domestic markets with icon, so you cannot conduct any trade with icon with them."}, {"id": "tribesmen", "zh": "部落民", "en": "Tribesmen", "pillar": "economy", "desc": "这些人代表了居住于【乡村】的群体，他们作为农民，牧羊人或渔猎者自给自足地生活，仍保持着自己分化的社会结构和组织，因此我们很难有效管理。", "desc_en": "These represent communities that populate Rural Locations, subsisting on their own as farmers, shepherds, or hunter-gatherers, and that we can hardly govern, since they maintain their own differentiated social structures and organization."}, {"id": "minting", "zh": "铸币", "en": "Minting", "pillar": "economy", "desc": "铸币可以以【通货膨胀】为代价增加【国库】。如果我们不铸造任何货币，【通货膨胀】会降低。", "desc_en": "Minting is a way to increase our Treasury at the cost of Inflation. If we do not mint any coins, our Inflation may decrease."}, {"id": "unemploy", "zh": "闲置人口", "en": "Available Population", "pillar": "economy", "desc": "【人群】可以受【雇佣】于【建筑】或【原产】。而那些并没有这样做的则被视为可用。", "desc_en": "Pops can be Employed either in a Building or in an R.G.O.. Those that are not doing that are considered Available."}, {"id": "disease_resistance", "zh": "防疫能力", "en": "Disease Resistance", "pillar": "economy", "desc": "该数值影响了【人群】和【角色】从如腺鼠疫等【疫病】中存活的概率。", "desc_en": "This impacts how likely Pops and Characters are to survive Diseases, like the bubonic plague."}, {"id": "estate_building", "zh": "阶层建筑", "en": "Estate Building", "pillar": "economy", "desc": "阶层建筑只能由【阶层】建造和维护的【建筑】，旨在提高其【政治力量】。它们的效果通常与王室的利益相悖。【阶层】更倾向于在【控制力】较低的【地点】建造它们，阶层建筑可以通过【议会议程】摧毁，也可以在高【控制力】的情况下由王室摧毁。\n\n【阶层】也可以建造常规【建筑】和【原产】来增加收入，他们更倾向于低【控制力】【地点】，因为他们在那里已享有高【财富份额】。\n\n【阶层】支付常规4倍的建造【价格】。", "desc_en": "Estate Buildings are Buildings that are only built and maintained by Estates, seeking to increase their Political Power. Their effects usually go against the interests of the crown estate. Estates will prefer to build them in Locations with low Control, and they can be destroyed by the Crown if Control is high enough, or through a Parliament Agenda.\n\nEstates can also build regular Buildings and R.G.O. to increase their income, and to that end they will prefer low Control Locations where they already enjoy a high Wealth Share.\n\nEstates pay 4 times the regular construction Price."}, {"id": "estate_tax_base", "zh": "阶层税基", "en": "Estate Tax Base", "pillar": "economy", "desc": "各【阶层】根据其与其他【阶层】的相对【阶层力量】从每个【地点】获得一定比例【税基】的【杜卡特】。然后再减去【阶层结余】。", "desc_en": "Each Estate gains Ducats by a fraction of Tax Base in each Location that depends on their Estate Power there compared to the other Estates. This is then reduced by the Estates Enrichment."}, {"id": "employ", "zh": "雇佣", "en": "Employ", "pillar": "economy", "desc": "【人群】可以受雇佣于【建筑】或【原产】。一个建筑只能支持一种【社会阶级】，其最大数量取决于建筑类型和建筑等级。", "desc_en": "Pops can be employed either in a Building or in an R.G.O.. A building can only support one Social Class, and the maximum amount depends on the type of building and how many levels it has."}, {"id": "mercenary_expense", "zh": "雇佣佣兵", "en": "Hiring Mercenaries", "pillar": "economy", "desc": "这是我们雇佣【雇佣兵】为我们而战的花费。", "desc_en": "This is our cost from hiring Mercenaries to fight for us."}, {"id": "mercenary_income", "zh": "雇佣兵收入", "en": "Mercenary Income", "pillar": "economy", "desc": "这是我们租借【陆军】或【海军】为其他【国家】提供【雇佣兵】服务所得的【杜卡特】。", "desc_en": "This is the Ducats we get from renting our Armies or Navies as Mercenaries to other Countries."}, {"id": "employment_system", "zh": "雇佣制度", "en": "Employment System", "pillar": "economy", "desc": "这描述了一处【地点】的【建筑】以怎样的优先级填补它们的雇工。", "desc_en": "This describes how Locations fill their Buildings with workers."}, {"id": "demand", "zh": "需求", "en": "Demand", "pillar": "economy", "desc": "这是一个【市场】内，【建筑】投入所需、【人群】生活所需、各类【建造】所需以及【出口】到其他市场的某种【商品】的总量。", "desc_en": "This is the quantity of the Good that Buildings need for their input, how much the Pops need for their lives, how much various Constructions require, and how much Exports are requested from a Market."}, {"id": "food", "zh": "食物", "en": "Food", "pillar": "economy", "desc": "【陆军】行军依靠食物，【人群】生存也依靠食物。没有食物，军队将遭受【损耗】，人群也会【饥饿】。【食物商品】是食物的主要来源，虽然某些【建筑】也起到一定作用。\n\n食物的生产与分销涉及3个层级：\n\n【本地食物】：\n食物在【地点】生产和消费，盈余和短缺会添加到省份食物。\n\n【省份食物】：\n省份食物是最重要的层级。如果【省份】没有生产足够食物来满足其所有地点的消费，省份贮藏会降低。当贮藏耗尽，省份内所有地点都会陷入【饥饿】。但在此之前，省份会尝试从所属市场【购买食物】。\n\n【市场食物】：\n【市场】内所有省份在满贮藏时都会【出售食物】，并在贮藏较低时【购买食物】。只要市场内有足够食物，就不会有人饿死。", "desc_en": "What Armies march on, and what Pops survive on. Without Food, armies will suffer Attrition and Pops will suffer Starvation. Food Goods are the primary source of Food, although some Buildings also play a role.\n\nThere are 3 layers involved in the production and distribution of Food:\n\n Local Food:\nFood is produced and consumed in the Locations, and any excess or deficit is added to the Provincial Food.\n\n Provincial Food:\nThe Provincial Food is the most important layer. If a Province does not produce enough Food to sustain the consumption of all its Locations, the Provincial storage will decrease. When it depletes, all Locations inside a Province will suffer Starvation. But before that happens, the Province will try to Buy Food from its Market.\n\n Market Food:\nAll Provinces in a Market will try to Sell Food when their storage is full, and try to Buy Food when it is low. As long as there is enough Food inside a Market, no one will starve."}, {"id": "food_source", "zh": "食物供应", "en": "Food Source", "pillar": "economy", "desc": "一支【陆军】可以从以下途径收集食物：拥有【食物获取权】的【省份】、友方【补给站】或正在执行【分发食物】的【海军】。", "desc_en": "An Army will gather food from a Province where it has Food Access, a friendly Supply Depot or a Navy that is Distributing Food."}, {"id": "food_stockpile", "zh": "食物储备", "en": "Food Stockpile", "pillar": "economy", "desc": "【地点】每月产生的【食物】盈余将积累在【省份】食物储备中。【省份】每月积累的【食物】盈余将汇总到【市场】食物储备中。\n\n足够充裕的【食物储备】可以在【食物生产效率】下降严重的【冬季】帮助地点避免【饥饿】。\n\n食物储备较高的【省份】也允许其每月大量【购买食物】和【出售食物】。", "desc_en": "Monthly Food surplus from  Locations is stored in the  Province Stockpile. Monthly Food surplus from the Provinces is stored in the  Market Stockpile.\n\nA large enough Food Stockpile may help prevent Starvation during a harsh Winter, when the Food Productivity is low.\n\nA higher Food Stockpile in a  Province also allows it to Buy Food and Sell Food in larger quantities each month."}, {"id": "food_raw_material", "zh": "食物商品", "en": "Food Good", "pillar": "economy", "desc": "一些【原材料】除了和其他【商品】一样具有交易和消费属性，还能产生【食物】。这类商品在【原产】中生产，且能够比【自给农业】更有效地产生食物。\n\n当食物商品被交易，食物也会在【市场】间流动。", "desc_en": "On top of being traded and used like the other Goods, some Raw Goods also produce Food. They are produced in a R.G.O., and constitute a much more efficient source of Food than Subsistence Agriculture.\n\nFood is also moved between Markets when Food Goods are traded."}, {"id": "food_capacity", "zh": "食物容量", "en": "Food Capacity", "pillar": "economy", "desc": "这是【单位】在移动时能携带的【食物】数量。", "desc_en": "This is how much Food a Unit can carry with them as they move."}, {"id": "food_capacity_per_strength", "zh": "食物容量", "en": "Food Capacity", "pillar": "economy", "desc": "这是【单位】在移动时能携带的【食物】数量。", "desc_en": "This is how much Food a Unit can carry with them as they move."}, {"id": "food_consumption_per_strength", "zh": "食物消耗", "en": "Food Consumption", "pillar": "economy", "desc": "这是【军团】每天会消耗多少【食物】。", "desc_en": "This is how much Food a Regiment will consume each day."}, {"id": "food_productivity", "zh": "食物生产效率", "en": "Food Productivity", "pillar": "economy", "desc": "某一【地点】的食物生产效率将影响它产生【食物】的速度。\n\n这一效率主要取决于地点的地理条件，当然一些【法律】、【社会价值观】和【革新】也能对其产生影响。【城镇】生产食物的效率显著低于【乡村】。", "desc_en": "The Food Productivity of a Location impacts how efficient it is at producing Food.\n\nIt depends mostly on the geography of the Location, but some Laws, Societal Values, and Advances can also affect it. Urban Locations are less efficient at producing Food than Rural Locations."}, {"id": "food_decay", "zh": "食物腐坏", "en": "Food Decay", "pillar": "economy", "desc": "【食物】无法永久保存，随着时间的推移，每个月都会有部分食物变质腐败。", "desc_en": "Food does not last forever, and some are spoiled every month."}, {"id": "food_access", "zh": "食物获取权", "en": "Food Access", "pillar": "economy", "desc": "食物获取权允许我们的【陆军】和【海军】从其他【国家】的【地点】收集【食物】。", "desc_en": "Food Access allows our Armies and Navies to gather Food from the Locations of the other Countries."}, {"id": "food_storage", "zh": "食物贮藏", "en": "Food Storage", "pillar": "economy", "desc": "这是【军团】或【舰船】能携带的【食物】数量。", "desc_en": "This is the amount of Food that a Regiment or Ship can carry with them."}, {"id": "food_storage_per_strength", "zh": "食物贮藏", "en": "Food Storage", "pillar": "economy", "desc": "这是【军团】或【舰船】能携带的【食物】数量。", "desc_en": "This is the amount of Food that a Regiment or Ship can carry with them."}, {"id": "d10", "zh": "D10", "en": "D10", "pillar": "military", "desc": "D10是在【战斗】中使用的十面骰子，用来决定一方表现得有多好。", "desc_en": "A D10 is a ten-sided dice roll used in Combat, to determine how well a side is doing."}, {"id": "d100", "zh": "D100", "en": "D100", "pillar": "military", "desc": "D100是用于检测百分比概率的一百面骰子。", "desc_en": "A D100 is a hundred-sided dice roll used to check percentage-based chances."}, {"id": "d20", "zh": "D20", "en": "D20", "pillar": "military", "desc": "D20是在【战斗】中使用的二十面骰子，用以判定【军团】或【舰船】是否能从【预备队】加入战斗。", "desc_en": "A D20 is a twenty-sided dice roll used in Combat, when a Regiment or Ship leaves the Reserves."}, {"id": "non_avoidable_attrition", "zh": "不可避免损耗", "en": "Unavoidable Attrition", "pillar": "military", "desc": "一般而言，当一国的【陆军】驻扎在该国【拥有】并【控制】的【要塞】或毗邻【控制区】内时，通常不会遭受【损耗】。但是某些不可抗力因素，如黑死病，导致的损耗是无法避免的。", "desc_en": "Usually Armies do not take Attrition if they are within the Zone of Control of a Fort owned and controlled by themselves, their direct Subjects, or their direct Overlord, but some things like the black death can not be avoided like that."}, {"id": "center", "zh": "中军", "en": "Center", "pillar": "military", "desc": "这是一个【单位】的中央【阵位】。如果中央没有敌军，他们就可以轻松抵达左【侧翼】或右【侧翼】。", "desc_en": "This is the center Section of a Unit. If there is no opponent in the center, they can easily reach either the left Flank or the right Flank."}, {"id": "initiative", "zh": "主动性", "en": "Initiative", "pillar": "military", "desc": "主动性是【军团】在【战斗】的【作战阶段】会【接战】的概率。\n\n每个小时，假如有足够的【战斗宽度】，所有当前未【接战】的【军团】会尝试加入战斗。\n\n概率计算方式为（主动性×2.5%（日步）/ 1%（时步））+（2.5%（日步）/ 1%（时步）×战斗的小时数），如果概率高于【D100】，那么【军团】会【接战】。\n\n通常来说，轻型和远程【军团】拥有最高的主动性。", "desc_en": "Initiative is the chance that a Regiment will Engage during the Combat Phase of Combat.\n\nEvery day, assuming there is enough Frontage available, all the Regiments not currently Engaged will attempt to join the fray.\n\nThe chance is calculated as (Initiative * 0.025) + (0.03 * number of days in combat); if the chance is higher than a D100, then the Regiment becomes Engaged in the fighting.\n\nIn general, light and ranged Regiments have the highest Initiative."}, {"id": "manpower", "zh": "人力", "en": "Manpower", "pillar": "military", "desc": "人力代表了一个【国家】可用于供养常备【陆军】的闲散人员的限度。\n\n训练和维持正规【军团】需要消耗人力。通常地，这一军种比【陆军征召兵】更具战斗力。\n\n通过建造一些人力【建筑】或研发特定【革新】可提高获取人力的速度。", "desc_en": "Manpower represents the limit of how many blaggards and scoundrels a Country can support in its standing Army.\n\nManpower is expended when training and maintaining professional Regiments, which are usually more effective than Army Levies.\n\nThe rate at which Manpower is gained can be increased by constructing Manpower Buildings or researching certain Advances."}, {"id": "combat_phase", "zh": "作战阶段", "en": "Combat Phase", "pillar": "military", "desc": "作战阶段是发生于最初的【轰击阶段】后的主要【战斗】【阶段】。【军团】和【舰船】将尝试与【敌人】【接战】。", "desc_en": "The Combat Phase is the main Phase of Combat which takes place after the initial Bombard Phase. Regiments or Ships will attempt to Engage their War Enemy counterparts."}, {"id": "flank", "zh": "侧翼", "en": "Flank", "pillar": "military", "desc": "侧翼是【陆军】【中军】两侧的【阵位】。左侧阵位通常与敌人的右侧阵位交战，而右侧阵位通常与敌人的左侧阵位交战。不过，【侧翼攻击能力】也允许打击相邻的阵位。", "desc_en": "Flanks are the Sections in an Army besides the Center. The left Section usually fights the right Section of the opponent and the right Section usually fights the left Section of the opponent. However, Flanking Ability also allows damaging adjacent Sections."}, {"id": "secure_flanks", "zh": "侧翼保护", "en": "Secure Flanks", "pillar": "military", "desc": "当相邻【阵位】存在【友方】部队时会提供防御增益。如果两翼都有保护，增益会翻倍。", "desc_en": "This provides a defensive bonus when there are Friendly troops in a neighboring Section. If both flanks are secure, the bonus is doubled."}, {"id": "secure_flanks_defense", "zh": "侧翼保护防御", "en": "Secure Flanks Defense", "pillar": "military", "desc": "当相邻【阵位】存在【友方】部队时会提供防御增益。如果两翼都有保护，增益会翻倍。", "desc_en": "This provides a defensive bonus when there are Friendly troops in a neighboring Section. If both flanks are secure, the bonus is doubled."}, {"id": "repair", "zh": "修理", "en": "Repair", "pillar": "military", "desc": "当【舰船】受损时，它可以在我们拥有的【港口】或我们拥有【驻港权】的地方进行修复，从所属【国家】获取【水手】和【杜卡特】。", "desc_en": "When a Ship is damaged, it can be repaired in one of our own Ports or where we have Fleet Basing Rights, by drawing Sailors and Ducats from its Country."}, {"id": "truce", "zh": "停战", "en": "Truce", "pillar": "military", "desc": "两个【国家】签署【和平条约】时，会自动建立停战。对处于停战协议的国家发动【战争】会造成严重惩罚。一些外交行动对与我们停战的国家会完全禁用。", "desc_en": "A truce is automatically created when a Peace Treaty is signed between two Countries. Declaring War on someone we have a truce with will have severe penalties. Some diplomatic actions may be entirely blocked with nations we have a truce with."}, {"id": "strength", "zh": "兵力", "en": "Strength", "pillar": "military", "desc": "这是一支【军团】当前拥有的人数。", "desc_en": "This how many men a Regiment currently has."}, {"id": "army_based", "zh": "兵团国家", "en": "Army Based Country", "pillar": "military", "desc": "兵团国家是可以【拥有】【地点】，但是其存在完全依赖于自己的【陆军】的【国家】。如果军队被摧毁，那么国家就会覆灭。", "desc_en": "An Army Based Country is a Country that can Own Locations, but its existence is relying entirely on its Armies. If those are destroyed, then the Country collapses."}, {"id": "combined_arms", "zh": "兵种混编", "en": "Combined Arms", "pillar": "military", "desc": "拥有均衡【单位类别】构成的【陆军】和【海军】，在【战斗】中每涉及一种额外的类别，都会获得【战斗力】加成。加成的强度可能因科技及其他因素而有所不同。\n\n要获得兵种混编加成，一支【陆军】中同一类别的【军团】占比不能达到50%或以上。不同【单位类别】的例子包括轻型战舰与重型战舰，或轻步兵与重骑兵。", "desc_en": "Armies and Navies with balanced compositions of Unit Categories receive a bonus to their Combat Power in Battle for each additional category involved. The strenght of the bonus may vary depending on technology and other sources.\n\nIn order to benefit from the Combined Arms bonus, an Army cannot have 50% or more Regiments of the same category. Examples of different Unit Categories are navy light ship and navy heavy ship, or army light infantry and army heavy cavalry."}, {"id": "regiment", "zh": "军团", "en": "Regiment", "pillar": "military", "desc": "军团是一支【陆军】的基础组成单位。每队军团拥有以【人力】补充的【最大兵力】和特定【单位类型】，并可归类为【陆军征召兵】、【雇佣兵】或【正规军团】其中之一。", "desc_en": "A regiment is the building block of an Army. Each has a Maximum Strength of Manpower and is of a specified Unit Type. They can either be an Army Levy, a Mercenary, or a Regular Regiment."}, {"id": "loot", "zh": "劫掠", "en": "Loot", "pillar": "military", "desc": "【陆军】【占领】【地点】后会从中掠夺【杜卡特】，并给予该【地点】大概12个月的被劫掠【修正】。", "desc_en": "When Armies Occupy Locations they will steal Ducats from it, and give the Location Looted Modifier for about 12 months."}, {"id": "unit", "zh": "单位", "en": "Unit", "pillar": "military", "desc": "一个单位可以是【陆军】也可以是【海军】。单位由【子单位】组成。", "desc_en": "A unit can either be an Army or a Navy. It is made up of Subunits."}, {"id": "unit_modifier", "zh": "单位修正", "en": "Unit Modifier", "pillar": "military", "desc": "作用于【单位】的【修正】。", "desc_en": "A Modifier that applies to a particular Unit."}, {"id": "unit_weight", "zh": "单位损耗权重", "en": "Unit Weight", "pillar": "military", "desc": "这是一项累计值，取决于【军团】的当前【兵力】，以及其【单位类型】。\n在计算【损耗】时，该数值会与当前【地点】的【补给上限】进行直接比较。", "desc_en": "This is an accumulated value that depends on the current Strength of the Regiment and which Unit Type it is.\nThis is compared directly to the Supply Limit in the current Location when calculating Attrition."}, {"id": "unit_template", "zh": "单位模板", "en": "Unit Template", "pillar": "military", "desc": "单位模版是一系列可以用来直接招募不同【单位】的【单位类型】的集合。它可以用来创建【军团】和【舰船】。", "desc_en": "A unit template is a collection of Unit Types that can be used to recruit different Units directly. It can be used to create both Regiments and Ships."}, {"id": "unit_category", "zh": "单位类别", "en": "Unit Category", "pillar": "military", "desc": "【军团】或【舰船】总是属于以下类别之一。\n（详见速查典：unit_category）", "desc_en": "A Regiment or Ship always belongs to one of the following categories.\n(See ledger: unit_category)"}, {"id": "unit_type", "zh": "单位类型", "en": "Unit Type", "pillar": "military", "desc": "每个【单位类别】都包含许多单位的不同衍生类型。不同的类型来自【革新】、【文化】或其他来源。类型使得单位具有独特性，并赋予其能力和属性。例如，【舰船】包括柯克帆船、双层战列舰和三桅帆船，而【军团】则包括火绳枪兵和骑士骑兵等多种类型。", "desc_en": "Each Unit Category contains lots of variations when it comes to type. Different types come from Advances, Culture, or from other sources. The type is what makes a unit unique, and what gives it its abilities and attributes. Some examples for Ships include n cog, n twodecker, and n xebec, while Regiments include a arquebusiers and a cavaliers amongst many more."}, {"id": "occupation", "zh": "占领", "en": "Occupation", "pillar": "military", "desc": "占领是指【地点】的【控制者】与其【拥有者】不同。这通常发生在一个【地点】处于由【战争对手】【控制】的【防御工事】的【控制区】内，或者当一支【陆军】成功【围攻】该地点的情况下。\n\n在许多情况下，一个【地点】需要被占领才能被加入到【和平条约】中。", "desc_en": "Occupation is when the Controller of a Location is different from its Owner. This happens when a Location falls within the Zone of Control of a Fortification that is Controlled by an War Enemy, or when an Army successfully Sieges the location.\n\nIn many cases, a Location needs to be occupied before it can be added to a Peace Treaty."}, {"id": "war_exhaustion", "zh": "厌战度", "en": "War Exhaustion", "pillar": "military", "desc": "厌战度代表我们【国家】被【战争】破坏的程度。如果足够高，我们将被迫签署【和平条约】。这些是1厌战度时的效果：\n陆海军士气 -2.5%、全局阶层满意度目标 -1%、全局防御 -2.5%（每 1 点厌战）", "desc_en": "War Exhaustion represents how much our Country has been ravaged by War. If it is high enough, we will be forced to sign a Peace Treaty. These are the effects at 1 War Exhaustion:\nLand/Naval Morale -2.5%, Estate Target Satisfaction -1%, Global Defensive -2.5% per point"}, {"id": "combat_speed", "zh": "参战速度", "en": "Combat Speed", "pillar": "military", "desc": "这是在【战斗】中从【预备队】移动到前排【阵位】的能力。对于【舰船】，它还影响受损船只撤离当前【阵位】的速度。", "desc_en": "This is the ability to move from the Reserves to any other Section inside a Battle. For Ships it also impacts how quickly a damaged one can leave the current Section to retreat."}, {"id": "anti_piracy_warfare", "zh": "反海盗影响", "en": "Anti-Piracy Impact", "pillar": "military", "desc": "这是【舰船】会对其地区内【私掠者】产生的影响。", "desc_en": "This is the effect the Ship will have on Privateers in their area."}, {"id": "mercenary_contract_length", "zh": "合同期限", "en": "Contract Length", "pillar": "military", "desc": "这是佣兵团为雇主服务的月份数。", "desc_en": "This is the amount of months that this company will serve at the behest of its contractor."}, {"id": "peace", "zh": "和平", "en": "Peace", "pillar": "military", "desc": "和平是指【国家】未处于任何进行中的【战争】的状态。", "desc_en": "Peace is the status in which the Country is not in any ongoing War."}, {"id": "peace_offer", "zh": "和平提议", "en": "Peace Offer", "pillar": "military", "desc": "这是一项结束两国或多个【国家】间正在进行中的【战争】的外交行动。在和平提议中，一方能以【和平条约】的形式向另一方提出条件。一旦另一方接受，和平协议就将签署，【战争】将宣告结束。\n\n一个【国家】在和平条约中可提出的条件取决于他们的【战争分数】。", "desc_en": "It is a diplomatic action that puts an end to an ongoing War between two or more Countries. In it, one side will be able to state their conditions to the other side as Peace Treaties. Once the other side accepts them, the peace will be signed and the War will end.\n\nHow much a Country will be able to get out of a peace treaty will depend on its Warscore."}, {"id": "peace_treaty", "zh": "和平条约", "en": "Peace Treaty", "pillar": "military", "desc": "这是【和平提议】的条件，包括两个【国家】间的【地点】割让、【杜卡特】的赔偿和其他特殊条约，例如放弃殖民宣称、接管市场中心或羞辱。", "desc_en": "This will be the conditions of a Peace Offer, which include the transfer of a Location between two Countries, or a tribute in Ducats between them, or even some special treaties like abandon colonial claim, execute ruler, or peace humiliate."}, {"id": "siege", "zh": "围攻", "en": "Siege", "pillar": "military", "desc": "如果【陆军】所到达的【地点】当地【控制者】与该陆军是【战争对手】，就会发生围攻。\n\n对于无【防御工事】地点的围攻将花费一个月，而对有防御工事地点的围攻将耗日良久，这取决于防御工事等级。\n\n如果陆军攻下了一处由战争对手【拥有】的地点，它将被【占领】并提升陆军拥有者的【战争分数】。\n\n要使【围攻】得到推进，攻城部队人数至少应与【守军】人数相当。对于未建设【防御工事】的【地点】，至少需要100人的部队。", "desc_en": "A siege occurs when an Army arrives in a Location when the Controller and the Army are War Enemies.\n\nA siege against a Location without a Fortification will take about a month, but if there is a Fortification present it will take far longer, depending on the level of the Fortification.\n\nIf the Army wins against a Location Owned by the War Enemy, it will then become Occupied and it will increase the Warscore for the Army's Owner.\n\nFor a Siege to progress there needs to be at least as many men besieging it as the number of men in the Garrison. For a Location without Fortifications, there needs to be at least 100 men."}, {"id": "land_ownership_rule", "zh": "土地所有权规则", "en": "Land Ownership Rule", "pillar": "military", "desc": "一些【国际组织】可以直接拥有【地点】。土地所有权规则便是用于规定这种所有权的性质，以及适用于这些地点的【修正】类型。", "desc_en": "Some International Organizations are capable of owning Locations. The Land Ownership Rule describes the nature of this ownership, and what Modifiers apply on these Locations."}, {"id": "morale", "zh": "士气", "en": "Morale", "pillar": "military", "desc": "士气代表一支【陆军】或【海军】在放弃前能战斗多久。\n\n在【战斗】中，所有【军团】和【舰船】会对对手造成【士气打击】，具体效果会受到对手【士气承伤】的修正。一旦士气归零，陆军或海军会【撤退】并输掉【战斗】。", "desc_en": "Morale is how long an Army or Navy will fight before giving up.\n\nIn Battle, every Regiment or Ship inflicts Morale Damage Done upon its opponent, the effect of which is modified by the opponent's Morale Damage Taken. Once Morale hits zero, the Army or Navy will Retreat and lose the Battle."}, {"id": "sub_unit", "zh": "子单位", "en": "Subunit", "pillar": "military", "desc": "子单位是一支【单位】下特定的部队，以【军团】或【舰船】的形式参与作战。他们总是属于某一特定的【单位类型】，同时也归属于某个【单位类别】。", "desc_en": "Subunits are the distinct troops in the Unit which fight either as Regiments or as Ships. They are always of a specific Unit Type and as such belong to a Unit Category."}, {"id": "garrison", "zh": "守军", "en": "Garrison", "pillar": "military", "desc": "这些是正在守卫某一【地点】上【防御工事】的士兵。当他们全军覆没，或是【士气】归零时，防守方将输掉【围攻】。\n\n要使【围攻】得到推进，攻城部队人数至少应与【守军】人数相当。对于未建设【防御工事】的【地点】，至少需要100人的部队。", "desc_en": "These are the soldiers that are working with defending the Fortifications of a Location. When they are all killed, or their Morale is gone, the Siege will be lost for the defender.\n\nFor a Siege to progress there needs to be at least as many men besieging it as the number of men in the Garrison. For a Location without Fortifications, there needs to be at least 100 men."}, {"id": "casus_belli", "zh": "宣战理由", "en": "Casus Belli", "pillar": "military", "desc": "字面的意思是开战的原因，意味着一个【国家】发动【战争】的正当理由。根据所用宣战理由的不同，【战争】的类型和【战争目标】都将有所差别。", "desc_en": "Literally meaning Cause for War, it is the justification a Country uses for starting a War. Depending on the Casus Belli used, the type of War and the Wargoal will be different."}, {"id": "blockade", "zh": "封锁", "en": "Blockade", "pillar": "military", "desc": "封锁指的是【敌方】【海军】存在于【港口】外的【海域】，需要的【舰船】数量取决于受影响【港口】的【人口】和【发展度】。\n\n封锁的最重要效果包括：\n• 降低【食物】产出\n• 降低【海上存在】\n• 降低【发展度】\n• 降低【控制力】\n• 降低【繁荣度】", "desc_en": "A blockade is when a Hostile Navy is present in the Seazone outside a Port, the amount of Ships needed depends on the Population and Development of the Ports affected.\n\nThe most important effects of blockade:\n• Reduce Food Production\n• Reduce Maritime Presence\n• Reduce Development\n• Reduce Control\n• Reduce Prosperity"}, {"id": "blockade_capacity", "zh": "封锁能力", "en": "Blockade Capacity", "pillar": "military", "desc": "这决定了一艘【舰船】在封锁时的表现有多好。该数值会与目标【地点】的一项数值进行直接对比，后者由目标地点的【发展度】、【人口】、【进口】和【出口】决定。", "desc_en": "This determines how good a Ship is at blockading. This is directly compared to a value in the target Location depending on its Development, Population, Imports, and Exports it has."}, {"id": "regular_army", "zh": "常备军", "en": "Regular Army", "pillar": "military", "desc": "【国家】的常备【陆军】，不包括【征召兵】。", "desc_en": "Refers to the standing Army that a Country has, excluding Levies."}, {"id": "assault", "zh": "强攻", "en": "Assault", "pillar": "military", "desc": "强攻是指【围攻】部队猛攻【防御工事】以期快速占领的行为。强攻可能会付出相当大的代价，因为进攻方将承受重大伤亡。", "desc_en": "An assault is when the attacker in a Siege tries to storm the Fortification in order to take it as quickly as possible. An assault can be rather costly, as the attacker will take heavy casualties."}, {"id": "levy", "zh": "征召兵", "en": "Levy", "pillar": "military", "desc": "征召兵是通过召集【人群】进行组织军事单位。可以是【陆军征召兵】或【海军征召兵】。", "desc_en": "A levy is a military unit that a Pop will raise when called. It is either an Army Levy or a Naval Levy."}, {"id": "levy_combat_efficiency", "zh": "征召兵作战效率", "en": "Levy Combat Efficiency", "pillar": "military", "desc": "这影响相较于【正规军】军团，一支【征召兵】【军团】在【战斗】中的表现。", "desc_en": "This impacts how effective will a Regiment of Levies perform in Combat compared to a Regular Regiment."}, {"id": "total_strength", "zh": "总兵力", "en": "Total Strength", "pillar": "military", "desc": "这是一支【陆军】总共的人数，来自于各【军团】的单独【兵力】全部相加。", "desc_en": "This how many men an Army has in total, adding together all the individual Strength of each Regiment."}, {"id": "war", "zh": "战争", "en": "War", "pillar": "military", "desc": "当一个【国家】花费【外交官】挑起与另一国家的冲突时，战争就此开始。与任意一方【同盟】的国家可能被召唤加入战争。\n\n当处于战争状态时，双方的【陆军】和【海军】将在相遇时爆发【战斗】。【陆军】能够【围攻】【战争对手】的【地点】，【海军】能够【封锁】敌人的【港口】。\n\n战争将持续到【和平条约】签署，随后参战【国家】之间将恢复【和平】状态。", "desc_en": "A war is created when one Country uses a Diplomat on another country to start a conflict. Countries that are Allied with either side may get called into the war.\n\nDuring a war, Armies and Navies from each side that encounter each other will Battle each other. Armies will be able to Siege the War Enemies Locations, while Navies can Blockade their Ports.\n\nA war continue until a Peace Treaty is signed, and Peace reigns again between the involved Countries."}, {"id": "peace_cost", "zh": "战争分数花费", "en": "Peace Offer value", "pillar": "military", "desc": "这是在【和平提议】中添加一项【和平条约】所需要的花费。通常其总额将和【战争分数】进行权衡，从而决定其他【国家】是否会接受。", "desc_en": "This is how much a Peace Treaty will cost to add to a Peace Offer. It is usually compared to the Warscore to determine whether the other Country would accept it or not."}, {"id": "enemy", "zh": "战争对手", "en": "War Enemy", "pillar": "military", "desc": "处于【战争】状态的两个【国家】将视彼此为敌人，当它们的【陆军】或【海军】在同一地点或海域相遇，将爆发【战斗】。\n\n【叛军】和【海盗】被所有国家视为敌人。", "desc_en": "Two Countries that are at War against each other will view each other as enemies, and they will Battle when their Armies or Navies meet.\n\nRebels and Pirates are enemies to all."}, {"id": "war_enthusiasm", "zh": "战争热情", "en": "War Enthusiasm", "pillar": "military", "desc": "这一概念描述了一个【国家】将【战争】继续进行下去的意愿。", "desc_en": "This describes the willingness of a Country to continue to pursue this War."}, {"id": "war_ally", "zh": "战争盟友", "en": "War Allies", "pillar": "military", "desc": "这些是在某场【战争】中站在同一方互相支援的【国家】。", "desc_en": "These are Countries that are helping each other on the same side of a War."}, {"id": "war_goal", "zh": "战争目标", "en": "Wargoal", "pillar": "military", "desc": "战争目标是为某个【战争】设立的目标，它将取决于所使用的【宣战理由】的类型。实现战争目标将获得相当可观的【战争分数】。", "desc_en": "A wargoal is the objective established for a certain War, and it will depend on the type of Casus Belli used. Achieving the wargoal will give a considerable amount of Warscore."}, {"id": "war_reparations", "zh": "战争赔款", "en": "War Reparations", "pillar": "military", "desc": "这种和平【条约】下，一个【国家】需要以【杜卡特】的形式每月支付10%收入，支持另一【国家】的【财政】，通常是胜利者为了报复刚刚结束的战争。", "desc_en": "This is a peace Treaty where one Country is made to send 10% of their income in Ducats each month to support the Finances of the other Country, usually the victor, in retaliation for the war that just ended."}, {"id": "war_leader", "zh": "战争领袖", "en": "War Leader", "pillar": "military", "desc": "战争领袖是指领导【战争】中冲突双方的两个【国家】。他们将主导【和平条约】的协商过程，从而决定冲突的最终结果。", "desc_en": "A War Leader is one of the two Countries who lead their respective side in a War. They will discuss the potential outcomes of the conflict by deciding over the Peace Treaties."}, {"id": "prisoner", "zh": "战俘", "en": "Prisoner", "pillar": "military", "desc": "战俘是战斗结束后被俘虏的敌方【军团】。他们可以被收买为【雇佣兵】为俘虏方作战，要求赎金，或者简单地处理掉……无论人道与否。", "desc_en": "Prisoners are enemy Regiments that have been captured after a battle. They can be bribed to be Mercenaries fighting for their captors, ransomed, or simply disposed of...humanely or not."}, {"id": "combat", "zh": "战斗", "en": "Combat", "pillar": "military", "desc": "当两支或两支以上相互【敌对】的【陆军】或【海军】在同一【地点】或【海域】相遇时，它们之间便将爆发战斗。\n战斗通常以【轰击阶段】开始，接着进入【作战阶段】。每个【军团】或【舰船】将尝试与敌军【接战】，并持续到某一方【撤退】。", "desc_en": "If two or more Armies meet in a Location, or two or more Navies in a Seazone, and they are Hostile towards each other, a battle will start between them.\nThe battle usually starts with a Bombard Phase and then continues in the Combat Phase. Each Regiment or Ship will attempt to Engage the enemy, and fight until one side Retreats."}, {"id": "combat_power", "zh": "战斗力", "en": "Combat Power", "pillar": "military", "desc": "这是【军团】在【战斗】中的直接伤害输出属性。它乘以【军团】的【兵力】决定了【军团】能造成多少伤害。", "desc_en": "This is the direct damage dealing attribute of a Regiment in Combat. It is multiplied with the Strength of the Regiment to determine how much damage the Regiment does."}, {"id": "attrition", "zh": "损耗", "en": "Attrition", "pillar": "military", "desc": "损耗在每月开始时生效，对于【军团】，这意味着士兵死亡，而对于【舰船】，它会损坏舰船的船体。某些损耗是【不可避免损耗】，损耗的主要来源包括以下：\n• 【陆军】没有【食物】\n• 【地点】的总【单位损耗权重】高于【补给上限】\n• 【冬季】、【地形】、【植被】或【气候】", "desc_en": "Attrition is applied at the start of each month, which for Regiments means that people die, while for Ships it also damages the actual ship. Some attrition is Unavoidable Attrition and the main sources for attrition include the following:\n• Army without Food\n• Total Unit Weight in Location above Supply Limit\n• Winter, Topography, Vegetation, or Climate"}, {"id": "attrition_loss", "zh": "损耗减员", "en": "Attrition Loss", "pillar": "military", "desc": "【军团】或【舰船】因承受【损耗】而每月遭受的损失量。", "desc_en": "How much damage Attrition does to a Regiment or Ship each month."}, {"id": "retreat", "zh": "撤退", "en": "Retreat", "pillar": "military", "desc": "一支【陆军】或【海军】会在【士气】过低输掉战斗后被迫撤退，也可以主动选择【撤退】。撤退时，其将无法再进行战斗或接受新命令，直到抵达目的地。", "desc_en": "An Army or Navy may be forced to retreat from losing a battle, due to their Morale becoming too low, or it could voluntarily decide to Retreat. While retreating, it will not be able to fight again, or be given new orders, until it has reached its destination."}, {"id": "rival_enemy", "zh": "敌人", "en": "Enemy", "pillar": "military", "desc": "宣布另一【国家】为【宿敌】的国家会被视为前者的敌人。一个【国家】可能宣布了许多【宿敌】但没有敌人，如果对方【国家】未回宣宿敌的话。", "desc_en": "A Country that has declared another a Rival will be known as the Enemy of the latter. A Country might have declared many Rivals, and yet have no Enemies, if no other Country has rivalled them back."}, {"id": "white_peace", "zh": "无条件和平", "en": "White Peace", "pillar": "military", "desc": "这种【和平条约】下，一切回归战前状态。", "desc_en": "This is a Peace Treaty that returns to the pre-war conditions."}, {"id": "maximum_strength", "zh": "最大兵力", "en": "Maximum Strength", "pillar": "military", "desc": "这代表着一个【军团】的兵力规模，同时也反映出维持该建制所需的【人力】。当两支单位的【战斗宽度】相同时，拥有更多【人力】的【军团】在【战斗】中表现更为优秀。", "desc_en": "This increases how many more men a Regiment has, thus increasing its Manpower cost. A Regiment with a higher amount of Manpower, but with the same Frontage, is more effective in Combat."}, {"id": "max_strength", "zh": "最大兵力", "en": "Maximum Strength", "pillar": "military", "desc": "这代表着一个【军团】的兵力规模，同时也反映出维持该建制所需的【人力】。当两支单位的【战斗宽度】相同时，拥有更多【人力】的【军团】在【战斗】中表现更为优秀。", "desc_en": "This increases how many more men a Regiment has, thus increasing its Manpower cost. A Regiment with a higher amount of Manpower, but with the same Frontage, is more effective in Combat."}, {"id": "embarkings", "zh": "正在登船", "en": "Embarkings", "pillar": "military", "desc": "由【海军】运输的【陆军】能够从某个【海域】登陆到邻近的【沿海】【地点】。", "desc_en": "An Army that is being transported by a Navy can disembark from a Seazone to an adjacent Coastal Location."}, {"id": "regular_regiment", "zh": "正规军团", "en": "Regular Regiment", "pillar": "military", "desc": "正规军团是由【国家】花费【人力】和【杜卡特】等资源手动招募的基础战斗单位。这些单位构成了数量相当有限的常备【陆军】，研发较晚【时代】的【革新】可以提高这一数量。", "desc_en": "Regular Regiments are recruited manually by a Country using most commonly Manpower and Ducats. These form the standing Armies, and are rather limited in numbers until you get the Advances from later Ages."}, {"id": "regular_ship", "zh": "正规舰船", "en": "Regular Ship", "pillar": "military", "desc": "正规舰船由【国家】花费【水手】和【杜卡特】手动招募，并成为常备【海军】的组成部分。这类舰船在初期数量相当有限，可以通过后续【时代】的【革新】进行扩充。", "desc_en": "Regular Ships are recruited manually by a Country using Sailors and Ducats. These form the standing Navies, and are rather limited in numbers until you get the Advances from later Ages."}, {"id": "monthly_manpower", "zh": "每月人力", "en": "Monthly Manpower", "pillar": "military", "desc": "这是【国家】每月获得的新【人力】。", "desc_en": "This is the monthly gain of new Manpower for the Country."}, {"id": "mercenary_monthly_fee", "zh": "每月费用", "en": "Monthly Fee", "pillar": "military", "desc": "这是雇佣佣兵团的每月花费，主要取决于【军团】的数量和质量，以及【指挥官】的【能力】。", "desc_en": "This is the monthly cost of hiring this company. It depends mostly on the number and the quality of its Regiments, as well as the Abilities of its Commander."}, {"id": "sailors", "zh": "水手", "en": "Sailors", "pillar": "military", "desc": "一个【国家】可能拥有一定数量的水手，这代表着那些在公海上谋生的渔民、商船水手和海军军官。\n\n这些经验丰富的水手是建造【舰船】所需，在维护【海军】时也会被消耗。他们与【海军征召兵】不同，战斗力更强。甚至在【探索】任务中也需要他们。\n\n水手获取速度可以通过建造港口【建筑】或研究特定【革新】来提高。", "desc_en": "A Country may possess a number of Sailors, representing the fishermen, merchant seamen, and naval officers who make a living on the open seas.\n\nSuch experienced tars are required to build Ships, and are expended while maintaining a Navy. These are separate from Naval Levies and more effective. They are even required to man Exploration missions.\n\nThe rate at which Sailors are gained can be increased by constructing port Buildings or researching certain Advances."}, {"id": "exile", "zh": "流亡", "en": "In Exile", "pillar": "military", "desc": "一支【陆军】或【海军】在某些情况下将处于流亡状态，该状态下它们无法同任何【单位】进行战斗或展开围攻，直到返回友好领土。这一状态通常发生在单位处在它们本无法进入的领土时，如签订【和平条约】后的敌方领土。", "desc_en": "An Army or Navy can be set in Exile, which means that it will be unable to siege or fight any Units until we have moved it back to friendly territory. This happens when they are in territory where they no longer have access to, usually after a Peace Treaty has been signed."}, {"id": "maritime_presence", "zh": "海上存在", "en": "Maritime Presence", "pillar": "military", "desc": "我们在沿岸海域的海上存在对于我们的【贸易】和领土【控制力】都至关重要。\n\n如果我们处于和平时期，只要通过拥有【港口】，就能使海上存在随着时间推移而增长。【封锁】会快速降低我们的存在，【海域】中的【海军】则可以快速重建我们的存在。\n\n高海上存在能在计算控制力时降低两处【海域】之间的【邻近度】衰减。一个【市场】内的沿岸海域的海上存在同样是【贸易优势】的重要来源。", "desc_en": "The Maritime Presence we have along our coasts is vital both for our Trade Advantage and for our Control over our territory.\n\nMaritime Presence builds up over time, if we are at peace, just from having Ports, while a Blockade will quickly reduce our presence. A Navy in a Seazone can quickly build up the presence again.\n\nHigh Maritime Presence reduces the Proximity that is lost between Seazones when calculating Control. Maritime Presence in the coastal Seazones of a Market increases our Trade Advantage in that market."}, {"id": "navy", "zh": "海军", "en": "Navy", "pillar": "military", "desc": "海军可以让【国家】在本土之外投射力量。海军由【角色】领导的【舰船】组成，能够进行【战斗】、【封锁】【敌对】海岸、扰乱敌人的【海上存在】，并将【陆军】运送到所需地点。同时还帮助处理后勤问题，因为它们可以【分发食物】和【收集食物】。", "desc_en": "Navies are what allows a Country to project power beyond its own land. Navies are groups of Ships led by a Character, which can fight Battles, Blockade Hostile coasts, disrupt enemy Maritime Presence, and transport Armies where they are needed. They also help with logistics as they can Distribute Food and Gather Food."}, {"id": "navy_tradition", "zh": "海军传统", "en": "Navy Tradition", "pillar": "military", "desc": "这代表了一个【国家】累积的【海军】、海上【战斗】、【封锁】和其他所有海军相关事务的经验。", "desc_en": "This represents the accumulated experience of Navies, their Battles, Blockades, and all other naval-related aspects a Country has."}, {"id": "naval_strength", "zh": "海军实力", "en": "Naval Strength", "pillar": "military", "desc": "一个【国家】的海军实力根据其最大【水手】储量、【海军】规模和【海军征召兵】军力来计算得出。", "desc_en": "The Naval Strength of a Country is calculated from its maximum Sailors, Navy size, and Naval Levy power."}, {"id": "navy_levy", "zh": "海军征召兵", "en": "Naval Levy", "pillar": "military", "desc": "海军征召兵是指直接从【人群】那里征用的运输【舰船】。当该单位组建时，拥有该船的【人群】及其船员将从【地点】的【人群】中被带走，当单位解散时，所有幸存者都会回到【人群】中。这些船只通常比从【水手】那里招募的【海军】更脆弱，应该由配备大炮的正规船只进行护卫。\n\n征召【舰船】还具有以下效果：\n\n经验衰减 +2%", "desc_en": "A naval levy is a transport Ship that has been commandeered directly from Pops. When the unit is recruited, the Pops that own the ship and their crew are taken from Pops in Locations, and when the unit is disbanded, any survivors return to the Pops. These ships are generally flimsier than a Navy recruited from Sailors, and should be guarded by proper ships with cannons.\n\nA levy Ship also has the following effect:\n\nExperience Decay +2%"}, {"id": "navy_maintenance", "zh": "海军维护费", "en": "Navy Maintenance", "pillar": "military", "desc": "当我们拥有一支华丽、闪亮的【舰船】队伍准备出航时，真是令人愉悦。然而，这些船只可不会自我维护，需要花费【杜卡特】来保持它们的良好状态。海军维护费就是衡量我们投入多少资源来保持舰队状态良好的一种方式。\n\n维护不足，【士气】就会受挫，我们的舰船也会战斗力下降，无论是在战斗中还是在增强【海上存在】时都是如此。", "desc_en": "It is lovely when we have a grand, shiny fleet of Ships ready to set sail. These vessels do not just maintain themselves, though: Ducats must be spent on keeping them shipshape. Navy Maintenance is a way of measuring how many resources we are diverting towards keeping our ships in good condition.\n\nAt lower maintenance, Morale will suffer, and our ships will be less effective, both in combat and at increasing Maritime Presence."}, {"id": "pirate", "zh": "海盗", "en": "Pirate", "pillar": "military", "desc": "海盗是通过【舰船】袭击其他船只或沿海地区，以劫掠【商品】和【杜卡特】为目的的武装袭击者。", "desc_en": "Pirates are boat-based attackers of other Ships or coastal areas who steal Goods or Ducats."}, {"id": "crossing", "zh": "渡水作战", "en": "Crossing", "pillar": "military", "desc": "【陆军】作为【进攻方】跨越【地点】间的河流、穿越【海峡】或从【海域】登陆时会承受【战斗】惩罚。\n\n跨越【河流】会对【进攻方】掷骰造成-1惩罚。跨越【海峡】会造成-2惩罚。", "desc_en": "An Army crossing a river between two Locations, crossing a Strait, or landing from a Seazone will get a penalty in Battle if they are the Attacker.\n\nCrossing a River imposes a penalty on the Attacker of -1 on the dice roll. Crossing a Strait imposes a penalty of -2."}, {"id": "broken_units", "zh": "溃军", "en": "Broken Units", "pillar": "military", "desc": "这些是自当前【战斗】中被击溃的【军团】或【舰船】。他们不会再参与该场战斗。", "desc_en": "These are the Regiments or Ships that have been routed in the current Battle. They will no longer participate in this battle at all."}, {"id": "cannons", "zh": "火炮", "en": "Cannons", "pillar": "military", "desc": "【舰船】拥有的火炮越多，在【战斗】中造成的伤害就越高。", "desc_en": "The more cannons a Ship has, the more damage they can do in Combat."}, {"id": "embarking", "zh": "登船", "en": "Embarking", "pillar": "military", "desc": "由【海军】运输的【陆军】能够从某个【海域】登陆到邻近的【沿海】【地点】。", "desc_en": "An Army that is being transported by a Navy can disembark from a Seazone to an adjacent Coastal Location."}, {"id": "privateer_maintenance", "zh": "私掠维护费", "en": "Privateer Maintenance", "pillar": "military", "desc": "虽然【私掠者】可以让自己致富，但涉及到【水手】时，他们仍需要【国家】的支持。", "desc_en": "While Privateers can enrich themselves, they still need to be supported by a Country when it comes to Sailors."}, {"id": "privateer", "zh": "私掠者", "en": "Privateer", "pillar": "military", "desc": "私掠者是胆识过人、响应了【国家】号召、对任何潜在【敌对】者的【海上存在】制造严重破坏的人。对于遇到私掠者的人来说，私掠者和【海盗】没什么不同。", "desc_en": "Privateers are enterprising people who have responded to the call from a Country to wreak havoc on the Maritime Presence of anyone potentially Hostile. For those that encounter them, they are indistinguishable from Pirates."}, {"id": "experience", "zh": "经验", "en": "Experience", "pillar": "military", "desc": "军队经验用于减少【战斗】中的【承伤】，可以通过【战斗】、【围攻】和【封锁】获取。【军团】和【舰船】的经验将随着时间推移逐渐衰减。\n【军团】也可通过操练军队【单位能力】来获得经验。\n在一些【招募方式】下，新招募的单位初始即可拥有更高的经验等级。", "desc_en": "Experience reduces the Damage Taken in a Battle, and is primarily gained through participating in a Battle, a Siege, or a Blockade. Over time, the experience of a Regiment or Ship will slowly decay.\nRegiments can also gain experience by the drill army Unit Ability.\nWith some Recruitment Methods, a new unit can start with a higher level of experience."}, {"id": "ship", "zh": "舰船", "en": "Ship", "pillar": "military", "desc": "舰船是【海军】的主要组成部分，可以运载【食物】、【军团】和其所属水员。每艘舰船都有特定的【船只类型】。", "desc_en": "This is the main building block of a Navy. A ship is a large boat able to carry Food, Regiments, and its own crew. Each ship is of a specific Ship Type."}, {"id": "navy_based", "zh": "舰队国家", "en": "Navy Based Country", "pillar": "military", "desc": "舰队国家是可以【拥有】【地点】，但其存在完全依赖于自己的【海军】的【国家】。如果海军被摧毁，那么国家就会覆灭。", "desc_en": "A Navy Based Country is a Country that can Own Locations, but its existence is relying entirely on its Navies. If those are destroyed, then the Country collapses."}, {"id": "hull_size", "zh": "船体尺寸", "en": "Hull Size", "pillar": "military", "desc": "船体尺寸越大，【舰船】在【战斗】中承受的伤害越小。", "desc_en": "The larger the hull size, the less damage a Ship takes in Combat."}, {"id": "reinforce", "zh": "补员", "en": "Reinforce", "pillar": "military", "desc": "【军团】低于【最大兵力】时会尝试补员，从所属【国家】获取【人力】和【杜卡特】。只有【正规军团】可以补员，并且只能在【友方】【地点】进行。", "desc_en": "When a Regiment is below its Maximum Strength, it will attempt to reinforce, by drawing Manpower and Ducats from its Country. Only a Regular Regiment can reinforce, and unless in a Friendly Location it will not be possible."}, {"id": "fort_limit", "zh": "要塞上限", "en": "Fort Limit", "pillar": "military", "desc": "country with icon的要塞上限代表其行政能力能够维持的fortifications with icon数量。【国家】可以超出要塞上限，但这么做会逐步提高其fort maintenance with icon。\n\n要塞上限主要随治下locations with icon的数量提高，不过country rank with icon、城市【地点等级】【地点】的数量、防御倾向societal value with icon和部分advances with icon也能提高要塞上限。", "desc_en": "The Fort Limit of a country with icon represents its ability to maintain its fortifications with icon without overburdening the administration. A Country can surpass its Fort Limit, but doing so will incur progressively higher fort maintenance with icon costs.\n\nThe Fort Limit increases chiefly with the number of owned locations with icon, but also with the country rank with icon and the number of Locations with city Location Rank. The defensive societal value with icon and some advances with icon may also increase it."}, {"id": "fort_maintenance", "zh": "要塞维护费", "en": "Fort Maintenance", "pillar": "military", "desc": "【要塞】对于击退入侵的【陆军】非常有用，但它们需要【杜卡特】来维护以确保完成任务的能力。要塞维护费是衡量一个【国家】将多少资源用于确保【要塞】处于良好状态的标准。花费的资源越多，要塞就越有效。", "desc_en": "Forts are useful for repelling invading Armies, but they use Ducats in upkeep to make sure they are capable of doing their job. Fort Maintenance is a measure of how many resources a Country is diverting towards ensuring their Forts are in good shape. The more resources spent, the more effective the forts will be."}, {"id": "discipline", "zh": "训练度", "en": "Discipline", "pillar": "military", "desc": "该数值影响了【军团】在【战斗】中的【承伤】和造成的伤害。训练度越高，造成的伤害越高，【承伤】越低。", "desc_en": "This impacts both the damage that a Regiment does in Combat and the Damage Taken. The higher the discipline the more damage done, and the less Damage Taken."}, {"id": "bombard", "zh": "轰击", "en": "Bombard", "pillar": "military", "desc": "可以轰击的【军团】会在【战斗】开场的【轰击阶段】以其【战斗力】造成伤害。", "desc_en": "Regiments that can bombard will deal their Combat Power as damage during the opening Bombard Phase of Combat."}, {"id": "bombard_efficiency", "zh": "轰击效率", "en": "Bombard Efficiency", "pillar": "military", "desc": "这是炮兵【军团】在【轰击阶段】开火的概率。", "desc_en": "This is the chance that artillery Regiments have to fire during the Bombard Phase."}, {"id": "bombard_phase", "zh": "轰击阶段", "en": "Bombard Phase", "pillar": "military", "desc": "轰击阶段是发生在主要的【作战阶段】前的开幕【战斗】【阶段】，持续3天（日步）/ 5小时。只有具有【轰击】能力的【军团】能在本阶段起作用，如炮兵。\n\n在轰击阶段的每小时，有效的【军团】有一次【轰击】机会，运用【战斗力】对同一【阵位】的敌方【军团】造成伤害。", "desc_en": "The Bombard Phase is the opening Phase of Combat which takes place before the main Combat Phase. It lasts 3 day(s) and is exclusively utilized by Regiments that can Bombard, such as army artillery.\n\nEach day of the Bombard Phase, valid Regiments have a chance to Bombard, which will deal their Combat Power as damage to an enemy Regiment on the same Section."}, {"id": "attacker", "zh": "进攻方", "en": "Attacker", "pillar": "military", "desc": "在【战斗】中，进攻方可能面临数个不利条件，因为他们将承受【地形】、【植被】、【渡水作战】的任何惩罚。另一方被称为【防御方】。", "desc_en": "The Attacker in a Battle may have several disadvantages, as they will get any Topography, Vegetation, or Crossing penalties. The other side is referred to as the Defender."}, {"id": "war_attacker", "zh": "进攻方", "en": "Attacker", "pillar": "military", "desc": "在一场war with icon中，进攻方是指主动挑起冲突的一方，其战争领袖通常选择某种casus belli with icon作为行动理由。\n\n进攻方需要达成其war goal with icon，从而逐步积累war score with icon。", "desc_en": "In a war with icon, the Attacker is the side whose leader initiated the conflict and chose the casus belli with icon.\n\nIn order to earn war score with icon, the Attacker side needs to fulfil the war goal with icon."}, {"id": "fortification", "zh": "防御工事", "en": "Fortification", "pillar": "military", "desc": "这些是一个【国家】用来保护治下【地点】，阻碍【战争对手】【陆军】的防御性【建筑】。拥有要塞的【地点】无法被快速【围攻】下，而是需要长期的【围攻】。某些【革新】会允许建造更有效的要塞，每一级都能提高【占领】所需的【围攻】难度。\n\n建有要塞的地点对毗邻【地点】提供【控制区】保护。\n\n要塞会产生直接计入国家【国库】的fort maintenance with icon，该费用受所在【市场】中【商品】价格影响。所有【国家】均设有一定的【要塞上限】，用于表示能够高效维持的要塞数量，超出上限将显著增加【要塞维护费】。", "desc_en": "These are defensive Buildings designed to protect the Country's own Locations against War Enemy Armies. A Location with a fort can not be Sieged instantly, but instead will require a prolonged Siege. Certain Advances will allow the construction of more effective forts, with each level increasing the difficulty of the Siege required to Occupy them.\n\nForts have a Zone of Control over adjacent Locations.\n\nForts have fort maintenance with icon costs that go directly to the Country's Treasury, and depend on the prices of Goods in their Market. All Countries have a Fort Limit to the number of forts they can maintain efficiently, and surpassing it increases the Fort Maintenance considerably."}, {"id": "defender", "zh": "防御方", "en": "Defender", "pillar": "military", "desc": "在【战斗】中，防御方将不会遭遇【进攻方】可能承受的各种惩罚。通常情况下，防御方是首先到达【地点】的【陆军】或【海军】，除非他们正忙于【围攻】。", "desc_en": "The Defender in a Battle will avoid the penalties that the Attacker may get. Usually, the defender is the Army or Navy that is first present in a Location, unless they are busy in a Siege."}, {"id": "war_defender", "zh": "防御方", "en": "Defender", "pillar": "military", "desc": "在一场war with icon中，防御方是指其战争领袖遭到宣战的国家。此时，该国会自动召集allies with icon加入【战争】。\n\n防御方需要阻止【进攻方】达成其war goal with icon，从而逐步积累war score with icon。", "desc_en": "In a war with icon, the Defender is the side whose leader was declared war upon. The Defender side will automatically call their allies with icon into the War.\n\nIn order to earn war score with icon, the Defender side needs to prevent the Attacker from fulfilling the war goal with icon."}, {"id": "phase", "zh": "阶段", "en": "Phase", "pillar": "military", "desc": "【战斗】分两个阶段，首先是初始3天（日步）/ 5小时的【轰击阶段】（如果有【军团】能够【轰击】），之后是【作战阶段】。", "desc_en": "There are two Phases of Combat, starting with the initial 3-day Bombard Phase (if any Regiments are able to Bombard), followed by the Combat Phase."}, {"id": "army", "zh": "陆军", "en": "Army", "pillar": "military", "desc": "陆军是由一名【角色】领导，由多个【军团】组成的单位。它可以进行【战斗】或【围攻】敌人的【防御工事】。", "desc_en": "An army is a group of Regiments led by a Character, which can fight Battles and Siege down enemy Fortifications."}, {"id": "army_tradition", "zh": "陆军传统", "en": "Army Tradition", "pillar": "military", "desc": "这代表了一个【国家】累积的【陆军】、【战斗】和【围攻】经验。", "desc_en": "This represents the accumulated experience of Armies, Battles, and Sieges a Country has."}, {"id": "army_levy", "zh": "陆军征召兵", "en": "Army Levy", "pillar": "military", "desc": "陆军征召兵是直接从【人群】中征召的【军团】。当该单位组建时，被征召的【人群】会减少，当单位解散时，所有幸存者都会回到【人群】中。这些人的训练不如从【人力】中招募的正规【陆军】，他们也不进行补员。\n\n征召【军团】还具有以下效果：\n\n训练度 -20%、经验衰减 +2%、食物消耗 -75%（轻装觅食）", "desc_en": "An army levy is a Regiment that has been raised directly from Pops. When the unit is recruited, the Pops they get recruited from are reduced, and when the unit is disbanded, any survivors return to the Pops. These people are less trained than a regular Army recruited from Manpower, and they do not reinforce.\n\nA levy Regiment also has the following effect:\n\nDiscipline -20%, Experience Decay +2%, Food Consumption -75%"}, {"id": "army_maintenance", "zh": "陆军维护费", "en": "Army Maintenance", "pillar": "military", "desc": "我们需要给我们的【陆军】薪水、武器、口粮和衣物，否则他们的战斗力就不会很高。陆军维护费就是衡量我们投入多少【杜卡特】来确保【陆军】得到所需一切的方式。没有这些，【士气】就会受挫，我们军队的战斗力也会下降。", "desc_en": "We need to pay, equip, feed, and clothe our Armies, or they will not be very effective. Army Maintenance is a way of measuring how many Ducats we are diverting towards making sure our Armies have everything they need. Without this, Morale will suffer, and our troops will be less effective."}, {"id": "mercenary", "zh": "雇佣兵", "en": "Mercenary", "pillar": "military", "desc": "雇佣兵是为了【杜卡特】参与军事冲突，但在其他方面与冲突不相干的私人个体。一个【国家】自己的部队可以被其他国家雇为雇佣军。\n\n雇佣兵的基础花费比【正规军】高出50%。", "desc_en": "Mercenaries are private individuals who take part in military conflict for Ducats, but are otherwise outsiders to the conflict. A Country's own units can be hired out to other countries as mercenaries.\n\nThe base cost of Mercenaries is 50% higher than Regulars."}, {"id": "mercenary_hiring_fee", "zh": "雇佣费用", "en": "Hiring Fee", "pillar": "military", "desc": "这是雇佣佣兵团的预付费用，不计算【合同期限】内费用。", "desc_en": "This is the upfront cost of hiring this mercenary company, notwithstanding the Contract Length."}, {"id": "reserves", "zh": "预备队", "en": "Reserves", "pillar": "military", "desc": "这些【军团】或【舰船】不会在【战斗】中参战，但根据需要，它们可以向【中军】或某一【侧翼】移动。\n每个【军团】或【舰船】都会掷一个【D20】，如果掷出的数值低于其【参战速度】，它就能加入战斗。然而，每小时只会有【战斗宽度】允许的单位尝试增援。", "desc_en": "These Regiments or Ships are not actively fighting in a Battle, but depending on need, they may move up to the Center or either Flank.\nEach Regiment or Ship rolls a D20 and if the roll is lower than its Combat Speed, it will be able to join the battle. However, only enough units for the possible Frontage of the battle attempts to reinforce each day."}, {"id": "leadership_election_resolution", "zh": "领袖选举决议", "en": "Leadership Election Resolution", "pillar": "military", "desc": "这是用于决定一个【国际组织】的【领袖】如何选举产生的特殊【决议】。", "desc_en": "This is the special Resolution used to determine how the Leader of an International Organization is elected."}, {"id": "dice", "zh": "骰子", "en": "Dice", "pillar": "military", "desc": "行动的结果通常由掷骰子决定，例如【围攻】或【战斗】的【阶段】。\n【D10】\n【D20】\n【D100】", "desc_en": "Dice are often rolled to determine the outcome of an action, like the Phases of a Siege or a Battle. \nD10\nD20\nD100"}, {"id": "upper_class", "zh": "上层阶级", "en": "Upper Class", "pillar": "state", "desc": "这些是在一个【国家】中拥有最大权力的几个【阶层】所对应的【社会阶级】，具体涵盖以下【社会阶级】：\n• 贵族\n• 教士\n• 市民", "desc_en": "This is a group of Social Classes that belong to one of the Estates that usually have the most power in a Country, and are one of the following Social Classes:\n• nobles\n• clergy\n• burghers"}, {"id": "lower_class", "zh": "下层阶级", "en": "Lower Class", "pillar": "state", "desc": "这组【社会阶级】属于社会底层，包括以下【社会阶级】：\n• 平民\n• 奴隶", "desc_en": "This is a group of Social Classes that belong to the lower strata of society, including the following Social Classes:\n• laborers\n• soldiers\n• peasants\n• tribesmen\n• slaves"}, {"id": "major_reform", "zh": "主要改革", "en": "Major Reform", "pillar": "state", "desc": "主要改革是定义一个【国家】的特殊【政府改革】。一个【国家】只能拥有一项主要改革。", "desc_en": "A Major Reform is a special Government Reform that defines a Country. A Country may only have one Major Reform at a time."}, {"id": "output", "zh": "产出", "en": "Output", "pillar": "state", "desc": "作为【制成品】由【建筑】生产，或作为【原材料】由【地点】生产的【商品】数量。", "desc_en": "The amount of Goods that is created either from a Building as Produced Goods, or as Raw Goods from a Location."}, {"id": "people", "zh": "人", "en": "People", "pillar": "state", "desc": "独立的人类，半可再生资源，聚集为【人群】或呈现为【角色】。", "desc_en": "Individual human beings. Semi-renewable resource, grouped in Pops or may appear as Characters."}, {"id": "tier", "zh": "位阶", "en": "Tier", "pillar": "state", "desc": "这是【可成立国家】等级的名称。每个【国家】都拥有从I到IV的等级，取决于成立条件的难易。最重要的是，【国家】只能成立更高级的国家。", "desc_en": "This is the name for the level that a Formable Country has. Every Country belongs to a Tier from I to IV, depending on how hard the formation requirements are. Most importantly, Countries can only form countries of higher Tiers than their current one."}, {"id": "mission", "zh": "使命", "en": "Mission", "pillar": "state", "desc": "使命是【国家】可以完成的单独【任务】的集合。它们可以为【国家】提供引导，并在任务完成时提供有用的奖励（如果规则开启的话）。", "desc_en": "Missions are packages of individual Tasks which are available to a Country. They serve as a guidance for the Country and grant useful rewards after finishing a task or all the tasks, depending on the settings."}, {"id": "mission_task", "zh": "使命任务", "en": "Mission Task", "pillar": "state", "desc": "任务是【使命】的子元素。它们有自己的完成要求并包含了一定奖励，在要求得到满足时提供奖励。要想完成【使命】，必须完成所有任务。", "desc_en": "A task is a sub-element of a Mission. They are made of a requirement and can contain a reward if the aforementioned condition is fulfilled. All tasks have to be completed in order to finish a Mission."}, {"id": "flanking_ability", "zh": "侧翼攻击能力", "en": "Flanking Ability", "pillar": "state", "desc": "该数值决定了单位在战斗中能对不同【阵位】的单位造成多少伤害。", "desc_en": "This determines how much damage it can inflict on units in a different Section in combat."}, {"id": "modifier", "zh": "修正", "en": "Modifier", "pillar": "state", "desc": "修正是影响游戏运作的数值，通常对某些游戏内数据进行加算或乘算。\n修正总是和特定的作用域相关，比如【国家修正】和【国家】相关，【地点修正】和【地点】相关，【角色修正】和【角色】相关，以及【国际组织修正】和【国际组织】相关。", "desc_en": "Modifiers are values that influence how the game works, by for example adding or multiplying to a certain calculation.\nModifiers are attached to a certain entity, such as Country Modifiers to Countries, Location Modifiers to Locations, Character Modifiers to Characters and International Organization Modifiers to International Organizations."}, {"id": "candidate", "zh": "候选者", "en": "Candidate", "pillar": "state", "desc": "这些是目前被视为角逐【国际组织】下任【领袖】的【国家】。", "desc_en": "These are the Countries that are currently considered as the next Leader of an International Organization."}, {"id": "borrower", "zh": "借方", "en": "Borrower", "pillar": "state", "desc": "借方是亏欠【杜卡特】并需要为此支付【利息】的【国家】，对应的贷方通常是另一【国家】或某一【阶层】。", "desc_en": "This is a Country which owes Ducats and has to pay Interest on it, usually to another Country or an Estate."}, {"id": "health_trait", "zh": "健康特质", "en": "Health Trait", "pillar": "state", "desc": "健康特质是影响【角色】健康（或不健康）的【特质】。\n\n角色一生可以获得任意数量的健康特质。\n\n健康特质可以来自多种来源，例如【事件】、【疫病】或【战斗】。甚至角色出生时亦有可能获得健康特质。\n\n源于战斗的特质的概率取决于友方伤亡数量。", "desc_en": "A Health Trait is a type of Trait that reflects the health (or unhealth) of a Character.\n\nA Character can end up with any number of Health Traits throughout their life.\n\nThey can be received from various sources, such as Events, Diseases, or Battle. They may even be saddled with a Health Trait from birth.\n\nTraits borne of Battle increase in their likliness depending on the number of friendly casualties."}, {"id": "child", "zh": "儿童", "en": "Child", "pillar": "state", "desc": "3岁到10岁之间的【角色】被视为儿童。他们无法为【国家】服务，但如果他们属于【统治者】【宗族】，你可以为其进行【儿童教育】。", "desc_en": "A Character who is between the age of 3 and 10 years old is a child. They can not serve their Country, but if they belong to the Ruler's Dynasty, you can give them a Child Education."}, {"id": "child_education", "zh": "儿童教育", "en": "Child Education", "pillar": "state", "desc": "【儿童】在3岁时可以接受教育。这将决定他们的【能力】会如何随时间提升。\n\n每月【儿童】都有55%的几率根据所受的教育提升其【能力】。", "desc_en": "Children can be given an education from the age of 3. This will determine how their Abilities improve over time.\n\nEvery month a Child has a 55% chance to increase their Abilities according to their education."}, {"id": "child_trait", "zh": "儿童特质", "en": "Child Trait", "pillar": "state", "desc": "每个【儿童】和【少年】在成长时都会有一个儿童特质，并且在成为【成年人】时移除。儿童特质影响了他们提升【能力】的速度。", "desc_en": "Every Child and Adolescent has one single Child Trait while growing up, which is removed once they become an Adult. Child Traits influence the rate at which they increase their Abilities."}, {"id": "republican_tradition", "zh": "共和传统", "en": "Republican Tradition", "pillar": "state", "desc": "共和传统衡量了共和主义的精神在我国如何深入人心，代表着共和国的传统得到贯彻的程度。一个共和国每数年将选举一名新【统治者】，使【统治者】在数次【选举】中连任将降低我们的共和传统。一个平稳运行的共和制政府应使这一指标保持在高位，如果共和传统过低，共和制政府将面临崩溃并有落入某种独裁统治的风险。", "desc_en": "Republican Tradition measures how well Republicanism is entrenched in our country. Republican Tradition represents how strong the traditions are in a republic. A republic elects a new Ruler every couple of years and keeping the same Ruler over several Elections will reduce our Republican Tradition. At low levels, it may collapse and revert to some kind of autocracy. For a well-functioning republic government, this measure should be kept high."}, {"id": "relation_type", "zh": "关系类型", "en": "Relation Type", "pillar": "state", "desc": "这些是我们可以与一个【国家】建立的关系。可以通过【外交】，或者与【附属国】互动。\n\n例子包括禁运、海峡通行费豁免或兵役免除税。", "desc_en": "These are relations we can form with a Country. This is either through Diplomacy or by interacting with a Subject.\n\nExamples include embargo nation, sound toll exemption or scutage."}, {"id": "civil_war", "zh": "内战", "en": "Civil War", "pillar": "state", "desc": "内战是一种特殊类型的【战争】，【国家】不是与其他【国家】进行【战争】，而是与自己的一部分交战。与常规【战争】的不同在于，【地点】不会被视为【占领】，而是在被【围攻】后立即转换【控制者】。", "desc_en": "A civil war is a special type of War in which a Country is at War not with another Country but with a part of itself. It also differs from normal Wars in that there is no Occupation of Locations, but instead, they will switch Controller immediately once they are Sieged."}, {"id": "cabinet", "zh": "内阁", "en": "Cabinet", "pillar": "state", "desc": "内阁是【国家】高级顾问组成的团体，他们通过【内阁行动】协助统治。研究某些【革新】可以增加【内阁席位】的数量。", "desc_en": "The Cabinet is the assembly of higher officials that help govern the Country through Cabinet Actions. The number of Cabinet Seats is increased by Advances."}, {"id": "cabinet_seats", "zh": "内阁席位", "en": "Cabinet Seats", "pillar": "state", "desc": "这定义了【国家】中可以同时在【内阁】任职的【内阁成员】的数量。某些【革新】可以增加可用的内阁席位数量。", "desc_en": "This defines the number of Cabinet Members that a Country can employ simultaneously in its Cabinet. Certain Advances can increase the number of Cabinet Seats available."}, {"id": "cabinet_bottleneck", "zh": "内阁席位瓶颈", "en": "Cabinet Slot Bottleneck", "pillar": "state", "desc": "EU5 核心治理与扩张制约：同一时间全国只能运行与内阁席位等量的内阁行动，而整合未整合省份（Integrate Province）、灾后恢复（Recovery Effort）、提升控制力、推广文化均需占用席位。在解锁地区级整合行动前，内阁席位直接决定版图消化上限。", "desc_en": "Core strategic bottleneck where cabinet seats limit parallel province integration, recovery, assimilation, and control boosting."}, {"id": "cabinet_member", "zh": "内阁成员", "en": "Cabinet Member", "pillar": "state", "desc": "内阁成员是在【内阁】任职的【角色】。", "desc_en": "A Cabinet Member is a Character employed in the Cabinet."}, {"id": "cabinet_efficiency", "zh": "内阁效率", "en": "Cabinet Efficiency", "pillar": "state", "desc": "这是被派去执行【内阁行动】的【内阁】【角色】的执行速度和效率。它受【王室力量】和【社会价值观】影响，也可以通过【革新】、【政府改革】、【政策】和【建筑】进行修正。", "desc_en": "It is the speed and effectiveness with which Characters from the Cabinet will operate when assigned to perform Cabinet Actions. It is influenced by the Crown Power and Societal Values, and can also be modified by Advances, Government Reforms, Policies, and Buildings."}, {"id": "cabinet_trait", "zh": "内阁特质", "en": "Cabinet Trait", "pillar": "state", "desc": "内阁特质是只作用于【内阁成员】【角色】的【特质】。\n\n拥有内阁特质的角色会对效力【国家】提供增益。\n\n如果该角色晋升为【内阁首脑】，则内阁特质的效果翻倍。", "desc_en": "A Cabinet Trait is a type of Trait that is only active while a Character is a Cabinet Member.\n\nA Character with a Cabinet Trait can give a boost to the Country that employs them.\n\nThe effects of a Cabinet Trait are doubled if the Character is promoted to Head of the Cabinet."}, {"id": "cabinet_action", "zh": "内阁行动", "en": "Cabinet Action", "pillar": "state", "desc": "【内阁】成员可以被指派内阁行动。这些行动会被执行到完成，或我们决定更改。\n可用的行动包括：\n\n行政行动\n（行政 ADM 类内阁行动：如提升控制力、发展省份、降通胀、研究思潮）\n\n外交行动\n（外交 DIP 类内阁行动：如灾后恢复、安抚阶层、推广文化/宗教、降厌战）\n\n军事行动\n（军事 MIL 类内阁行动：如整合省份/地区、稳定国家、镇压叛乱）", "desc_en": "A member of the Cabinet can be assigned to a Cabinet Action. These are performed either until they are finished, or until we decide to change it. \nThese are the different actions available: \n\nAdministrative Actions \nAdministrative cabinet actions \n\nDiplomatic Actions \nDiplomatic cabinet actions \n\nMilitary Actions \nMilitary cabinet actions"}, {"id": "head_of_the_cabinet", "zh": "内阁首脑", "en": "Head of the Cabinet", "pillar": "state", "desc": "内阁首脑是由朝廷提拔作为【内阁】的代表。\n\n该【角色】受到以下增益：\n内阁效率 +25%、内阁特质效果翻倍（+100%）、任职期间不可免职或兼任统帅", "desc_en": "The Head of the Cabinet is a Character who has been promoted by the court to represent the Cabinet.\n\nThe Character receives the following bonuses:\nCabinet Efficiency +25%, Cabinet Trait Impact +100%, cannot be removed"}, {"id": "subject_military_stance", "zh": "军事姿态", "en": "Military Stance", "pillar": "state", "desc": "这描述了【附属国】在【宗主国】处于【战争】时决定如何行动。", "desc_en": "This describes how Subjects decide what to do for their Overlords in times of War."}, {"id": "military_tactics", "zh": "军事战术", "en": "Military Tactics", "pillar": "state", "desc": "这会降低【军团】在【战斗】中的【承伤】。", "desc_en": "This reduces the Damage Taken of a Regiment in Combat."}, {"id": "military_objective", "zh": "军事目标", "en": "Military Objective", "pillar": "state", "desc": "军事目标是向【陆军】和【海军】下达的一系列使命，使其以优先完成这些目标为准则自主行动。", "desc_en": "Armies and Navies can be assigned objectives that they will attempt to fulfill on their own."}, {"id": "mil", "zh": "军事能力", "en": "Military Ability", "pillar": "state", "desc": "该【能力】代表【角色】有多善于处理军事事务，他们对战术的理解如何，以及他们如何做出艰难的选择。", "desc_en": "This Ability represents how good a Character is at understanding the military aspects of life, how they understand tactics, and how they make tough choices."}, {"id": "military_access", "zh": "军事通行权", "en": "Military Access", "pillar": "state", "desc": "军事通行权允许我们的部队穿过另一【国家】的土地。", "desc_en": "Military Access allows our troops to move through the land of the other Countries."}, {"id": "military_strength", "zh": "军力", "en": "Military Strength", "pillar": "state", "desc": "一个【国家】的军力是根据其最大【人力】，【陆军】规模和【征召兵】力量计算的。", "desc_en": "The Military Strength of a Country is calculated from its maximum Manpower, Army size, and Levy power."}, {"id": "peasant_enfranchisement", "zh": "农民自主权", "en": "Peasant Enfranchisement", "pillar": "state", "desc": "这决定了一个【地点】有多少【财富份额】属于平民阶层。剩余份额将转给贵族阶层。\n\n自主权主要受自由民societal value with icon的偏移程度影响。【城镇】的平民拥有比【乡村】更高的自主权，同时，一些【建筑】也会提升或降低这一水平。", "desc_en": "This determines how much of the Wealth Share of a Location belongs to the peasants estate. The rest is transferred to the nobles estate.\n\nEnfranchisement depends mostly on the free subjects societal value with icon. Urban Locations have a higher level than Rural Locations, and some Buildings can increase it or decrease it."}, {"id": "resolution", "zh": "决议", "en": "Resolution", "pillar": "state", "desc": "这些是【国际组织】可以采取的影响整个组织的行动。任意【成员】【国家】都可以向其他【成员】提出决议，且所有【成员】都可以通过支持或反对来影响辩论的结果。\n\n如果被通过，将基于决议内容产生不同的效果。", "desc_en": "These are actions taken by International Organizations affecting the whole organization. Any Member Country is able to propose a resolution to the other Members, and every Member will be able to influence the outcome of the debate by either supporting or opposing it.\n\nIf passed, the effects will depend on which resolution was taken."}, {"id": "decision", "zh": "决议", "en": "Decision", "pillar": "state", "desc": "玩家可以随时为其国家做出的一项选择，显示在决议面板中。与【动态历史事件】不同，决议不绑定于特定的触发时间——玩家自行决定何时（以及是否）执行它。决策可以是特定国家专属的（存在标签限制），也可以是通用的（所有国家可用），并可能存在单次标志，限制每局游戏只能使用一次。", "desc_en": "A choice the player can make for their country at any time, presented in the Decisions panel. Unlike a Dynamic Historical Event, a decision is not bound to a specific time of firing, but instead the player picks when (and whether) to act on it. Decisions can be country-specific or generic, and may be able to be triggered multiple times per campaign or just once."}, {"id": "decisions", "zh": "决议", "en": "Decisions", "pillar": "state", "desc": "玩家可以随时为其国家做出的一项选择，显示在决议面板中。与【动态历史事件】不同，决议不绑定于特定的触发时间——玩家自行决定何时（以及是否）执行它。决策可以是特定国家专属的（存在标签限制），也可以是通用的（所有国家可用），并可能存在单次标志，限制每局游戏只能使用一次。", "desc_en": "A choice the player can make for their country at any time, presented in the Decisions panel. Unlike a Dynamic Historical Event, a decision is not bound to a specific time of firing, but instead the player picks when (and whether) to act on it. Decisions can be country-specific or generic, and may be able to be triggered multiple times per campaign or just once."}, {"id": "selling_efficiency", "zh": "出售效率", "en": "Selling Efficiency", "pillar": "state", "desc": "这会增加【贸易】的利润，适用于你在目标【市场】购买【商品】的价格与销售价格之间的差额。仅对有利可图的贸易产生影响。", "desc_en": "This increases the profit margin on a Trade, applied to the difference between what you pay for Goods and what you sell them for in the target Market. It only benefits profitable trades."}, {"id": "lowborn", "zh": "出身卑微", "en": "Lowborn", "pillar": "state", "desc": "这是一个不属于任何显赫【宗族】的【角色】。", "desc_en": "This is a Character who does not belong to any Dynasty of note."}, {"id": "nationalist_rebels", "zh": "分离主义叛军", "en": "Nationalist Rebels", "pillar": "state", "desc": "叛军是尝试【叛乱】的异【文化】或【宗教】的【人群】，或试图发动【内战】的不满【阶层】。", "desc_en": "Rebels is a faction that are either Pops of another Culture or Religion that is attempting a Revolt or an unhappy Estate that is trying to force a Civil War."}, {"id": "great_power_rank", "zh": "列强排名", "en": "Great Power Rank", "pillar": "state", "desc": "列强排名显示了一个【国家】在最终胜利角逐中所处的当前位置。该排名由【列强分数】总和决定。", "desc_en": "Great Power Rank shows the current position a Country holds in the race for final victory. The Rank is decided by the sum of the Great Power Score."}, {"id": "profit", "zh": "利润", "en": "Profit", "pillar": "state", "desc": "这是【建筑】或【原产】为所在【地点】【财富】贡献的数额。换句话说，这是【建筑】创造的【杜卡特】。\n\n如果为负数，建筑会被视为亏损并停止运转。", "desc_en": "This is the amount that a Building or a R.G.O. contributes to the Wealth of its Location. In other words, the Ducats that are created from the Building.\n\nIf it is negative, the building will be considered unprofitable and stop working."}, {"id": "promote", "zh": "升级", "en": "Promote", "pillar": "state", "desc": "当所处【地点】有可用岗位时，【人群】将由平民【升级】。人群至少需要属于【相容文化】才能升级。", "desc_en": "Pops will Promote from peasants when there are possible positions for them in their Location. Pops need to belong to at least a Tolerated Culture in order to promote."}, {"id": "unit_ability", "zh": "单位能力", "en": "Unit Ability", "pillar": "state", "desc": "这是一些如操练军队或分散驰援之类的【单位】指令。一些单位能力为触发式指令，而部分能力为可切换指令，在激活后持续生效。", "desc_en": "This is the name for orders like drill army or march to sound of guns, which can be given to Units. Some of these are instant actions, others a state that can be toggled on or off."}, {"id": "hindu_branch", "zh": "印度教支派", "en": "Hindu Branch", "pillar": "state", "desc": "印度教的支派是该宗教体系下由特定传统和信仰构成的群体，每个支派都侧重崇拜一位或多位特定的【神祇】。", "desc_en": "A branch is a group of traditions and beliefs inside hindu giving prominence to one or more specific Gods."}, {"id": "historical_capital", "zh": "历史首都", "en": "Historical Capital", "pillar": "state", "desc": "这是一处过去曾作为某【国家】【首都】的【地点】。所有在【首都】建造时能提供特殊效果的【建筑】，在该【地点】成为【历史首都】后，这些效果依然保留。它本身还会提供+50的【邻近度】，但如果该【地点】已经从当前【首都】获得了更高的【邻近度】，该加成将不会生效。", "desc_en": "This is a Location that has served before as the Capital of the Country that owns it. Only a change of Capital caused by an event, decision or other special action creates a Historical Capital; moving the Capital ourselves does not. A Country can only have one Historical Capital at a time: when the Capital moves again, the previous Historical Capital loses its status. Any Buildings that give special effects when built in the Capital keep those effects in a Historical Capital. The Location also keeps a smaller share of the Capital bonuses, including Proximity source, Maximum Control, Population Capacity, Migration Attraction, Fort Maintenance efficiency and free building levels. The Proximity has no effect if the Location is already receiving higher Proximity from the current Capital."}, {"id": "friend", "zh": "友好国", "en": "Friend", "pillar": "state", "desc": "友好【国家】是我们的【附属国】、【宗主国】或【战争】盟友。当然，我们自己的国家也被视为友好的。", "desc_en": "A friendly Country is one who is either our Subject, our Overlord, or a War Allies. Of course, our own country is also considered friendly."}, {"id": "revolter", "zh": "叛乱国", "en": "Revolter", "pillar": "state", "desc": "一系列【地点】脱离为新【国家】，并对原来的【拥有者】发动【战争】即为叛乱。", "desc_en": "A revolt is when a group of Locations break away as a new Country and start a War against the original Owner."}, {"id": "unrest", "zh": "叛乱度", "en": "Unrest", "pillar": "state", "desc": "这项数值会对【地点】内【人群】的【人群满意度】造成负面影响。", "desc_en": "It is a value that negatively impacts the Pop Satisfaction of the Pops in a certain Location."}, {"id": "rebel_movement", "zh": "叛乱运动", "en": "Rebel Movement", "pillar": "state", "desc": "叛乱运动由一群因【人群满意度】过低而联合反抗政府的【人群】组成。\n\n叛乱运动存在多种类型。例如，其他【文化】或【宗教】的【人群】会试图发动【叛乱】，而不满的【阶层】则会尝试挑起【内战】。", "desc_en": "A Rebel Movement is a group of Pops that band together against their government due to their low Pop Satisfaction.\n\nThere are various types of Rebel Movements. For instance, Pops of another Culture or Religion will attempt a Revolt, while an unhappy Estate will try to start a Civil War."}, {"id": "call_to_arms", "zh": "召唤参战", "en": "Call to Arms", "pillar": "state", "desc": "召唤参战是一项在【战争】期间向每个【同盟】或其他已经宣称要加入军事冲突的【国家】发出的一项【外交行动】。\n\n作为【防御方】的国家将自动召唤盟友参战，而【进攻方】国家须手动进行该外交行动，且说服盟友加入战争将更加困难。", "desc_en": "A call to arms is a Diplomatic Action which can be done during War to every Ally and other Countries which have sworn to participate in military conflicts.\n\nCountries that are the Defender will automatically call their allies into the war, while countries that are the Attacker have to manually call them, and it is more difficult for them to convince them to join."}, {"id": "formable_country", "zh": "可成立国家", "en": "Formable Country", "pillar": "state", "desc": "可成立国家是一种新的国家认同，可以由满足特定条件的【国家】成立（或重建）。\n\n这些条件可能包括控制一个【区域】内一定百分比的【地点】，或是拥有特定【主流文化】。\n\n我们只能成立更高【位阶】的可成立国家。\n\n通常来说，它们代表了历史上的统一，甚至是传说中的野心。成立后，旧【国家】的名称、旗帜和颜色会更改为可成立国家的样式。", "desc_en": "A Formable Country is a new national identity that can be formed (or re-formed) by a Country fulfilling certain conditions.\n\nThese conditions might include controlling a percentage of the Locations in a Region, or having a specific Primary Culture.\n\nWe can only form a Formable Country that has a higher Tier than our current Tier.\n\nTypically, they represent historical unions, or even legendary ambitions. Upon formation, the old Country will change its name, flag, and colors to that of the Formable Country."}, {"id": "historical_option", "zh": "史实选项", "en": "Historical Option", "pillar": "state", "desc": "该事件为一个历史【事件】。选择该【事件选项】会让你和历史上的【国家】做出相同的决定。", "desc_en": "This is a historical Event, and this Event Option is the one that will make you take the same decision as the Country did in history."}, {"id": "assimilate", "zh": "同化", "en": "Assimilate", "pillar": "state", "desc": "同化是指某一【文化】的【人群】随着时间推移变更为他们【所属】【国家】的【主流文化】的过程。\n\n如果该【主流文化】相较于【人群】的文化具有较高的【文化战争力量】，同化的速度将加快。\n\n某些特定的【文化】与其【信仰】直接绑定，因此在他们【皈依】前无法被同化。\n\n一种文化必须在国家内存在，或对玩家持有中立及以上态度，才可以被选择。", "desc_en": "This is the process where Pops of one Culture change over time to the Primary Culture or an Accepted Culture of the Country that Owns them.\n\nIn each Location, the largest of these cultures first assimilates the Pops of every other culture, leaving the Primary Culture and Accepted Cultures untouched. Once only those remain, the Accepted Cultures slowly assimilate into the Primary Culture.\n\nPops of the Primary Culture are never assimilated, unless a Cabinet Action promotes another culture in their Province.\n\nIt is sped up if the assimilating culture has a high Culture War Power versus the Pop culture.\n\nSome specific Cultures are directly tied to their Faith, so they will not be able to be assimilated unless they are Converted first.\n\nA culture must either be present in a country or have a neutral or higher opinion of the player to be selectable."}, {"id": "logistics_distance", "zh": "后勤距离", "en": "Logistics Distance", "pillar": "state", "desc": "这指的是一支【陆军】距离其【食物供应】有多远。陆军可以从拥有【食物获取权】的【省份】、友军的【补给站】或正在执行【分发食物】的【海军】收集食物。【敌方】部队和敌军【控制区】将会阻止后勤食物供应。", "desc_en": "This is how far away an Army can trace its supply lines to a Food Source. Armies will gather food from a Province where it has Food Access, a friendly Supply Depot, or a Navy that is Distributing Food. A Hostile army or Zone of Control will block this."}, {"id": "entrenchment", "zh": "固化", "en": "Entrenchment", "pillar": "state", "desc": "这是【官僚部门】在【政府】内的固化程度，固化越高，花费越高，也越难以清除。", "desc_en": "This is how embedded into Government a Bureaucracy is. The higher the Entrenchment, the more it does, the more it costs, and the harder it is to get rid of.\n\nIt also impacts the Estate Satisfaction of Estates that like or dislike the Bureaucracy in question."}, {"id": "country", "zh": "国家", "en": "Country", "pillar": "state", "desc": "国家是能够参与【外交】的政治实体，拥有【政府】、【主流文化】和【主导宗教】，能够通过控制【陆军】和【海军】来投射自己的影响力。\n\n每个国家都归属于【定居】、【地产】、【兵团国家】或【游群社会】中的一类。\n\n每个国家都由人类玩家或者电脑扮演。", "desc_en": "A Country is a political entity that can participate in Diplomacy. It has a Government, a Primary Culture, and a Primary Religion. It may control Armies and Navies to project its power.\n\nEvery Country is either Settled, Extraterritorial, Army Based Country, or a Society of Pops.\n\nEach Country is played either by a human player or by an AI."}, {"id": "country_interaction", "zh": "国家互动", "en": "Country Interaction", "pillar": "state", "desc": "这些是我们可以对一个【国家】进行的【行动】。可以通过【外交】，或者与【附属国】互动。\n\n例子包括破坏名誉、偿还债务或转让地点。", "desc_en": "These are the Actions we can do with a Country. This is either through Diplomacy or by interacting with a Subject.\n\nExamples include sabotage reputation, pay off debt or give location to subject."}, {"id": "country_modifier", "zh": "国家修正", "en": "Country Modifier", "pillar": "state", "desc": "作用于整个【国家】的【修正】。", "desc_en": "A Modifier that applies to an entire Country."}, {"id": "country_strength", "zh": "国家实力", "en": "Country Strength", "pillar": "state", "desc": "这是一个【国家】实力的估算。它将国家的【军力】、【收入】和【人口】纳入考量。", "desc_en": "This is an estimate of the power of a Country. It takes into account its Military Strength, Income, and Population."}, {"id": "ai_disposition", "zh": "国家态度", "en": "Country Disposition", "pillar": "state", "desc": "国家态度反映了该国目前对你的看法，受到你们的相对实力、其是否对你的土地拥有宣称以及你们是否拥有任意正式宿敌关系的影响。国家会不断重新评估自己的态度，可能会随权力平衡的改变而改变。\\n\\n存在以下态度：\n（详见速查典：ai_disposition）", "desc_en": "A country's disposition reflects how it currently views you, shaped by your relative power, whether they hold a claim on your lands, and any formal rivalry. Dispositions are reassessed continuously and can shift as the balance of power changes.\\n\\nThe dispositions below exist:\n(See ledger: ai_disposition)"}, {"id": "ai_personality", "zh": "国家性格", "en": "Country Personality", "pillar": "state", "desc": "国家性格反映了该国的基本特性和治理方略，无论它倾向于征服、谨慎、外交还是孤立。性格在游戏开局时设置，只能通过事件或游戏规则进行更改。\\n\\n存在以下性格：\n（详见速查典：ai_personality）", "desc_en": "A nation's personality reflects its fundamental character and approach to statecraft, whether it prefers conquest, caution, diplomacy, or isolation. Personalities are set at the start of the game and can change only through events or game rules.\\n\\nThe personalities below exist:\n(See ledger: ai_personality)"}, {"id": "country_rank", "zh": "国家等级", "en": "Country Rank", "pillar": "state", "desc": "国家等级代表了【国家】在国际场合所受的尊重。这主要取决于国家的规模和实力，多数时候，一个国家仅凭历史上的传统国力就足以赢得尊重，因此一旦升级至更高的位阶，就永远不会再降低。\\n\\n更高的国家等级会给予更强的外交能力，更高的位阶也会解锁更多影响其他国家的【外交】手段。\n（详见速查典：country_rank）", "desc_en": "The Country Rank represents the respect Countries inspire among their peers. It will primarily depend on the size and might of a Country, although tradition alone is often enough to command respect so once acquired a Rank can never be lost.\\n\\nEach Country Rank allows greater diplomatic capabilities, with higher Ranks unlocking new means to influence other Countries through Diplomacy.\n(See ledger: country_rank)"}, {"id": "country_type", "zh": "国家类型", "en": "Country Type", "pillar": "state", "desc": "国家类型定义了一个【国家】的存在条件，并对游戏方式具有重大影响。一些国家需要【拥有】【地点】使其存续下去，另一些类型的国家则与他们的【陆军】，【建筑】或【人群】绑定。", "desc_en": "The Country Type defines the condition of existence of a Country and has enormous gameplay implications. Some Countries are defined by the Locations they Own and cannot exist without them, while others are defined by their Armies, their Buildings, or their Pops."}, {"id": "extraterritorial_country", "zh": "地产国家", "en": "Extraterritorial Country", "pillar": "state", "desc": "地产国家是凭借【建筑】存在的【国家】，无需【拥有】整个【地点】。", "desc_en": "An Extraterritorial Country is a Country that exists by virtue of its Buildings, and does not need to Own entire Locations."}, {"id": "map_mode_slot", "zh": "地图模式槽位", "en": "Map Mode Slot", "pillar": "state", "desc": "地图模式槽位是包含多个地图模式的容器。重复点击槽位可以在各地图模式间循环。打开任意地图模式类别，右键点击任意地图模式将其添加到槽位中。", "desc_en": "A Map Mode Slot is a container with several map modes. Click the slot repeatedly to cycle through them. Open any map mode category and right click on any map mode to add it to a slot."}, {"id": "geography", "zh": "地理", "en": "Geography", "pillar": "state", "desc": "地理是地域和自然特征的性质和相关设定。【大陆】、【次大陆】、【区域】、【地区】、【省份】和【地点】构成了这个世界的地理。", "desc_en": "Geography is the nature and relative arrangement of places and physical features. Continents, Subcontinents, Regions, Areas, Provinces and Locations are all parts of the world's geography."}, {"id": "geographical_term", "zh": "地理区划", "en": "Geographical Term", "pillar": "state", "desc": "【大陆】、【次大陆】、【区域】、【地区】、【省份】和【地点】等地理概念的任意集合。", "desc_en": "An arbitrary collection of geographical concepts like Continents, Subcontinents, Regions, Areas, Provinces and Locations."}, {"id": "diplomacy", "zh": "外交", "en": "Diplomacy", "pillar": "state", "desc": "外交是两个在【外交范围】内的【国家】之间的互动，由【外交官】推动。\n\n外交涵盖了【同盟】、【条约】、【附属国】和【宗主国】等各方面，并涉及【战争】与【和平】。\n\n高【威望】使外交更容易进行，而高【敌意】则使之更加困难。", "desc_en": "Diplomacy is an interaction between two Countries within Diplomatic Range of each other. It is facilitated by Diplomats.\n\nIt covers everything from Alliances, Treaties, Subjects, and Overlords, and governs War and Peace.\n\nHigh Prestige makes it easier to do diplomacy, while high Antagonism makes it harder."}, {"id": "diplomatic_reputation", "zh": "外交声誉", "en": "Diplomatic Reputation", "pillar": "state", "desc": "【国家】的外交声誉代表了其在国际关系中有多受重视。特别是，它影响了国家有多受其他国家【信任】。", "desc_en": "A Country's Diplomatic Reputation represents how highly regarded it is in international relations. In particular, it affects how Trusted it is by all other countries."}, {"id": "diplomat", "zh": "外交官", "en": "Diplomat", "pillar": "state", "desc": "这代表了【国家】在一定时间内可以进行多少【外交】。某些【革新】或【社会价值观】会提高该数值。", "desc_en": "This represents how much Diplomacy a Country can do in a given time. Some Advances or Societal Values will increase this amount."}, {"id": "diplomatic_capacity", "zh": "外交容量", "en": "Diplomatic Capacity", "pillar": "state", "desc": "与所有人结盟就是不与任何人结盟。维持比外交容量更多关系的【国家】将受到【外交声誉】和【威望】惩罚。特定【属国类型】也会占用外交容量占用，这也会削弱可用的外交行动。\n\n成为某些【国际组织】的成员会占用外交容量，你【同盟】的实力决定了该【同盟】占用的外交容量。", "desc_en": "An alliance with everyone is an alliance with no one. A Country that maintains more relations than its Diplomatic Capacity will suffer a penalty to their Diplomatic Reputation and Prestige. Certain Subject Types possess a Diplomatic Upkeep which reduces the available capacity too.\n\nMembership in some International Organizations will cost some Diplomatic Capacity, and the power of your Ally determines the cost of an Alliance."}, {"id": "bias", "zh": "外交态度", "en": "Bias", "pillar": "state", "desc": "外交态度是指一国对另一【国家】所持有的特定立场，包括【好感】、【信任度】与【敌意】三个维度。这些态度主要受两国【国家互动】的影响，同时也会因特定【事件】或历史背景的设定而产生变化。", "desc_en": "A bias is a certain attitude a Country can have towards another one. It is split into three categories: Opinion, Trust and Antagonism. Country Interactions, Events and historical setup have usually an impact on one of the three diplomatic aspects."}, {"id": "diplomatic_maintenance", "zh": "外交支出", "en": "Diplomatic Spending", "pillar": "state", "desc": "这是维持外交关系的预期花费。如有需要，我们可通过额外花费【杜卡特】，提升可使用的diplomats with icon数量与diplomatic capacity with icon。\n\n外交支出还能提高附庸国的subject loyalty with icon。", "desc_en": "Should we ever need it, the number of diplomats with icon at our disposal can be increased by spending extra Ducats.\n\nDiplomatic Spending also increases the speed of annexation with icon, subject loyalty with icon, diplomatic reputation with icon and counterespionage with icon."}, {"id": "dip", "zh": "外交能力", "en": "Diplomatic Ability", "pillar": "state", "desc": "该【能力】代表【角色】有多善于说服别人做某些事情。它也代表一个角色的受欢迎程度。", "desc_en": "This Ability represents how good a Character is at convincing other people to do certain things. It also represents how liked a character is."}, {"id": "diplomatic_range", "zh": "外交范围", "en": "Diplomatic Range", "pillar": "state", "desc": "外交范围限制了我们的外交官进行外交的物理距离。该范围以两国首都之间的距离为测算标准。", "desc_en": "Diplomatic Range limits the physical distance our diplomats can travel to conduct diplomacy. The distance to be traveled is from one capital to the other."}, {"id": "diplomatic_action", "zh": "外交行动", "en": "Diplomatic Action", "pillar": "state", "desc": "这是一个【国家】使用【外交官】对另一国家执行的行动。包括【同盟】、发动【战争】或许多其他事情。", "desc_en": "This is an action done by one Country to another using Diplomats. This includes forming Alliances, declaring War or many other things."}, {"id": "diplomatic_limitation", "zh": "外交限制", "en": "Diplomatic Limitation", "pillar": "state", "desc": "如果某国是高度依附于另一【国家】的【附属国】类型，或是【共主邦联】中的【被联统国】，则其外交可能会受到限制。这意味着以下外交行动要么无法执行，要么会受到严格限制：\n\n• 同盟\n• 食物获取权\n• 保障独立\n• 军事通行权\n• 驻港权\n• 创建建筑附属国\n• 创建附属国\n\n多数外交受限的附庸国无法自行发动【战争】，除非是针对极为特定的目标国家。", "desc_en": "A Country which is either a very dependent Subject or a Junior Partner in a Union might be diplomatically limited. That means the following diplomatic actions are either not possible or heavily restricted:\n\n•  Alliance\n•  Food Access\n•  Guarantee\n•  Military Access\n•  Fleet Basing Rights\n•  create building subject\n•  create province subject\n\nMost subjects with limited diplomacy are incapable of declaring their own Wars unless against very specific targets."}, {"id": "foreign", "zh": "外国", "en": "Foreign", "pillar": "state", "desc": "这是不属于你所游玩的【国家】的【地点】。", "desc_en": "This is a Location that is not owned by the Country you are playing."}, {"id": "celestial_authority_gc", "zh": "天朝威仪", "en": "Celestial Authority", "pillar": "state", "desc": "这是衡量中华天朝领袖统治合法性的变量。它可以用来通过该【国际组织】内的【法律】和【政策】。", "desc_en": "This is the measure of the legitimacy of the leader of the Middle Kingdom. It is used to pass Laws and Policies within that International Organization."}, {"id": "title_history", "zh": "头衔历史", "en": "Title History", "pillar": "state", "desc": "头衔历史是某【角色】在其一生中统治过的所有【国家】的关系列表。", "desc_en": "The Title History is the relation of all the Countries that a Character has ruled during their lives."}, {"id": "devotion", "zh": "奉献度", "en": "Devotion", "pillar": "state", "desc": "奉献度代表我国的【信仰】虔诚程度。奉献度越高，神权制的运作效率越高。", "desc_en": "Devotion represents the zeal of the Faith inside our country. The higher it is, the more efficiently our theocracy will run."}, {"id": "slave_rebels", "zh": "奴隶叛军", "en": "Slave Rebels", "pillar": "state", "desc": "叛军是尝试【叛乱】的异【文化】或【宗教】的【人群】，或试图发动【内战】的不满【阶层】。", "desc_en": "Rebels is a faction that are either Pops of another Culture or Religion that is attempting a Revolt or an unhappy Estate that is trying to force a Civil War."}, {"id": "prestige", "zh": "威望", "en": "Prestige", "pillar": "state", "desc": "【国家】的威望代表了该国在其他人眼中的分量。它会提高【主流文化】的【文化影响】，并使国家更容易开展【外交】。", "desc_en": "The prestige of a Country is how well seen that country is. The Cultural Influence of its Primary Culture is increased by it, and it makes it easier to do Diplomacy."}, {"id": "infant", "zh": "婴儿", "en": "Infant", "pillar": "state", "desc": "婴儿是不满2岁的【角色】。他们不能为【国家】作出服务，也无法接受【儿童教育】。", "desc_en": "A Character who is up to 2 years old is an infant. They can not serve their Country nor receive Child Education."}, {"id": "fully_settled", "zh": "完全定居", "en": "Fully Settled", "pillar": "state", "desc": "在一处【特许殖民地】中，当存在至少1000【人群】居住于一个未殖民【地点】，且该【地点】内一定比例的【人群】信仰【主导宗教】且为特许区所属国的【主流或已接纳文化】，则该地点将被视为完全定居。这一比例取决于该国的【力量投射】。", "desc_en": "When there is at least 1,000 Pops living in a Location and enough of the Pops in the Location in the Colonial Charter is the Primary or Accepted Culture and official Primary Religion of the owner of the charter, the location is considered Fully Settled. The percentage required is based on the Power Projection."}, {"id": "religious_figure_trait", "zh": "宗教人士特质", "en": "Religious Figure Trait", "pillar": "state", "desc": "宗教人士特质是只有当【角色】是【宗教人士】时才会生效的【特质】类型。\n\n拥有宗教人士特质的角色可以给予雇佣该角色的【国家】增益。", "desc_en": "A Religious Figure Trait is a type of Trait that is only active while a Character is a Religious Figure.\n\nA Character with a Religious Figure Trait can give a boost to the Country that employs them."}, {"id": "religious_rebels", "zh": "宗教叛军", "en": "Religious Rebels", "pillar": "state", "desc": "叛军是尝试【叛乱】的异【文化】或【宗教】的【人群】，或试图发动【内战】的不满【阶层】。", "desc_en": "Rebels is a faction that are either Pops of another Culture or Religion that is attempting a Revolt or an unhappy Estate that is trying to force a Civil War."}, {"id": "reformation", "zh": "宗教改革", "en": "Reformation", "pillar": "state", "desc": "宗教改革是一项在基督教世界内具有深远影响的运动。天主教信仰将分裂并产生出多种宗教派别，这一运动以宗教改革【局势】作为起点。\n宗教改革的宗教派别如下：\n• 胡斯派\n• 路德宗\n• 加尔文宗\n• 圣公宗", "desc_en": "The Reformation is an influential movement within the christian World which fragments the catholic faith into several other religions. This movement starts with Reformation Situation.\nThe following religions are part of the Reformation:\n• hussite\n• lutheran\n• calvinist\n• anglican"}, {"id": "religious_reform", "zh": "宗教改革", "en": "Religious Reform", "pillar": "state", "desc": "有时为了【宗教】的最理想未来，需要进行或接受宗教改革，代表因信徒的渴望和思潮而不断调整仪式和信仰。", "desc_en": "A Religious Reform is sometimes required or embraced for the best outcome of a Religion, representing the constant adaptation of the rites and faith due to the desires of its believers and institutions."}, {"id": "religious_faction", "zh": "宗教派系", "en": "Religious Faction", "pillar": "state", "desc": "单一【宗教】中有不同的组织代表内部的不同思潮。他们会试图互相争夺【国家】的赞助，并且【国家】本身也可以与他们互动并获得不同的受益。", "desc_en": "They are different organizations inside a single Religion, representing different currents of thought inside it. They will try to vie among each other for the Country's patronage, and the Country itself can interact with them and obtain different benefits."}, {"id": "dynasty", "zh": "宗族", "en": "Dynasty", "pillar": "state", "desc": "这是一群拥有共同祖先和血缘关系的角色。一个宗族中最显赫的【角色】将成为【宗族领袖】。", "desc_en": "It is a group of characters who share a common ancestor and are thus blood-related. The most important Character in a dynasty is the Head of the Dynasty."}, {"id": "dynasty_modifier", "zh": "宗族修正", "en": "Dynasty Modifier", "pillar": "state", "desc": "作用于【宗族】的【修正】。此类修正中，针对【角色】的效果将对该宗族所有在世成员生效；而针对国家的【国家修正】，仅在宗族成员担任国家【统治者】时才会生效。", "desc_en": "A Modifier that applies to the Dynasty. Modifier types which are supposed to target the Character are active on every living member of the dynasty, though Country Modifiers are only applied if the character is the Ruler of that country."}, {"id": "dynasty_founder", "zh": "宗族创建者", "en": "Dynasty Founder", "pillar": "state", "desc": "一个【宗族】的创建者。", "desc_en": "The Founder of the Dynasty."}, {"id": "dynasty_seat", "zh": "宗族基业", "en": "Dynastic Seat", "pillar": "state", "desc": "每个宗族都将特定的【地点】视为王朝的祖地。这些被视为宗族基业的【地点】会有稍多的贵族岗位。", "desc_en": "Every Dynasty has its ancestral home in a specific Location. Those Locations that harbor a Dynastic Seat will have more nobles than usual."}, {"id": "dynastic_power", "zh": "宗族权势", "en": "Dynastic Power", "pillar": "state", "desc": "宗族权势用于衡量一个【宗族】在某一【国际组织】内拥有的政治权力的大小，在神圣罗马帝国内部起到的作用尤其重要。这一变量的计算方式为将国家的【列强分数】乘以该国统治的【人群】占整个【国际组织】所有【国家】的【人口】的比例。", "desc_en": "Dynastic Power is the value of political power a Dynasty holds in an International Organization. It plays a major role within the Holy Roman Empire, and is calculated by multiplying the Great Power Score and ownership over Pops within the International Organization Countries have."}, {"id": "dynasty_head", "zh": "宗族领袖", "en": "Head of the Dynasty", "pillar": "state", "desc": "这是【宗族】中威望最高、最重要的【角色】。宗族的【方言】由其宗族领袖的语言决定，一些【事件】和其他内容可能需要宗族领袖。", "desc_en": "This is the most prestigious and important Character in the Dynasty. The Dialect of a dynasty is defined by that of its Head of the Dynasty, and some Events and other content may require a Head of the Dynasty."}, {"id": "bureaucracy", "zh": "官僚部门", "en": "Bureaucracy", "pillar": "state", "desc": "官僚部门是【政府】的分支，会随时间发展，汲取【结余】资金，并提供动态强度的增益和惩罚修正。\n\n每个官僚部门都拥有正面、负面和常驻修正。常驻修正固定不变。\n\n在【维护费】上花费的【杜卡特】数量会影响负面或正面修正哪一项占据主导。\n\n【固化】会随时间稳步提高，在提高费用的同时也会提高正面和负面修正的强度。高固化的官僚部门移除花费也更高。\n\n【阶层】对于生效的官僚部门有各自的态度，并会根据固化影响他们的【阶层满意度】。他们还可以通过【议会议程】要求增加或减少固化。", "desc_en": "A Bureaucracy is a branch of the Government that grows over time, draws money from the Balance, and provides good and bad modifiers with dynamic strength.\n\nEach Bureaucracy has positive, negative, and constant modifiers. Constant modifiers are constant.\n\nThe amount of Ducats spent on Maintenance impacts whether the negative or positive modifier is more dominant.\n\nEntrenchment increases steadily over time, increasing the cost, but also increasing the power of both positive and negative modifiers. A Bureaucracy with higher Entrenchment is also more costly to remove.\n\nEstates may like or dislike active Bureaucracies, which will impact their Estate Satisfaction relative to the Entrenchment. They may also ask to increase or reduce the Entrenchment via Parliament Agendas."}, {"id": "bureaucracy_type", "zh": "官僚部门类型", "en": "Bureaucracy Type", "pillar": "state", "desc": "官僚部门类型是【官僚部门】的模板，定义了其特征。", "desc_en": "A Bureaucracy Type is the blueprint of a Bureaucracy, and defines its characteristics."}, {"id": "bureaucracy_maintenance", "zh": "官僚部门维护花费", "en": "Bureaucracy Maintenance", "pillar": "state", "desc": "这是指运作【官僚部门】的每月花费。资金充足的官僚部门将没有负面修正，而资金不足的部门将只有负面修正。", "desc_en": "This refers to the cost of running the Bureaucracy each month. A fully funded Bureaucracy will have no negative modifiers, while a poorly funded will only have negatives."}, {"id": "settled_country", "zh": "定居国家", "en": "Settled Country", "pillar": "state", "desc": "定居国家是需要【拥有】【地点】来维持存在的【国家】。", "desc_en": "A Settled Country is a Country that needs to Own Locations in order to exist."}, {"id": "court_maintenance", "zh": "宫廷花费", "en": "Cost of the Court", "pillar": "state", "desc": "宫廷是【统治者】家庭的延伸，包括那些常规侍奉他们的人。最大的宫廷可以达到数千人，包括私人顾问、家族服务人员、神职人员、士绅、侍卫、后宫、妾侍、太监以及更多角色。所有这些人员都不是免费的，该数值代表了维持他们的存在所需的花费。", "desc_en": "The court is the extended household of the Ruler, including all those who regularly attend on them. In the largest courts, this number can grow to many thousands, comprised of camarilla, household staff, clergy, gentry, bodyguards, harem, concubines, eunuchs, and many more roles. All these people do not come for free, and this figure represents the cost of having them around."}, {"id": "mothballed", "zh": "封存", "en": "Mothballed", "pillar": "state", "desc": "被封存的【舰船】只需少量【杜卡特】维护，但不处于【战斗】准备状态，因此更容易被击败。", "desc_en": "Mothballed Ships require little Ducats to maintain them but are not kept in a Combat ready state, so can be defeated much more easily."}, {"id": "minor_revolt", "zh": "小规模叛乱", "en": "Minor Revolt", "pillar": "state", "desc": "如果一场【叛乱运动】在达成100%进度之时未能获得足够的支持，则不会酿成公开【叛乱】，而是会在受影响的【地点】导致小规模叛乱修正，造成以下惩罚：\n\n本地月度繁荣度 -0.5%、本地月度控制力 -0.5%。", "desc_en": "If a Rebel Movement has not managed to garner enough support when it reaches 100%, it will not break away in open Revolt, but cause a minor rebel uprising in the affected Locations, with the following penalties:\n\nLocal Monthly Prosperity -0.5%, Local Monthly Control -0.5%."}, {"id": "adolescent", "zh": "少年", "en": "Adolescent", "pillar": "state", "desc": "少年是年龄处于11岁和15岁之间的【角色】。他们尚未成长为【成年人】，但也不能被视为【儿童】了。", "desc_en": "A Character who is between the age of 11 and 15 years old is an adolescent. They are not yet an Adult but not really a Child anymore."}, {"id": "situation_action", "zh": "局势行动", "en": "Situation Action", "pillar": "state", "desc": "这些是我们在特定【局势】生效时可以采取的【行动】。一旦局势被解决它们就会消失。\n\n比如将宫廷移入躲藏处和重举义旗。", "desc_en": "These are the Actions we can do while a certain Situation is active. They vanish once the situation is resolved.\n\nSome examples are hide from black death and rtr rekindle revolt."}, {"id": "known_world", "zh": "已知世界", "en": "Known World", "pillar": "state", "desc": "这是你目前已【发现】的世界。任何未被你的【国家】发现的土地会被视为【未知之地】。", "desc_en": "This is the portion of the World that you have currently Discovered. Any territory not discovered by your Country is considered Terra Incognita."}, {"id": "protectionism", "zh": "市场保护", "en": "Market Protection", "pillar": "state", "desc": "这直接减少【外国】【市场】对该【地点】的【市场吸引力】，使其更可能归属其【拥有者】的【市场】。\\n\\n一单位的市场保护可抵消外国【市场】对本国地点一单位的市场吸引力。\n\n市场保护主要提高自【地点】的【控制力】。", "desc_en": "This directly reduces the Market Attraction that Foreign Markets have on Locations, making it more likely for them to fall under a Market of their Owner.\\n\\nOne point of Market Protection negates one point of Market Attraction of every foreign Market.\n\nMarket Protection increases mainly with the Control of the Location."}, {"id": "burghers_estate", "zh": "市民", "en": "Burghers", "pillar": "state", "desc": "这一阶层代表我国的商业阶层，包括手工业者、商人和贸易者。他们的传统职责是维持并发展经济。因此，他们通常被授予特殊的权利和特权，以便利商业与贸易。\n总体而言，让王室拥有比其他阶层更多的权力是更为有利的。", "desc_en": "This estate represents the commercial class of our country, including artisans, merchants, and traders. Their traditional responsibility is to maintain and develop the economy. Therefore, they are usually granted special rights and privileges to facilitate commerce and trade.\nIn general, it is better for the Crown estate to have more power than the other estates."}, {"id": "hre_law_level", "zh": "帝国法律等级", "en": "Imperial Law Level", "pillar": "state", "desc": "帝国法律等级衡量了【神圣罗马帝国】的各项法律制度分权化（或集权化）的程度。低法律等级代表【皇帝】的高度集权，而高法律等级代表权力的分散化。\n\n帝国改革只能向相邻法律等级修订，如：当现行法律为4级改革，皇帝就不能选择2级改革。大多数【法律】的默认等级为3级。", "desc_en": "The law level describes how decentralized versus centralized the specific law for the Holy Roman Empire is. A lower level represents higher power of the Emperor while a higher level represents a decentralized status.\n\nReforms can be only taken at their adjacent level, which means the Emperor cannot select a Level 2 reform if the current law is on a Level 4 reform. Most Laws start at level 3."}, {"id": "average_satisfaction", "zh": "平均满意度", "en": "Average Satisfaction", "pillar": "state", "desc": "这是一个【地点】的平均【人群满意度】。该数值会对地点的【繁荣度】和【控制力】造成负面影响。", "desc_en": "This is the average Pop Satisfaction in a Location. This has a negative impact on the Prosperity and the Control of the location."}, {"id": "peasants_estate", "zh": "平民", "en": "Commoners", "pillar": "state", "desc": "这一阶层代表社会最底层的民众。他们往往缺乏地位与权力，但平民百姓却是国家的根基，而当他们团结起来时，往往能爆发出令人惊讶的力量。\n总体而言，让王室拥有比其他阶层更多的权力是更为有利的。", "desc_en": "This is the estate which represents the population at the lowest tier of society. Frequently a class given little to no prestige or power, the common folk nevertheless make up the foundation of our country, and can become surprisingly powerful when united.\nIn general, it is better for the Crown estate to have more power than the other estates."}, {"id": "courtier", "zh": "廷臣", "en": "Courtier", "pillar": "state", "desc": "一个【国家】内所有未担任特定【职责】的【角色】都将被视为廷臣。廷臣可以被任命为【内阁成员】、【陆军将领】、【海军将领】或【探险家】。", "desc_en": "Any Character in a Country who does not hold a specific Role is considered a Courtier. Courtiers can be employed as Cabinet Members, Generals, Admirals, or Explorers."}, {"id": "construction_material", "zh": "建筑材料", "en": "Construction Material", "pillar": "state", "desc": "建筑材料是在【建造】【建筑】中起到重要作用的一类【原材料】。它们由【原产】生产，并且在【城镇】发展中至关重要。", "desc_en": "Construction Materials are Raw Goods which play a significant role in the Construction of Buildings. They are produced in a R.G.O., and are usually essential for the development of Urban Locations."}, {"id": "construction", "zh": "建造", "en": "Construction", "pillar": "state", "desc": "在【地点】建造有形事物的进程，例如建造【建筑】、招募【军团】或建造城市。\n\n建造需要从所在【地点】的【市场】获取【商品】。若所需【商品】不足，【建造】将会停滞。", "desc_en": "The process of building something in a Location, such as a Building, a Regiment, or a city.\n\nConstructions require Goods from the Market of the Location in which they are taking place. If the needed Goods aren't available, Construction will stall."}, {"id": "total_ability", "zh": "总能力", "en": "Total Ability", "pillar": "state", "desc": "【角色】的总能力是其【行政】、【外交】和【军事】【能力】的总和。", "desc_en": "The Total Ability of a Character is the sum of all their Administrative, Diplomatic, and Military Ability scores added together."}, {"id": "member", "zh": "成员", "en": "Member", "pillar": "state", "desc": "这些是属于【国际组织】的【国家】。", "desc_en": "These are the Countries that are part of an International Organization."}, {"id": "adult", "zh": "成年人", "en": "Adult", "pillar": "state", "desc": "至少16岁的【角色】被视为成年人。这样他们才可以在没有【摄政】的情况下担任【统治者】，成为【陆军将领】或【海军将领】，或就职于【内阁】，也可以【结婚】。不是成年人的角色可能是【婴儿】、【儿童】或【少年】。", "desc_en": "A Character who is at least 16 years old is deemed as an adult. They may then serve as Rulers without a Regent, become a General or Admiral, or serve in the Cabinet, and they can also become Married. A character that is not an adult is considered to be an Infant, Child, or Adolescent."}, {"id": "recruit", "zh": "招募", "en": "Recruit", "pillar": "state", "desc": "招募是在地图上将【人力】补充进【单位】的过程。这通常有【杜卡特】花费，以及附加的【商品】【需求】。毕竟，没有马的骑手几乎不能被称为骑手。", "desc_en": "Recruiting is a process to field Manpower as Units on the map. This usually has a Ducats cost and a Goods Demand attached to it. After all, a horseman without a horse can barely be called a horseman."}, {"id": "recruitment_method", "zh": "招募方式", "en": "Recruitment Method", "pillar": "state", "desc": "我们可以决定是要花费更多时间训练部队提高他们的【经验】，还是要尽快准备好【军团】，虽然这样【最大兵力】较低。", "desc_en": "We can decide if we want to spend more time training our troops to increase their Experience, or if we want to get the Regiment ready faster, but with lower Maximum Strength."}, {"id": "owner", "zh": "拥有者", "en": "Owner", "pillar": "state", "desc": "被认为合法占有一个【地点】的【国家】。即使【控制者】目前可能是另一个国家。", "desc_en": "The Country that is recognized to have de jure possession over a Location. Even if the Controller currently may be another country."}, {"id": "commander", "zh": "指挥官", "en": "Commander", "pillar": "state", "desc": "指挥官是指挥一支【单位】的【海军将领】或【陆军将领】。", "desc_en": "A Commander is an Admiral or General in charge of a Unit."}, {"id": "explorer_trait", "zh": "探险家特质", "en": "Explorer Trait", "pillar": "state", "desc": "探险家特质是只有当【角色】是【探险家】时才会生效的【特质】类型。\n\n一个角色在领导【探索】任务时最多可以获得一个探险家特质。", "desc_en": "An Explorer Trait is a type of Trait that is only active while a Character is an Explorer.\n\nA Character can earn up to one Explorer Trait while leading Exploration missions."}, {"id": "regency", "zh": "摄政", "en": "Regency", "pillar": "state", "desc": "当【政府】没有合法【统治者】时，就会进入摄政期，由【摄政】进行领导。\n\n通常来说，这发生于【继承法】未产生有效【继承人】，或【继承人】只是个【儿童】。\n\n在君主制中，【配偶】可以成为【摄政】，但除此之外，摄政将会是一位与最强大【阶层】甚至【宗主国】相关的【角色】。\n\n摄政会持续到出现合适的【统治者】。", "desc_en": "A Regency occurs while a Government has no legitimate Ruler, and is instead led by a Regent.\n\nUsually it is caused when the Succession Law produces no valid Heir, or when the Heir is a mere Child.\n\nIn a monarchy, the Consort may become the Regent, but otherwise it is a Character associated with the most powerful Estate, or even the Overlord.\n\nThe Regency persists until a proper Ruler is restored."}, {"id": "regent", "zh": "摄政", "en": "Regent", "pillar": "state", "desc": "这是【摄政】期间代理【国家】【统治者】行动的【角色】。", "desc_en": "This is a Character that is acting as the Ruler of the Country during a Regency."}, {"id": "payment", "zh": "支付", "en": "Payment", "pillar": "state", "desc": "这是【国际组织】内的一项安排，某些成员有义务向其他【成员】支付【杜卡特】、【人力】、【水手】或其他东西，以换取该组织的成员身份。支付可以通过不同【法律】进行调整。", "desc_en": "This is an arrangement made in an International Organization where some members are obliged to pay other Members Ducats, Manpower, Sailors or something else in return for their membership of the organization. Payments can be applied or repealed through different Laws."}, {"id": "improve_relations", "zh": "改善关系", "en": "Improve Relations", "pillar": "state", "desc": "这是一种【外交】行动，意图提高另一【国家】对我们【国家】的【好感】。", "desc_en": "It is an action of Diplomacy with the intention of improving the Opinion that another Country has of our own Country."}, {"id": "reform_desire", "zh": "改革呼声", "en": "Reform Desire", "pillar": "state", "desc": "天主教宗教存在关于何为正确教义、何为信仰范畴的内部冲突。随着时间的推移，改革的呼声越来越大，并将影响未来关于天主教教义的所有讨论。", "desc_en": "catholic religion has internal conflicts between what is the correct doctrine or not, and about what is part of the faith or not. As time goes by, the desire to reform becomes bigger, and will impact any future discussion about the doctrine of catholic."}, {"id": "government_type", "zh": "政体", "en": "Government Type", "pillar": "state", "desc": "【国家】的政体定义了其政府的内部结构。最重要的是，它决定了政府所使用的【政府影响力】和可用【继承法】，同时它也会解锁特定的【法律】、【政府改革】、【阶层特权】和【革新】。\n（详见速查典：government_type）", "desc_en": "The Government Type of a Country defines the inner structure of their government. Most notably it determines the Government Power they use and the Succession Laws available to them, but also unlocks specific Laws, Government Reforms, Estate Privileges, and Advances.\n(See ledger: government_type)"}, {"id": "government", "zh": "政府", "en": "Government", "pillar": "state", "desc": "每个【国家】都有一个特定【政体】的政府，位于其【首都】。\n\n政府由【统治者】和【内阁】组成，并由【社会价值观】，【政府改革】和【法律】塑造。", "desc_en": "Every Country has a Government of a specific Government Type located in its Capital.\n\nGovernments consist of the Ruler and the Cabinet, and are shaped by Societal Values, Government Reforms, and Laws."}, {"id": "government_power", "zh": "政府影响力", "en": "Government Power", "pillar": "state", "desc": "这是衡量【政府】运转情况的通用术语。有数种类型：【正统性】、【共和传统】、【奉献度】、【游牧团结】和【部落凝聚力】。", "desc_en": "This is the generic term for a measure of how well our Government functions. There are several types: Legitimacy, Republican Tradition, Devotion, Horde Unity and Tribal Cohesion."}, {"id": "government_reform", "zh": "政府改革", "en": "Government Reform", "pillar": "state", "desc": "政府改革代表了从古代传统到进步修正案的一切，勾勒出了【国家】的治理形态。每一项改革都是独一无二的，但它们通常会给予强大的权衡或开辟独特的游戏风格。\n\n【国家】只允许进行一定数量的政府改革，但可以通过某些【革新】提高限额。\n\n一些改革是【主要改革】，一个【国家】只能拥有一项。", "desc_en": "Representing everything from ancient traditions to progressive amendments, Government Reforms outline the shape of governance in a Country. Each one is unique, but they often give powerful trade-offs or open up unique play styles.\n\nCountries are only allowed a handful of Government Reforms, but can increase that allowance with certain Advances.\n\nSome reforms are Major Reforms; a Country may not have more than one of those."}, {"id": "government_needs", "zh": "政府需求", "en": "Government Needs", "pillar": "state", "desc": "【政府需求】是一个【国家】进行【建造】所需要的【商品】，行动包括建造【建筑】、升级【地点等级】、招募【陆军】、建造【海军】或准备【探索】等。\n\n如果【地点】所属【市场】无法满足【政府需求】，【建造】将会停滞。因此，确保【政府需求】的满足是任何政府的首要事项。", "desc_en": "Government Needs are those Goods your Country requires for Constructions like Buildings, upgrading Location Rank, recruiting Armies and Navies or preparing Explorations.\n\nConstructions will stall if the Government Needs cannot be satisfied in the Market of the Location, so the fulfillment of Government Needs should be a priority for any Government."}, {"id": "political_power", "zh": "政治力量", "en": "Political Power", "pillar": "state", "desc": "政治力量是【人群】在【政府】中的影响力。它用于计算【阶层力量】、【语言力量】，并决定各个【国家】的【上层阶级优势文化】。\n\n【人群】根据他们所属的【阶层】发挥不同程度的政治权力。例如，属于贵族阶层的人口自然比属于平民阶层的人口多数百倍的政治力量。", "desc_en": "Political Power is the clout that Pops have in the sphere of Government. It is used to calculate Estate Power and Language Power, as well as the Dominant Upper Class Culture of each Country.\n\nEach Pop exerts a different amount of Political Power dependent on the Estate they belong to. For example, a Pop belonging to the nobles estate naturally exerts hundreds of times more Political Power than a Pop belonging to the peasants estate."}, {"id": "political_influence", "zh": "政治影响力", "en": "Political Influence", "pillar": "state", "desc": "这代表了一位统治者及其内阁对【国家】政治机器累积的影响力。它每月根据【统治者】和内阁成员的综合能力增长。\n\n高【政治影响力】使你的【国家】运行更高效。", "desc_en": "This represents the accumulated influence a ruler and their cabinet wield over the political apparatus of a Country. It grows each month based on the Ruler's abilities and on the total ability of your cabinet members, divided by the number of cabinet seats you have. An empty seat counts as zero, so filling every seat always increases your gain.\n\nHigh Political Influence makes your Country run more efficiently."}, {"id": "policy", "zh": "政策", "en": "Policy", "pillar": "state", "desc": "每条【法律】都将解锁一个或多个政策以供选择。这决定了【国家】在执行这些法律时所采取的手段。", "desc_en": "Each Law has one or more Policies to choose from. These determine how the law is handled in a Country."}, {"id": "effect", "zh": "效果", "en": "Effect", "pillar": "state", "desc": "效果的作用是动态影响游戏，从简单地增加【杜卡特】到诸如解锁【政府改革】之类的更复杂操作都囊括在内。效果通常经由【事件】触发，或者作为【使命】的奖励。", "desc_en": "Effects are used in order to affect the game dynamically. They can range from the simple addition of Ducats to more complex actions like the unlocking of a Government Reform. Effects usually happen in an Event or are the rewards from Missions."}, {"id": "hostile", "zh": "敌对", "en": "Hostile", "pillar": "state", "desc": "敌对【国家】是想要伤害我们的国家，例如【叛军】、【海盗】或与我们进行【战争】的国家。", "desc_en": "A hostile Country is one that wants to do us harm, such as Rebels, Pirates, or a country we are at War with."}, {"id": "clergy_estate", "zh": "教士", "en": "Clergy", "pillar": "state", "desc": "这一阶层代表受过良好教育的国教教士。他们的传统职责是关怀国土与人民的精神福祉，但他们在国家行政中也有悠久的服务传统。在过去几个世纪中，他们从虔诚的信徒与历代君主那里获得了大量土地资产与特权。\n总体而言，让王室拥有比其他阶层更多的权力是更为有利的。", "desc_en": "This estate represents the educated priests of our state religion. Their traditional responsibility is to care for the spiritual well-being of the realm and our people, but they also have a long tradition of serving in our country's administration. Over the centuries, they have been gifted valuable property and privileges by pious folk and former rulers alike.\nIn general, it is better for the Crown estate to have more power than the other estates."}, {"id": "papal_authority", "zh": "教宗权威", "en": "Papal Authority", "pillar": "state", "desc": "教宗权威是衡量【教宗】受尊重和认可程度的标准。这是天主教会的【国际组织变量】，每月根据以下因素变化：【改革呼声】、内部和平、教义、【枢机】、【绝罚】和其他因素。\n应用于所有天主教【国家】的效果：\\n•【教宗权威】≥75：high papal authority\\n•【教宗权威】<25：low papal authority", "desc_en": "Papal Authority is a measure of how respected and acknowledged the Pope is. It is an International Organization Value of the Catholic Church, with monthly changes driven by: Reform Desire, internal peace, doctrines, Cardinals, Excommunications, and other factors.\nEffects apply to all catholic Countries:\\n• Papal Authority ≥ 75: high papal authority\\n• Papal Authority < 25: low papal authority"}, {"id": "papal_bull", "zh": "教宗诏书", "en": "Papal Bull", "pillar": "state", "desc": "教宗诏书是一种花费【杜卡特】颁布的国际敕令，影响所有天主教【宗教】的【国家】，但已实施王之敕令的国家除外。一部分教宗诏书具有【效果】和一项颁布的【法律】，而所有教宗诏书都有与【教宗权威】相称的国家【修正】。", "desc_en": "A Papal Bull is an international edict, enacted with Ducats, which affects all Countries of the catholic Religion, except those that have enacted placitum regium. While some Papal Bulls have Effects and an enacted Law, all Papal Bulls have Modifiers for the countries which scale in their effectiveness with the Papal Authority."}, {"id": "curia_action", "zh": "教廷行动", "en": "Curia Action", "pillar": "state", "desc": "这些是【教廷】可以采取的影响整个天主教世界的行动。任何天主教【国家】都可以向【教廷】提出辩论，并且所有拥有【枢机】的【国家】都可以通过支持或反对来影响辩论的结果。\n\n如果被通过，将基于教廷行动的内容产生不同的效果，作用于所有天主教【国家】。", "desc_en": "These are actions taken by the Curia affecting the whole catholic world. Any catholic Country is able to propose a debate to the Curia, and every Country with a Cardinal will be able to influence the outcome of the debate by either supporting or opposing it.\n\nIf passed, the effects will depend on which Curia Action was taken, but will apply to all catholic Countries."}, {"id": "dominant_country", "zh": "文化主导国", "en": "Dominant Country", "pillar": "state", "desc": "拥有某【主流文化】【人口】最多的【国家】将成为该【文化】的【文化主导国】。若某国的【宗主国】与其属于同一文化，则该国无法成为文化主导国。", "desc_en": "The Country that has the most Population of their Primary Culture becomes the Dominant Country of that Culture. A Country cannot be Dominant if their Overlord is of the same Culture."}, {"id": "unconditional_surrender", "zh": "无条件投降", "en": "Unconditional Surrender", "pillar": "state", "desc": "在提供无条件投降后，所有当前未被占领的【地点】将落入敌人的控制，敌人将获得100%的【战争分数】。投降【国家】的【陆军】将进入【流亡】状态，在【和平】签署之前，无法在未来的【战斗】中作战。无条件投降的接收方将收到敌人投降的提醒，之后便可以执行任何可能的和平条约，最多100%战争分数。如果接收国在几个月后仍未签署和平协议，他们将获得和平呼吁，以高于常规的速度每月增长【厌战度】。投降的国家将自动接受和平条约。当自然达到100%的战争分数时，AI通常会无条件投降。还有一些其他情况下，AI会无条件投降。", "desc_en": "Upon offering unconditional surrender, all of the currently unoccupied Locations will fall under enemy control and the enemy will gain 100% Warscore. Armies of the Country that surrendered will become Exiled and unable to fight in future Battles until Peace is signed. The recipient of an unconditional surrender will be alerted of the enemy's surrender and from then on will be able to enforce any possible peace up to 100% warscore cost. If the recipient country does not sign peace after a couple of months, they will get a call for peace giving them monthly War Exhaustion which increases faster than normal. The peace will be automatically accepted by the country that surrendered. When naturally reaching 100% warscore, the AI will usually unconditionally surrender. There are also some other cases in which the AI unconditionally surrenders."}, {"id": "normal_power", "zh": "普通国家", "en": "Normal Power", "pillar": "state", "desc": "【普通国家】即不是【列强】的【国家】。", "desc_en": "A Normal Power is a Country that is not a Great Power."}, {"id": "share_of_power_gc", "zh": "权力支配度", "en": "Share of Power", "pillar": "state", "desc": "在是在德里的衰亡【局势】局势下衡量斗争双方力量对比的标准。德里苏丹国可通过以下方式增强实力：\n——局势行动\n——【事件】\n——特殊和平条约\n其他【国家】的外交支持\n\n反对者则可通过向德里苏丹国发动进攻战争并取得胜利来增强实力", "desc_en": "This is the measure of strength of a particular opposing side during the fall of delhi Situation. Delhi Sultanate can increase it through the following means:\n- Situation Actions\n- Events\n- Special Peace Treaties\n- Diplomatic Support from other Countries\n\nOpposers can increase theirs through offensive wars and victories against Delhi Sultanate."}, {"id": "trigger", "zh": "条件", "en": "Trigger", "pillar": "state", "desc": "条件是为了激活某些【效果】、【事件】、【任务】和其他游戏元素而需要满足的情况。", "desc_en": "Triggers are conditions which need to be fulfilled in order for certain Effects, Events, Tasks and other kind of game elements to be active."}, {"id": "legitimacy", "zh": "正统性", "en": "Legitimacy", "pillar": "state", "desc": "正统性是衡量【国家】内的人口和阶层有多接受治理的标准。正统性在很大程度上是平稳治国的先决条件——水平较低时，没人愿意与我们合作，叛乱可能会爆发，试图扶持一位他们认为更合适的【统治者】。", "desc_en": "Legitimacy is a measure of how accepted the governance is by the population and estates in their Country. It is very much a prerequisite for running a country smoothly - at low levels we will find that nobody wants to work with us and rebellions may break out, attempting to install a Ruler that they find more palatable."}, {"id": "civil_construction", "zh": "民用建造", "en": "Civil Construction", "pillar": "state", "desc": "民用建造是指一个【地点】内当前一切非【陆军】【海军】单位建造，比如【建筑】、迁移【首都】、创建【市场】或修建【道路】。", "desc_en": "Civil Constructions are anything that is currently being built in a Location that is not an Army or Navy unit, for example Buildings, moving your Capital, creating a Market or building Roads."}, {"id": "immortality", "zh": "永生", "en": "Immortality", "pillar": "state", "desc": "永生者【角色】不会死于衰老。但他们仍有可能因其他世俗原因而死，例如【战斗】，或者【疫病】这种更糟糕的事情。", "desc_en": "When a Character is immortal, they will not die from old age. They are however still susceptible to death from other worldly causes, such as Battle or something far worse, like Disease."}, {"id": "legal_male", "zh": "法定男性", "en": "Legal Male", "pillar": "state", "desc": "法定男性是一名在法律上被认定为男性，从而获得了和男性同等的【继承法】权利的女性【角色】。通过赋予女性继承权这一【角色互动】可将一名女性确立为法定男性。", "desc_en": "A Legally Male is a female Character who is considered, by law, to be a man. This gives them the same rights as their male counterparts in the question of Succession Law. This status may be declared on a woman with the prefection Character Interaction."}, {"id": "law", "zh": "法律", "en": "Law", "pillar": "state", "desc": "每条法律都需要选择一项【政策】以使其生效。不同的【政体】和【宗教】将解锁不同的法律，同时随着【革新】研发将解锁更多法律。我们在执行法律时选择的【政策】通常会对我们的【社会价值观】产生影响。", "desc_en": "Each law has to have a Policy selected for it, else it is not active. Different Government Types and Religions gain different laws, and more laws are given through Advances. Depending on what Policy we pick in a law, we will often impact our Societal Values."}, {"id": "admiral", "zh": "海军将领", "en": "Admiral", "pillar": "state", "desc": "这是被委任领导【海军】的【角色】。", "desc_en": "This is a Character that has been assigned the role of leading a Navy."}, {"id": "admiral_trait", "zh": "海军将领特质", "en": "Admiral Trait", "pillar": "state", "desc": "海军将领特质是只有当【角色】是【海军将领】时才会生效的【特质】类型。\n\n一个角色在海上【战斗】时最多可以获得一个海军将领特质。", "desc_en": "An Admiral Trait is a type of Trait that is only active while a Character is an Admiral.\n\nA Character can earn up to one Admiral Trait while fighting naval Battles."}, {"id": "naval_range", "zh": "海军范围", "en": "Naval Range", "pillar": "state", "desc": "这是我们的【舰船】在必须返航补给前所能【探索】的最大距离。", "desc_en": "This is simply how far our Ships can Explore before they need to turn back for more supplies."}, {"id": "overseas", "zh": "海外飞地", "en": "Overseas", "pillar": "state", "desc": "这是与【国家】【首都】无陆路连接，位于另一【大陆】且不位于相邻【次大陆】的【地点】。", "desc_en": "This is a Location on another Continent whose Subcontinent does not border the Capital's Continent, by land or sea."}, {"id": "infiltrate_administration", "zh": "渗透行政系统", "en": "Infiltrate Administration", "pillar": "state", "desc": "这允许我们在一定时间内移除另一个【国家】的【战争迷雾】。", "desc_en": "This allows us to remove Fog of War over another Country for a period of time."}, {"id": "horde_unity", "zh": "游牧团结", "en": "Horde Unity", "pillar": "state", "desc": "游牧团结用于衡量一位汗能从部族中获得多少支持。它会随时间而降低，但能通过劫掠省份来增加。低团结的草原游牧很可能会出现内部冲突。", "desc_en": "Horde Unity is a measure of how much support a Khān has from the tribes. It goes down over time and is increased by looting and razing provinces. A steppe horde with low unity is likely to succumb to internal strife."}, {"id": "estate_satisfaction_equilibrium", "zh": "满意度均衡点", "en": "Satisfaction Equilibrium", "pillar": "state", "desc": "这是【阶层】的【阶层满意度】的移动趋向于的目标数值。移动速度取决于诸多因素。", "desc_en": "This is what the Estate Satisfaction of an Estate will move towards. The speed by which it moves depends on many factors."}, {"id": "special_status", "zh": "特殊地位", "en": "Special Status", "pillar": "state", "desc": "一个在特定【国际组织】中占据特殊地位的国家，通常会享有特定的权利或承担相应的义务。通常情况下，该组织的【领袖】会拥有特殊地位，以彰显其代表该组织的独特属性。在其他一些组织中，【选举者】同样拥有特殊地位。", "desc_en": "Members with a Special Status in an International Organization enjoy certain privileges or have certain duties to fulfill. In some cases, the Leader of the organization has a special status to emphasize their unique position. Other organizations have Electors instead which are represented with a special status."}, {"id": "special_status_power", "zh": "特殊地位权能", "en": "Special Status Power", "pillar": "state", "desc": "这是一系列具有【特殊地位】的【成员】在【国际组织】的事务中所享有的政治权力。对于一些在【议会】中进行辩论且无法通过【决议】直接通过的【议会议案】，这种影响力对它们的表决通过至关重要。", "desc_en": "This is the political power that a group of Members with a specific Special Status has in an International Organization. This influence can be relevant for passing certain Parliament Issues in the Parliament unless those are resolved via a Resolution."}, {"id": "trait", "zh": "特质", "en": "Trait", "pillar": "state", "desc": "特质定义了【角色】在各种境况下的性格和行为。完成特定【职责】可以获得不同类型的特质，但角色只会使用与其当前职责相关的特质。", "desc_en": "Traits define the personality and behavior of a Character under various circumstances. Different types of Traits can be earned while fulfilling specific Roles, but a Character will only make use of those Traits relevant for their current Role."}, {"id": "crown_estate", "zh": "王室", "en": "Crown", "pillar": "state", "desc": "这是整个国家与政府权威的核心与源泉，只掌握在最高统治者手中，并不授予其他阶层。\n总体而言，让王室拥有比其他阶层更多的权力是更为有利的。", "desc_en": "This is the heart and source of authority for our entire realm and government, held solely by those at the very top and not granted to the other estates.\nIn general, it is better for the Crown estate to have more power than the other estates."}, {"id": "crown_power", "zh": "王室力量", "en": "Crown Power", "pillar": "state", "desc": "王室力量描述了王室在【国家】内部的权力。该数值越高，【国家】就会越强大越高效。如果给予【阶层】太多【阶层特权】，该数值就会变得非常低，以至于国家受到惩罚。\n\n一些【时代】的【革新】可以有效提高【王室力量】，尤其是我们迈入绝对主义时代（V）后。", "desc_en": "This is the power that the crown has in a Country. The bigger it is, the more powerful and efficient the Country becomes. If too many Estate Privileges have been given to the Estates, this may be so low that the country gets penalties.\n\nThere are Advances through the Ages that increase the Crown Power, especially as we advance into the age 5 absolutism."}, {"id": "royal_marriage", "zh": "王室联姻", "en": "Royal Marriage", "pillar": "state", "desc": "王室联姻是来自不同【国家】的两个【角色】的婚姻，旨在让两国的关系更加紧密，并为【统治者】提供【威望】。", "desc_en": "A royal marriage is a marriage between two Characters from two different Countries, in an effort to tie them closer together, and give Prestige to their Rulers."}, {"id": "production_efficiency", "zh": "生产效率", "en": "Production Efficiency", "pillar": "state", "desc": "这影响了【建筑】的【产出】。正生产效率会提高利润，而负生产效率可能会使建筑不值得继续运营。", "desc_en": "This impacts the Output of Buildings. A positive Production Efficiency increases the profit, while a negative may make it not worth keeping open."}, {"id": "production_method", "zh": "生产方式", "en": "Production Method", "pillar": "state", "desc": "生产方式可在【建筑】中调整，以改变建筑物运作所需【商品】，或者改变其发挥的效能。", "desc_en": "This is something that can be changed in a Building to change the Goods required for its performance and/or what the building itself is capable of doing."}, {"id": "fertility", "zh": "生育力", "en": "Fertility", "pillar": "state", "desc": "女性【角色】的怀孕能力，以及男性角色使女性角色怀孕的能力。", "desc_en": "This impacts the ability of a Character becoming pregnant if they are female, or to get a female pregnant when they are a male."}, {"id": "societal_value", "zh": "社会价值观", "en": "Societal Value", "pillar": "state", "desc": "社会价值观塑造了一个【国家】的社会与政治结构，定义人民的习俗和法律体系的特征。它对国家的运作方式具有深远影响，某些高级【政府改革】的实施需要特定的社会价值观组合作为前提。此外，社会价值观在【外交】中也至关重要，拥有相似【社会价值观】的【国家】通常会对彼此持有更高的【好感】。\\n\\n每个社会价值观都表现为一个轴线，包含两个对立的极点，数值范围最高可达100。一个国家在轴线上的位置主要受【法律】、【阶层特权】和【内阁行动】的影响，并会随时间逐渐向某一极点缓慢偏移。然而，向极点的推进会在达到最大值时停滞，具体取决于推动其发展的因素总量。数值越高，进一步推动其发展所需的因素就越多。\n\n（详见速查典：societal_values）", "desc_en": "The Societal Values define the social and political structure of a Country, the customs of its people and the characteristics of its legal body. Its effects can have a profound impact on how the country is played, and some advanced Government Reforms require specific combinations of Societal Values to be enacted. Societal Values also play an important role in Diplomacy, as Countries with affine Societal Values will tend to have a higher Opinion of each other.\\n\\nEach Societal Value is an axis with two opposite poles that can reach up to 100. A Country's position on the axis is primarily influenced by Laws, Estate Privileges, and Cabinet Actions, and it drifts slowly over time towards one of the two poles. However, progress towards one pole will stall at a maximum, determined by the total amount of factors pushing it in that direction. The higher a Societal Value, the more factors are needed to push it further.\n\n(See ledger: societal_values)"}, {"id": "holy_roman_empire", "zh": "神圣罗马帝国", "en": "Holy Roman Empire", "pillar": "state", "desc": "神圣罗马帝国是一个在政治上统辖了北德意志区域、南德意志区域区域以及意大利区域、法兰西区域部分区域的【国际组织】。神圣罗马帝国是一个由国力从微不足道到中等强权的众多【国家】组成的集合体，它们都受到【领袖】的保护。\n\n神圣罗马皇帝是该组织的领袖，经由选举获得这一职位。", "desc_en": "The Holy Roman Empire is an International Organization which dominates the political sphere of north german region, south german region and partially italy region and france region. The Holy Roman Empire is an amalgamation of countless Countries of insignificant to medium power who all fall under the protection of their Leader.\n\nThe Emperor is the head of this organization which gets elected into this position."}, {"id": "blocked_treaties", "zh": "禁止条约", "en": "Blocked Treaties", "pillar": "state", "desc": "这使得一个【国家】不可以与禁止的【国家】签署任何【条约】。", "desc_en": "This makes it impossible for a Country to sign any sort of Treaty with the Country they are blocked from doing it with."}, {"id": "divorce", "zh": "离婚", "en": "Divorce", "pillar": "state", "desc": "结束【婚姻】的方式，通常需要第三方的许可。", "desc_en": "A way to end up a Marriage, often requires permission from a third party."}, {"id": "private_regiment", "zh": "私人团", "en": "Private Regiment", "pillar": "state", "desc": "私人团是由【阶层】招募并保留在自己私人军队中的【军团】，不会耗费我们的【人力】。我们可以征召这些团为我们效力，但一旦解散，它们会返还给领地，而不是把兵力返还给我们。若某个领地发动叛乱，它会召回所有它曾借给我们的私人团。", "desc_en": "A private regiment is a Regiment that an Estate raises and keeps in its own private army, at no cost to our Manpower. We can press those regiments into our service, and once disbanded they return to the estate rather than returning manpower to us. An estate that rises in revolt recalls every private regiment it has lent us."}, {"id": "privateer_durability", "zh": "私掠耐久度", "en": "Privateer Durability", "pillar": "state", "desc": "在具有【反海盗影响】的海洋【地区】中，【私掠者】将会持续受损直至被摧毁。私掠耐久度越高，他们能存活的时间越久。", "desc_en": "Privateers can be damaged and destroyed by Anti-Piracy Impact in their Area. With a higher Privateer Durability, they can survive for longer."}, {"id": "ethnicity", "zh": "种族", "en": "Ethnicity", "pillar": "state", "desc": "种族定义了【角色】的主要外貌特征。", "desc_en": "Ethnicity is what defines the main physical features of a Character."}, {"id": "stability", "zh": "稳定度", "en": "Stability", "pillar": "state", "desc": "稳定度是衡量【国家】内部和平的标准。如果为负，那么它代表动荡，如果为正，那么它代表平静。随着时间推移，稳定度将趋向于0，除非有其他因素影响。发动【战争】是会降低国家稳定度的行动之一。", "desc_en": "The stability is a measure of the internal peace of a Country. If it is negative, then it represents turmoil, and if it is positive, tranquility. Over time, stability will tend towards 0, unless other factors impact it. Starting Wars is one of the actions that will reduce the stability of a country."}, {"id": "stability_investment", "zh": "稳定度投资", "en": "Stability Investment", "pillar": "state", "desc": "花费部分【结余】在【稳定度】上是三种提升稳定度的主要方式中的一种，其他方式是使用【内阁行动】或有足够的【主导宗教】教士阶层。", "desc_en": "Spending part of the Balance on Stability is one of three main ways to increase stability, the others involve using a Cabinet Actions on it or having enough clergy estate of the Primary Religion."}, {"id": "legislative_efficiency", "zh": "立法效率", "en": "Legislative Efficiency", "pillar": "state", "desc": "这影响一个【国家】能够多么迅速地施行【法律】、【政府改革】和【阶层特权】。", "desc_en": "This impacts how quickly a Country can implement Laws, Government Reforms, and Estate Privileges."}, {"id": "pretender_rebels", "zh": "篡位者叛军", "en": "Pretender Rebels", "pillar": "state", "desc": "叛军是尝试【叛乱】的异【文化】或【宗教】的【人群】，或试图发动【内战】的不满【阶层】。", "desc_en": "Rebels is a faction that are either Pops of another Culture or Religion that is attempting a Revolt or an unhappy Estate that is trying to force a Civil War."}, {"id": "ruler", "zh": "统治者", "en": "Ruler", "pillar": "state", "desc": "每个【国家】都可能有一名【角色】担任其统治者。根据不同【政体】，他们可能终生统治，也可能在一段时间后被替换。统治者的【特质】会影响整个【国家】，其【行政能力】、【军事能力】和【外交能力】也直接影响【内阁】的效率。\n\n未来的统治者由【继承法】决定。如果没有合法【成年人】，【政府】则由【摄政】统治。", "desc_en": "Every Country may have a Character as its ruler. Depending on the Government Type they may rule for life, or for a set period of time, before being replaced. The Traits of a ruler affect the entire Country, and the Administrative Ability, Military Ability, and Diplomatic Ability have a direct impact on the efficiency of the Cabinet.\n\nFuture rulers are selected by the Succession Law. While there is no legitimate Adult, the Government is instead ruled by a Regent."}, {"id": "ruler_trait", "zh": "统治者特质", "en": "Ruler Trait", "pillar": "state", "desc": "统治者特质是只有当【角色】是【统治者】或【摄政】时才会生效的【特质】类型。\n\n一个角色在统治【国家】时最多可以获得3个统治者特质。", "desc_en": "A Ruler Trait is a type of Trait that is only active while a Character is either Ruler or Regent.\n\nA Character can earn up to three Ruler Traits while ruling a Country."}, {"id": "heir", "zh": "继承人", "en": "Heir", "pillar": "state", "desc": "当前【统治者】死亡或退位时，会继任【统治者】的【角色】。继承顺序由【政府】的【继承法】决定。\n\n如果发生继承，但却没有有效的继承人或者继承人是【儿童】时，则触发【摄政】。", "desc_en": "The Character who is next in line to be the Ruler when the current Ruler dies or abdicates. The order of succession is determined by the Succession Law of the Government.\n\nIf succession occurs, but there is no valid heir, or the heir is a Child, a Regency is triggered."}, {"id": "eligibility_rules", "zh": "继承人资格", "en": "Eligibility Rules", "pillar": "state", "desc": "【继承法】的继承人资格决定了什么【角色】有资格成为【国家】的【继承人】。", "desc_en": "The Eligibility Rules of a Succession Law determine which Characters are eligible to become Heir of a Country."}, {"id": "inheritance_contract", "zh": "继承契约", "en": "Inheritance Contract", "pillar": "state", "desc": "在欧洲，尤其是在【神圣罗马帝国】境内，统治者没有生下继承人时，订立合法的继承契约是很常见的做法。如果一名执政角色没有继承人，其会和另一人签订契约，约定在自己去世后，对方将继承这个国家，直到其生下合适的继承人为止。这类契约通常会以（大笔的）金钱作为交换。", "desc_en": "In Europe, especially inside the Holy Roman Empire, it was quite common to form legal Inheritance Contracts if a ruler had not sired an heir. If a ruling character has no heir, this ruler would make a contract with another that he will inherit the country upon his death until a suitable heir was sired. Usually in exchange for (vast amounts of) money."}, {"id": "heir_selection", "zh": "继承法", "en": "Succession Law", "pillar": "state", "desc": "每个【政府】都有一项继承法，决定了当前【统治者】死亡或退位后，哪个【角色】应该继任。\n\n许多继承法在继承发生前就根据【继承人分数】确定了【继承人】，而另一些则会进行【 选举】。\n\n不同继承法有不同的规则，比如继承人是否属于同一【宗族】，或者他们是否必须属于特定【阶层】。\n\n【国家】可以选择不同的继承法，可用选项受不同因素影响，例如当前【政体】和任意生效【政府改革】。", "desc_en": "Every Government has a Succession Law which defines which Character shall be the next Ruler once the current one dies or abdicates.\n\nMany Succession Laws define an Heir before the succession occurs based on the Heir Score of that character, while others trigger an Election.\n\nEach different Succession Law has its own rules, such as whether an heir may be of the same Dynasty, or if they must belong to specific Estates.\n\nA Country may select another Succession Law; the options available can be influenced by factors such as the current Government Type and any active Government Reforms."}, {"id": "maintenance", "zh": "维护费", "en": "Maintenance", "pillar": "state", "desc": "我们每月要为我们的【军团】支付【陆军维护费】，为我们的【舰船】支付【海军维护费】。", "desc_en": "Each month we will need to pay Army Maintenance for our Regiments and Navy Maintenance for our Ships."}, {"id": "role", "zh": "职责", "en": "Role", "pillar": "state", "desc": "职责是【成年人】【角色】在【国家】内扮演的不同位置。角色的【能力】将根据职责产生不同的效果，并且他们可以获得不同的【特质】。\n\n通常一个角色只能同时履行一个职责，但有时【统治者】和【摄政】也可以作为【陆军将领】或【海军将领】。", "desc_en": "Roles are different positions that an Adult Character may fulfill in a Country. The Abilities of a Character will have different effects depending on their Role, and they will be able to earn different Traits.\n\nNormally a Character may only perform one Role at a time, but sometimes Rulers and Regents can act as Generals or Admirals."}, {"id": "cobelligerent", "zh": "联合作战国", "en": "Co-belligerent", "pillar": "state", "desc": "一个以联合作战国身份卷入【战争】的【国家】将能够召唤它自己的【同盟】加入【战争】。\n\n在【和平条约】中向联合作战国提出割让【地点】的战争分数花费与战争领袖【国家】相同。", "desc_en": "A Country that is called into a War as a Co-belligerent will be able to call its own Allies into the War.\n\nTaking Locations from a Co-belligerent Country in a Peace Treaty will have the same cost as the war leader's."}, {"id": "ability", "zh": "能力", "en": "Ability", "pillar": "state", "desc": "能力代表每个【角色】的不同资质。每种能力的数值从0到100不等。新生儿的能力从0开始，随着成长逐渐提高。\n\n有三种类型的能力：\n——【行政】\n——【外交】\n——【军事】\n\n它们相加后就是【角色】的【总能力】。", "desc_en": "Ability represents the different aptitudes of each Character. The values of each range from 0 to 100. Newborn children start at 0 and gradually increase their Abilities as they grow up.\n\nThere are three types of Ability:\n - Administrative\n - Diplomatic\n - Military\n\nAdded together, they constitute the Character's Total Ability."}, {"id": "crew_size", "zh": "船员规模", "en": "Crew Size", "pillar": "state", "desc": "这决定了一艘【舰船】需要多少【水手】才能使用。", "desc_en": "This determines how many Sailors are required for the Ship to be operational."}, {"id": "artist_trait", "zh": "艺术家特质", "en": "Artist Trait", "pillar": "state", "desc": "艺术家特质是只有当【角色】是【艺术家】时才会生效的【特质】类型。\n\n任何艺术家作为游戏中的角色被创建出来的时候，都会自带特质。", "desc_en": "An Artist Trait is a type of Trait that is only active while a Character is an Artist.\n\nEvery Artist has its trait assigned when they are created as a Character."}, {"id": "heroes", "zh": "英雄", "en": "Heroes", "pillar": "state", "desc": "在采纳英雄崇拜信条的希腊多神教【宗教】中，事迹拥有非凡神圣性的【角色】会被视为英雄。成为英雄的过程被称为封圣。", "desc_en": "A Hero is a Character that is recognized in a hellenistic Religion following the Heroic Cults aspect by having an extraordinary degree of holiness through their deeds. The process to become a Hero is known as canonization."}, {"id": "action", "zh": "行动", "en": "Action", "pillar": "state", "desc": "行动是在游戏世界内引发【效果】的按钮。通常以【国家互动】、【局势行动】或【单位能力】的形式展现。", "desc_en": "An action is a button which causes an Effect in the game world. Such actions are usually in the form of Country Interactions, Situation Actions or Unit Abilities."}, {"id": "circle_satisfaction", "zh": "行政圈满意度", "en": "Circle Satisfaction", "pillar": "state", "desc": "【帝国行政圈】成员对【行政圈领袖】的满意程度。较高的满意度会奖励【行政圈领袖】【威望】和【外交声誉】。", "desc_en": "A measure of how content the members of an Imperial Circle are with their Circle Leader. Higher satisfaction rewards the Circle Leader with Prestige and Diplomatic Reputation."}, {"id": "circle_leader", "zh": "行政圈领袖", "en": "Circle Leader", "pillar": "state", "desc": "被指定为【帝国行政圈】领袖的国家。【行政圈领袖】可以充当【帝国行政圈】成员国与【皇帝】的中间人。", "desc_en": "The country which has been designated as as the leader of a Imperial Circle. The Circle Leader acts as an intermediary between the members of their Imperial Circle and the Emperor."}, {"id": "adm", "zh": "行政能力", "en": "Administrative Ability", "pillar": "state", "desc": "该【能力】代表【角色】有多善于处理行政任务，有多善于组织事务，掌控经济，以及维持国家运行。", "desc_en": "This Ability represents how good a Character is at handling administrative tasks, how good they are at organizing things, handling the economy, and making a country run."}, {"id": "decaying_modifier", "zh": "衰减修正", "en": "Decaying Modifier", "pillar": "state", "desc": "衰减修正与常规【修正】类似，但其效果会逐渐衰减。它会产生随时间衰退的临时变化。", "desc_en": "Decaying Modifiers are like regular Modifiers, but their effects gradually weaken as they near their expiration date. This creates temporary changes that fade over time."}, {"id": "character", "zh": "角色", "en": "Character", "pillar": "state", "desc": "角色是具有【能力】、【特质】、【文化】和【宗教】的单独【个人】。如果出身高贵，甚至可能属于一个【宗族】。\n\n一旦变为【成年人】，他们可以成为【统治者】或【摄政】，任职于【内阁】，或担任【陆军将领】或【海军将领】。\n\n【成年人】也可以【结婚】并生育【子女】。", "desc_en": "A Character is an individual Person possessing Abilities, Traits, Culture, and Religion. They may even belong to a Dynasty if they are of noble bearing.\n\nOnce they become an Adult, they may be a Ruler or Regent, or may be assigned a role in Cabinet, or as a General or Admiral.\n\nAdults may also Marry and produce Children."}, {"id": "character_interaction", "zh": "角色互动", "en": "Character Interaction", "pillar": "state", "desc": "这些是我们可以对一个【角色】进行的【行动】。例如与贵族结婚、切腹自尽或辞去大团长之职", "desc_en": "These are the Actions we can do with a Character. Examples include Marry a Noble, seppuku, or resign as grand master"}, {"id": "character_modifier", "zh": "角色修正", "en": "Character Modifier", "pillar": "state", "desc": "作用于【角色】的【修正】。只有当角色是国家的【统治者】时，修正才会对【国家】生效。", "desc_en": "A Modifier that applies to the Character. Modifier types which are supposed to target the Country are only active if the character is the Ruler of that country."}, {"id": "betrothal", "zh": "订婚", "en": "Betrothal", "pillar": "state", "desc": "订婚是两个来自不同【国家】的【角色】之间正式承诺将在日后【婚姻】的约定。当两个【角色】都达到适婚年龄后，订婚会自动转化为【王室联姻】。", "desc_en": "A betrothal is a formal pledge between two Characters from two different Countries to marry at a later date. When both Characters become eligible for Marriage, the betrothal is automatically converted into a Royal Marriage."}, {"id": "parliament", "zh": "议会", "en": "Parliament", "pillar": "state", "desc": "一个【国家】能够召集各【阶层】召开议会，以解决可能存在的任何【议会议案】，同时也可以趁此机会制造【宣战理由】、提高【赋税】、扩大【陆军征召兵】和【海军征召兵】规模或更改当前【法律】。我们需要解决任意【阶层】的【议会议程】以换取他们的支持。\n\n除【首都】之外，议会也可在拥有一定【邻近度】，且为城镇或【省会】的其他【地点】召开，议会会址将获得少量奖励。如果该【地点】被【占领】，则议会自动失败。\n\n神圣罗马帝国等【国际组织】也能召开组织内部的议会。然而，议会系统取决于组织的类型，因为有些组织需要特定【特殊地位】的【成员】使用其【特殊地位权能】予以支持才能通过。", "desc_en": "A Country can call its Estates into a session of Parliament, to solve any Parliament Issue they may have, while also giving the opportunities to create a Casus Belli, raise Taxes, increase Army Levies and Naval Levies, or change any of the current Laws. Any Estate may have a Parliament Agenda to resolve before they will pledge their support.\n\nParliament may take place in the Capital or another Location, as long as it's a city, town, or Province Capital, and has more than one Proximity, which receives some small benefits. If the Location becomes Occupied, the Parliament will fail.\n\nInternational Organizations such as the Holy Roman Empire can have a Parliament, too. However, the parliament system depends on the type of Organization as some require the support of Members of a specific Special Status and their Special Status Power to pass."}, {"id": "parliament_seat", "zh": "议会会址", "en": "Parliament Seat", "pillar": "state", "desc": "这是一个【国家】或一个【国际组织】召开【议会】的【地点】。", "desc_en": "This is the Location where the Parliament of a Country or of an International Organization takes place."}, {"id": "parliament_type", "zh": "议会类型", "en": "Parliament Type", "pillar": "state", "desc": "【议会】包含不同的【议会类型】。这影响了议会的运作方式。\n\n包括议会制、贵族议会、三级会议等政体专属议会形式", "desc_en": "A Parliament can be a different Parliament Type. This affects how the parliament functions.\n\nMonarchy / Estate / Noble Parliament types"}, {"id": "parliament_requests", "zh": "议会要求", "en": "Parliament Requests", "pillar": "state", "desc": "这些是【国家】可以花【议会支持度】来完成的行动。", "desc_en": "These are actions that a Country can spend Parliament Support on to get through."}, {"id": "parliament_request", "zh": "议会要求", "en": "Parliament Request", "pillar": "state", "desc": "这是一个【国家】可以花费【议会支持度】来得到通过的行动。", "desc_en": "This is an action that a Country can spend Parliament Support on to get through."}, {"id": "parliament_issue", "zh": "议会议案", "en": "Parliament Issue", "pillar": "state", "desc": "这是一个需要花费长时间进行争论的事项，并交由【议会】召集各【阶层】予以表决。如果未能通过，【国家】将因此遭受损失。\n\n对于一个【国际组织】，这些议案将交由具有【特殊地位】的【成员】进行协商讨论决定。", "desc_en": "This is something that has been under debate for a while, and will need to be resolved in Parliament by the Estates or the Country will become weaker.\n\nFor International Organizations, these debates need to be negotiated with the powerful Members with a Special Status."}, {"id": "parliament_agenda", "zh": "议会议程", "en": "Parliament Agenda", "pillar": "state", "desc": "在任何【阶层】宣布对我们予以支持之前，我们要首先解决议会议程。这么做对【国家】来说有可能代价高昂，且该阶层提供的支持程度取决于它们的【阶层力量】。\n\n在【国际组织】召开的议会中，拥有【特殊地位】的【成员】将提出他们自己的议会议程。如果完成了这些事项，他们或将使用【特殊地位权能】对我们保障支持。", "desc_en": "Any Estate may have a Parliament Agenda to resolve before they will pledge their support. This may be costly for the Country, as the support given relies on the Estate Power the estate has.\n\nIn the context of International Organizations, the Members of a Special Status will instead present their Parliament Agenda. Accepting those may either give their guaranteed support in form of their Special Status Power."}, {"id": "language_family", "zh": "语族", "en": "Language Family", "pillar": "state", "desc": "源自同种原始语言的数种【语言】被划归为同一个语族，它们之间可能有许多相似之处。\n\n一些【语言】不属于任何【语族】，因此会被视为【孤立语言】。", "desc_en": "A Language Family is a set of Languages that have descended from a common ancestor and therefore may share a lot of similarities.\n\nSome Languages do not belong to a Family and are therefore Isolated Language."}, {"id": "nobles_estate", "zh": "贵族", "en": "Nobility", "pillar": "state", "desc": "这一阶层代表着我国的世袭贵族。其特权由古老的传统保障，大多数是他们的祖先最初通过对国家的卓越服务而授予的。他们的传统职责是保卫王国抵御外来危险，并帮助统治者维持和平。\n总体而言，让王室拥有比其他阶层更多的权力是更为有利的。", "desc_en": "This estate represents our landed aristocracy. Their privileges are guaranteed by ancient traditions, most of which were originally granted in return for exceptional service to the state. They are traditionally responsible for protecting the realm against outside dangers as well as helping the ruler keep the peace.\nIn general, it is better for the Crown estate to have more power than the other estates."}, {"id": "lender", "zh": "贷方", "en": "Lender", "pillar": "state", "desc": "贷方或者是出借【杜卡特】赚取【利息】的银行，或者是出借贷款的另一【国家】。", "desc_en": "This is either a bank lending out Ducats to earn an Interest on it, or another Country that is lending it."}, {"id": "election", "zh": "选举", "en": "Election", "pillar": "state", "desc": "某些【继承法】可能需要一场选举来决定哪一位【角色】将成为下一任【统治者】。\n\n根据【继承法】的规则，选举可能会定期发生，或者在前任【统治者】去世时发生。\n\n如果没有【统治者】那么【政府】将暂时由【摄政】统治，直到选举结束。", "desc_en": "Some Succession Laws may require an election to decide which Character should be the next Ruler.\n\nDepending on the rules of the Succession Law, an election may occur at regular intervals, or upon the death of the previous Ruler.\n\nIf there is no Ruler, then the Government will temporarily be ruled by a Regency until the election concludes."}, {"id": "tribal_cohesion", "zh": "部落凝聚力", "en": "Tribal Cohesion", "pillar": "state", "desc": "部落凝聚力衡量了我们部落制下的成员在【宗教】和【文化】上的协调程度。低水平的部落凝聚力意味着部落制的治理形同散养禽畜，人人我行我素。为了维持部落制的运行稳定，我们应该保持高水平的部落凝聚力。", "desc_en": "Tribal Cohesion is a measure of how aligned the members of our tribe are in terms of Religion and Culture. At low levels, running the tribe will be like herding cats, with everyone wanting to do their own thing. This should be kept high for the tribe to be run smoothly."}, {"id": "unit_family", "zh": "部队族系", "en": "Unit Family", "pillar": "state", "desc": "某些 【单位类型】 属于一个族系，同一族系的所有成员共享同一个招募上限。将部队升级为同一族系中更新的成员永远不会额外占用名额，因此该上限限制的是你总共能够部署的数量，而非每种 【时代】 各自的数量。", "desc_en": "Some Unit Types belong to a family, and every member of a family shares a single recruitment limit. Upgrading a unit into a newer member of its own family never costs an extra slot, so the limit caps how many you may field in total rather than how many of each Age."}, {"id": "consort", "zh": "配偶", "en": "Consort", "pillar": "state", "desc": "配偶是与【统治者】【结婚】的【角色】。在某些政府类型中，他们可能会获得权力，但大多数情况下他们只能为产下【继承人】提供帮助。", "desc_en": "A Consort is a Character who is Married to a Ruler. In some forms of governments, they may get powers, but in most cases, they are there to help provide Heirs."}, {"id": "locked", "zh": "锁定", "en": "Locked", "pillar": "state", "desc": "被锁定的【陆军】或【海军】不能接受命令。你必须等到再次获得对该单位的操作权限后才能下达命令。", "desc_en": "An Army or Navy that has been locked can not be given orders. You have to wait until you get access to that unit again."}, {"id": "estate", "zh": "阶层", "en": "Estate", "pillar": "state", "desc": "阶层是country with icon内部的特定利益集团，其estate power with icon代表他们在政府内的政治力量，estate satisfaction with icon代表他们的需求得到了多少满足，而【阶层外交倾向】代表他们对其他国家的观感。\n\n阶层也可以拥有estate privileges with icon，即可被政府授予或剥夺的、提高其力量的特殊权利。相应地，【阶层】会为【国家】提供taxes with icon、army levies with icon和navy levies with icon。\n\n阶层从locations with icon获取tax base with icon，以及一部分【贸易】利润，他们使用财富建造buildings with icon和满足pop needs with icon。如果【阶层满意度】过低，就只会建造阶层建筑支持自己的【阶层力量】。\n\n每个character with icon都有所属阶层，获得cabinet with icon任命或【陆军】和【海军】指挥权时会提高阶层力量。一些【继承法】会限制【继承人】的阶层。", "desc_en": "Special interest groups within a country with icon, Estates have estate power with icon representing their political strength within government, estate satisfaction with icon representing how well their needs are fulfilled, an estate culture with icon and estate religion with icon inherited from their dominant Pops, and Estate Opinions of other Countries.\n\nEstates may also have estate privileges with icon, which are special rights that increase their power and can be granted or revoked by the government. In turn, Estates provide taxes with icon, army levies with icon, and navy levies with icon to their Country.\n\nEstates collect the tax base with icon from the locations with icon, as well as part of the profit of Trade, and they use that wealth to build buildings with icon and pay for pop needs with icon. If their Estate Satisfaction is low, they will only build estate buildings to support their own Estate Power.\n\nEach character with icon belongs to one of the Estates and increase its power when appointed to the cabinet with icon, or when commanding Armies and Navies. Some Succession Laws limit their Heirs to specific estates."}, {"id": "estate_power", "zh": "阶层力量", "en": "Estate Power", "pillar": "state", "desc": "阶层力量描述了【阶层】在【国家】内的权力。它在很大程度上取决于【阶层】下辖的【社会阶级】的【人口】规模，以及阶层所享有的【阶层特权】。\n\n一些【社会阶级】，如贵族，每【人群】拥有的阶层力量远高于奴隶。\n\n• 【阶层】力量的总和将削弱【国家】的【王室力量】。\n• 一处【地点】的人口规模、阶层力量和【社会阶级】决定了该地的【税基】如何分配。", "desc_en": "This is the power that an Estate has in a Country. It depends very much on the size of Population of the Social Classes that belong to the Estate, and what Estate Privileges they have been given.\n\nSome Social Classes like nobles get far more Estate Power per Pop than slaves do.\n\n• The total power of the Estates reduces the Crown Power of the Country.\n• The Tax Base of a Location is distributed depending on the size, Estate Power and Social Class of each pop there."}, {"id": "estate_rebels", "zh": "阶层叛军", "en": "Estate Rebels", "pillar": "state", "desc": "叛军是尝试【叛乱】的异【文化】或【宗教】的【人群】，或试图发动【内战】的不满【阶层】。", "desc_en": "Rebels is a faction that are either Pops of another Culture or Religion that is attempting a Revolt or an unhappy Estate that is trying to force a Civil War."}, {"id": "estate_opinion", "zh": "阶层外交倾向", "en": "Estate Opinion", "pillar": "state", "desc": "【国家】内的阶层对其他国家的看法，例如，是希望采取【敌对】行动还是要交好，而具体诉求都是为了满足阶层自身的需求。", "desc_en": "Estates in a Country will have opinions about other Countries, i.e. which to be Hostile against and which to befriend, all to further their own needs."}, {"id": "estate_religion", "zh": "阶层宗教", "en": "Estate Religion", "pillar": "state", "desc": "每个【阶层】都有一项优势阶层宗教，选自阶层【人群】中最具政治力量的【宗教】。\n\n阶层的【阶层满意度】和【阶层力量】受到【国家】对阶层宗教容忍的影响——【主导宗教】为【正统信仰容忍度】，同宗教组的【异端】信仰为【异端容忍度】，而异宗教组为【异教容忍度】。", "desc_en": "Each Estate has a dominant Estate Religion, picked from whichever Religion holds the most political weight among the estate's Pops.\n\nThe estate's Estate Satisfaction and Estate Power are modified based on the Country's tolerance of the estate's religion — Primary Religion Tolerance when it matches the Primary Religion, Tolerance of Heretics when it is a Heretic faith of the same group, and Tolerance of Heathens when it belongs to a different religion group."}, {"id": "estate_culture", "zh": "阶层文化", "en": "Estate Culture", "pillar": "state", "desc": "每个【阶层】都有一项优势阶层文化，依照【人群】在【国家】持有的政治力量加权。这些人群的优势【语言】会优先考虑，然后是讲该语言的人群的优势【文化】。\n\n文化为【主流文化】或【已接纳文化】的阶层拥有更高的【阶层满意度】和【阶层力量】。【相容文化】不变，其他文化两项都更低。", "desc_en": "Each Estate has a dominant Estate Culture, weighted by the Pops holding political weight in a Country. The dominant Language among those pops is picked first, and then the dominant Culture among pops who speak that language.\n\nAn estate whose culture is the Primary Culture or an Accepted Culture enjoys higher Estate Satisfaction and Estate Power. A Tolerated Culture is neutral, while any other culture lowers both."}, {"id": "estate_satisfaction", "zh": "阶层满意度", "en": "Estate Satisfaction", "pillar": "state", "desc": "该变量衡量了一个【阶层】对【国家】当前统治的满意程度。如果这一数值处于高水平，国家将获得奖励修正，反之将获得惩罚修正。如果这一数值过低，我们甚至无法从【阶层】中招募【陆军征召兵】和【海军征召兵】。\n\n阶层满意度也直接影响了【阶层】下辖【人群】的【人群满意度】。", "desc_en": "This is how happy the Estate is with how the Country is currently being ruled. If this is high, the country will get some bonuses, but if it is low, it will give penalties, and if it is low enough, we will not be able to recruit Army Levies and Naval Levies from that Estate.\n\nThis also has a direct impact on the Pop Satisfaction of the Pops belong to this Estate."}, {"id": "estate_privilege", "zh": "阶层特权", "en": "Estate Privilege", "pillar": "state", "desc": "【统治者】有时可向特定群体授予某些特权。这通常体现为税收减免、经营垄断等能为特定【阶层】带来优势的权利。授予特权往往需要付出某种代价，通常包括王室力量的削弱、【阶层】力量的增强，以及额外的负面效果。", "desc_en": "The Ruler can at times grant certain privileges to certain groups of people. These might be tax breaks, monopolies, or other rights that bestow an advantage to that particular Estate. They generally come at some cost to the crown, be that in the power of the Estate or some other cost."}, {"id": "estate_interactions", "zh": "阶层直接互动与绝境行动", "en": "Estate Interactions & Emergency Actions", "pillar": "state", "desc": "在阶层面板可直接执行的主动行动，分为常规互动（贿赂阶层、削减阶层力量强拆建筑、向阶层出售艺术品、征用私兵）与绝境行动（要求扩大征召、征收特别税、召开紧急议会及五大阶层专属求助如向市民无息紧急拨款）。处于防御性战争时，绝境行动消耗与满意度惩罚全部减半。", "desc_en": "Direct actions performed on estates including Bribe Estate, Perform Reduction, Sell Work of Art, Press Private Regiments, and Emergency Actions (costs & satisfaction hits halved in defensive wars)."}, {"id": "estates_enrichment", "zh": "阶层结余", "en": "Estates Enrichment", "pillar": "state", "desc": "这是一个【阶层】每月可以从其可征税收入中保留的金额。", "desc_en": "This is how much an Estate can withhold from their taxable income each month."}, {"id": "general", "zh": "陆军将领", "en": "General", "pillar": "state", "desc": "这是被委任领导【陆军】的【角色】。", "desc_en": "This is a Character that has been assigned the role of leading an Army."}, {"id": "general_trait", "zh": "陆军将领特质", "en": "General Trait", "pillar": "state", "desc": "陆军将领特质是只有当【角色】是【陆军将领】时才会生效的【特质】类型。\n\n一个角色在陆地【战斗】时最多可以获得一个陆军将领特质。", "desc_en": "A General Trait is a type of Trait that is only active while a Character is a General.\n\nA Character can earn up to one General Trait while fighting land Battles."}, {"id": "demote", "zh": "降级", "en": "Demote", "pillar": "state", "desc": "当所处【地点】的同【社会阶级】数量过多时，【人群】将降级为平民。", "desc_en": "Pops will demote to peasants when there are too many of their current Social Class in their Location."}, {"id": "leader_change_method", "zh": "领袖更换方式", "en": "Leader Change Method", "pillar": "state", "desc": "这决定了一个【国际组织】如何选出【领袖】。有以下五种方式：\n——轮替：现任领袖在任期结束后将排在领袖轮替序列的最后一位\n——投票：领袖将通过【领袖选举决议】选举产生\n——抽签：领袖将在候选国中随机产生\n——分数：领袖将根据国际组织内部的特定评分系统动态选择\n——未定：领袖决定机制空缺，这是由于该国际组织没有领袖或暂时无法产生领袖", "desc_en": "This determines how the Leader of an International Organization gets chosen. There are five methods to accomplish this:\n- Rotation - The current leader will be the last in line for leadership once their turn is up\n- Vote - The leader will be elected via a Leadership Election Resolution\n- Lottery - The leader will be chosen from possible candidates at random\n- Score - The leader will be chosen dynamically based on an internal point system specific to the International Organization\n- Undefined - The terms of how a leader for the International Organization is chosen are not defined, as no leader is needed or the International Organization has not codified the leadership yet"}, {"id": "leader_change_trigger", "zh": "领袖更换条件", "en": "Leader Change Trigger", "pillar": "state", "desc": "这决定了一个【国际组织】在什么条件下需要重新决定【领袖】。有以下三种条件：\n——统治者更换时：当领袖国统治者变更时须重新决定国际组织的新领袖\n——有任期：在经过特定月数后须重新决定国际组织新领袖\n——无限期：领袖永久留任", "desc_en": "This determines under what conditions the Leader of an International Organization gets changed. There are three triggers when the leader could change:\n- On Ruler Change - Whenever the ruler changes, a new leader for the International Organization is considered\n- Timed - A new leader of the International Organization is considered after a set amount of months\n- Indefinite - The leader remains in power indefinitely"}, {"id": "leader_type", "zh": "领袖类型", "en": "Leader Type", "pillar": "state", "desc": "这决定了一个【国际组织】的【领袖】是以什么形式领导国际组织。国际组织的领袖类型分以下三种：\n——角色：国际组织由某位【角色】及其所属国家来领导\n——国家：国际组织由某一特定【国家】领导，因此不考虑该国【统治者】变更的情况\n——无领袖：国际组织的领袖处于永久性空缺，任何角色或国家都不能代表该组织", "desc_en": "This determines who actually is the Leader of an International Organization. There are three types of leadership for International Organizations:\n- Character - The organization is led by a Character and the country it belongs to\n- Country - The organization is led by determined Country which is in charge even if its own Ruler gets replaced\n- Leaderless - The organization is in a perpetual state of an interregnum and neither character nor country will represent the organization"}, {"id": "capital", "zh": "首都", "en": "Capital", "pillar": "state", "desc": "这是【国家】的政治中心所在【地点】，【政府】就设在这里。在【战争】中被【占领】可能会造成灾难性后果。", "desc_en": "This is the Location that is at the political center of a Country, where the Government resides. Getting it Occupied in a War can be devastating."}, {"id": "impassable", "zh": "不可通行", "en": "Impassable", "pillar": "territory", "desc": "这是一处【单位】无法进入的【地点】或【海域】，也无法维持可观规模的人口长期居住。", "desc_en": "This is a Location or a Seazone that can not be entered by Units, nor can anyone live there in any sustainable numbers."}, {"id": "rural_location", "zh": "乡村", "en": "Rural Location", "pillar": "territory", "desc": "相对于【城镇】，乡村是不存在重要定居点的【地点】，几乎无法建造进阶【建筑】。", "desc_en": "A Location without a significant settlement, and therefore fewer opportunities to build special Buildings. It is the opposite of Urban Location."}, {"id": "self_control", "zh": "克己", "en": "Self Control", "pillar": "territory", "desc": "克己反映了一个【国家】和它的【统治者】如何通过舍弃享乐和物质财富，修习瑜伽正法。\n\n克己为正意味着他们倾向于断情绝欲，赋予【稳定度】、【迁徙】、【吞并】增益，并降低【食物】消费，而克己为负意味着他们倾向于放纵堕落，提高【赋税】和【食物】消费但会减少【厌战度】。克己均衡给予【研究】速度、【威望】和【阶层满意度】。", "desc_en": "Self Control is a measure of how a Country and its Ruler are renouncing pleasures and material possessions, and how they follow the path of Yoga.\n\nHaving a positive value of Self Control will mean that they tend to asceticism, giving benefits to Stability, Migration, Annexation, and reduced Daily Food Consumption, while having a negative Self Control means that they are tending towards depravity, giving increased Tax and Daily Food Consumption but reduced War Exhaustion. Having Self Control balanced gives in turn better Research speed, Prestige, and Estate Satisfaction."}, {"id": "union_integration_level", "zh": "共主邦联整合等级", "en": "Union Integration Level", "pillar": "territory", "desc": "共主邦联整合等级描述了一个【共主邦联】通过实施【法律】与【政策】所推进的集中化程度。每推进一项集中化政策，邦联内当前所有【成员】的集中化程度都会向前一级。在通过最终的集中化政策时，共主邦联内所有与联统主导国等级相同的被联统国将被整合。\n\n晚于整体集中化进度加入共主邦联的成员单独计算集中化等级，且需要通过【议会】追赶整体进度以实现整合。", "desc_en": "The Union Integration Level describes how centralized the Personal Union is through Laws and Policies. Every Member which is present when a centralizing policy is implemented gets its level increased. With the final centralization policy, all Junior Partners which have the same level as the Union get unified by the Senior Partner.\n\nMembers which join the Union later need to catch up their progress to be integrated via the Parliament."}, {"id": "inland", "zh": "内陆", "en": "Inland", "pillar": "territory", "desc": "内陆是不与【海域】相邻的【地点】，因此不会有【港口】，也不能建造【舰船】。\n\n与内陆地点相对的是【沿海】地点。", "desc_en": "A Location that is inland is not in contact with a Seazone, so it will not have a Port and will not be able to build Ships.\n\nThe opposite of an inland Location is a Coastal Location."}, {"id": "winter", "zh": "冬季", "en": "Winter", "pillar": "territory", "desc": "冬季会对【地点】产生负面影响。冬季发生的方式随机，但其寒冷程度，或者说【冬季等级】，受【气候】影响。\n\n冬季来临的月份取决于【地点】的【半球】。", "desc_en": "Winter affects Locations in negative ways. The way each winter happens is random, but its severity, or Winter Level, is influenced by the Climate.\n\nThe months that winter falls in depend on the Hemisphere of the Location."}, {"id": "winter_level", "zh": "冬季等级", "en": "Winter Level", "pillar": "territory", "desc": "冬季等级是一个【地点】【冬季】的严重程度。较严重的【冬季】会使【建造】暂停，甚至【封冻】一些较浅的【海域】。\n\n【陆军】在正常或严酷的【冬季】无法进入拥有山地【地形】的【地点】。\n\n一个【地点】能经历的最高冬季等级取决于当地【气候】。\n\n冬季等级包括以下：\n——无冬\n——轻冬\n——常冬\n——严冬", "desc_en": "Winter Level is the severity of Winter in a Location. Harsher Winter will halt Constructions and even Freeze Over some shallow Seazones.\n\nArmies are unable to move into Locations with mountains Topography during Normal or Severe Winter.\n\nArmies sheltered in a friendly Fort or within its Zone of Control do not suffer winter Attrition. This shelter extends to forts owned by your direct Subjects and to your direct Overlord.\n\nThe maximum Winter Level that a Location can experience is dependent on the local Climate.\n\nThe Winter Levels are as follows:\n- winter none\n- winter mild\n- winter normal\n- winter severe"}, {"id": "export", "zh": "出口", "en": "Export", "pillar": "territory", "desc": "出口是将【商品】转移出某一【市场】，从而增加【市场】对该商品【需求】的【贸易】活动。\n\n如果有多项贸易尝试出口同一商品，商品将按照【贸易优势】交付。", "desc_en": "An Export is a Trade moving Goods out from a Market, and thus increasing its Demand in that Market.\n\nIf there are multiple trades trying to export the same goods, then the goods are given in order of Trade Advantage."}, {"id": "export_tariff", "zh": "出口关税", "en": "Export Tariff", "pillar": "territory", "desc": "出口关税是你对离开你的【市场】运往境外目的地的【商品】收取的费用。它增加了你的商人在这类路线上的【贸易支出】，减少了对外出口，但每月产生【杜卡特】收入。目的地国家会对被征收出口关税感到不满。\n\n可以在贸易政策界面设定每种【商品】的出口关税比率。", "desc_en": "An export tariff is a fee you charge on Goods leaving your Markets for foreign destinations. It increases the Trade Expense for your own merchants on those routes, reducing outbound trade but generating Ducats income each month. Destination countries will resent being charged export tariffs.\n\nExport tariff rates are set per Good in the Trade Policies view."}, {"id": "export_market", "zh": "出口市场", "en": "Export Market", "pillar": "territory", "desc": "这是进行【出口】活动的【市场】，【商品】通过贸易流出。", "desc_en": "This is the Market where the Goods of a trade are bought, creating an Export."}, {"id": "export_efficiency", "zh": "出口效率", "en": "Export Efficiency", "pillar": "territory", "desc": "这直接影响了向境外【市场】出口【商品】的价格，进而影响了出售方的【贸易】利润。", "desc_en": "This modifies how profitable a Trade will be on the sell side, by directly impacting the price received when exporting Goods to a foreign Market."}, {"id": "export_subvention", "zh": "出口补贴", "en": "Export Subvention", "pillar": "territory", "desc": "出口补贴降低了特定【商品】离开你的【市场】销往国外的【贸易支出】。这提高了你的商人从出口贸易获取的利润，但每月需消耗国库【杜卡特】。目的地国家将因廉价商品而受益。\n\n可以在贸易政策界面设定每种【商品】的出口补贴比率。", "desc_en": "An export subvention reduces the Trade Expense on Goods leaving your Markets for foreign destinations. This makes outbound trade more profitable for your merchants, at a monthly Ducats cost to your treasury. Destination countries will appreciate the cheaper goods.\n\nExport subvention rates are set per Good in the Trade Policies view."}, {"id": "score", "zh": "分数", "en": "Score", "pillar": "territory", "desc": "这是用于跟踪【国家】表现如何的度量。每个国家按【行政】、【外交】和【军事】表现进行排名，并按排名获得分数。\n较大国家也可以通过持有【胜利卡】获得分数，每个【时代】可以获得一张。", "desc_en": "This is a way to track how well a Country is performing. Each country is ranked in Administrative, Diplomatic, and Military performance, and gain score out of their rank there.\nLarger countries also gain score from holding Victory Cards which they get one each Age."}, {"id": "separatism", "zh": "分离主义", "en": "Separatism", "pillar": "territory", "desc": "非【主流文化】的【人群】居住于被征服尚未【整合】的【地点】时会拥有较低的【人群满意度】。", "desc_en": "Pops that are not of the Primary Culture will have a lower Pop Satisfaction when they live in a Location that has been conquered and not yet Integrated."}, {"id": "great_power_score", "zh": "列强分数", "en": "Great Power Score", "pillar": "territory", "desc": "列强分数是用来衡量当前最强【国家】的无可争议的指标。分数最高的国家被视为【列强】。列强总数取决于第一列强的分数与其余的对比。\n\n国家可以通过统治更多【人口】、拥有更高【威望】、提升【国家等级】和其他方式来提升分数。\n\n【附属国】会根据其【属国类型】的不同将分数按某一比例上缴给【宗主国】。", "desc_en": "Great Power Score is the indisputable measure of which Country is the best. The top highest scoring Countries are the Great Powers. The total number of Great Powers varies depending on the Score of the top Great Power compared with the rest.\n\nCountries earn Score by owning more Population, having higher Prestige, increasing Country Rank, and various other sources.\n\nSubjects also forfeit a certain percentage of their Score to their Overlord, depending on their Subject Type."}, {"id": "original_location_rank", "zh": "初始地点等级", "en": "Original Location Rank", "pillar": "territory", "desc": "每个【地点】在游戏开局时的【地点等级】。\n\n（详见速查典：original_location_rank）", "desc_en": "The Location Rank that each Location had at the start of the campaign.\n\n(See ledger: original_location_rank)"}, {"id": "region", "zh": "区域", "en": "Region", "pillar": "territory", "desc": "区域由一系列【地区】组成，并且是【次大陆】的一部分。斯堪的纳维亚区域就是一个典型的区域。", "desc_en": "A Region is a group of Areas that is part of a Subcontinent. scandinavian region would be an example of a Region."}, {"id": "regional_power", "zh": "区域强权", "en": "Regional Power", "pillar": "territory", "desc": "【区域强权】是累积了足够多的【列强点数】足以支配其所在区域，但尚未达到【列强】地位的【国家】。\n\n【区域强权】能获得【列强】的一半加成——更多【外交容量】、【外交官】、【力量投射】、【威望】和雇佣兵招募范围——但强制和平、干预战争和威胁开战等行动仅限对首都位于相邻【区域】的【国家】使用。", "desc_en": "A Regional Power is a Country that has accumulated enough Great Power Points to dominate its region but has not yet reached Great Power status.\n\nA Regional Power earns half the bonuses of a Great Power — extra Diplomatic Capacity, Diplomats, Power Projection, Prestige, and mercenary range — but its Enforce Peace, Intervene in Wars, and Threaten War anywhere in the world actions are limited to Countries whose capital lies in an adjacent Region."}, {"id": "hemisphere", "zh": "半球", "en": "Hemisphere", "pillar": "territory", "desc": "所有【地点】都位于两个半球之一：赤道以北或以南。\n\n半球主要决定了【冬季】发生的月份：北半球大致在一月，南半球大致在六月。", "desc_en": "Every Location lies in one of two Hemispheres: north or south of the equator.\n\nThe Hemisphere primarily determines the months in which Winter is likely to occur: around January in the Northern Hemisphere, and around June in the Southern Hemisphere."}, {"id": "development", "zh": "发展度", "en": "Development", "pillar": "territory", "desc": "发展度代表了土地的开发程度，以及生活在那里的【人群】对土地的使用程度。发展度越高，可以居住在那里的人就越多，可以利用的价值就越高。", "desc_en": "Development represents how cultivated the land is, and how much it is used by the Pops living there. The higher the development, the more people can live there, and the more it can be exploited."}, {"id": "holy_site_importance", "zh": "圣地重要性", "en": "Holy Site Importance", "pillar": "territory", "desc": "【圣地】的重要性影响其对【地点】或【拥有者】的增益。", "desc_en": "The Importance of a Holy Site scales any bonuses that apply in its Location or Owner."}, {"id": "area", "zh": "地区", "en": "Area", "pillar": "territory", "desc": "地区由一系列【省份】组成，并且是【区域】的一部分。", "desc_en": "An Area is a group of Provinces, and is part of a Region."}, {"id": "topography", "zh": "地形", "en": "Topography", "pillar": "territory", "desc": "地形表示一个【地点】内地面的平坦起伏和海拔高度。较平坦的地形更适合发展【城镇】，而崎岖的地形则更易于防御。", "desc_en": "Topography represents the roughness and elevation of the land within a Location. Flatter Topography is generally better for growing Urban Locations, while rougher Topography is easier to defend."}, {"id": "location", "zh": "地点", "en": "Location", "pillar": "territory", "desc": "地点是最小的陆地地块，总是属于某一个【省份】。一个地点的基本属性由【地形】、【植被】以及【气候】定义。地点也可能包含【河流】。\n\n每个地点都具有特定的【原材料】并由居住在当地的【人群】收集。地点内能够建造【建筑】并【雇佣】当地人群。大多数地点都是【乡村】，但可以升级成为【城镇】。\n\n地点可以被【国家】【拥有】和【控制】。在【战争】期间，【陆军】可在不同地点间移动以占领地点。", "desc_en": "The smallest unit of land, and part of a Province. Its base characteristics are defined by Topography, Vegetation, and Climate. It may also contain a River.\n\nEach Location has a Raw Good which can be gathered by Pops who live there. Buildings can be constructed in Locations and also Employ Pops. Most Locations are Rural, but they can also be granted Urban Location status.\n\nEach Location can be Owned and Controlled by Countries, and Armies can move between different Locations to conquer them when there is a War."}, {"id": "location_modifier", "zh": "地点修正", "en": "Location Modifier", "pillar": "territory", "desc": "作用于【地点】的【修正】。", "desc_en": "A Modifier that applies to a Location."}, {"id": "location_rank", "zh": "地点等级", "en": "Location Rank", "pillar": "territory", "desc": "每个【地点】都有等级，可以是【城镇】或【乡村】。\n\n（详见速查典：location_rank）", "desc_en": "Each Location has a rank, which can be described as an Urban Location or a Rural Location.\\n\\nThe color of the rank icon shows whether the Location is a capital.\n(See ledger: location_rank)\n\nProvince Capitals\n•  megalopolis\\n•  city\\n•  town\\n•  rural settlement\n\nCountry Capitals\n•  megalopolis\\n•  city\\n•  town\\n•  rural settlement"}, {"id": "location_importance", "zh": "地点重要性", "en": "Location Importance", "pillar": "territory", "desc": "这取决于多种因素，诸如【地点】的港口适宜性，【人口】规模，有多少连接的【道路】，建有多少【建筑】，是否为【首都】，是否有城堡，以及它的【市场接入度】。", "desc_en": "This is determined based on a multitude of factors such as the Location's harbor suitability, its Population size, how many Roads lead to it, how many Buildings it has, whether or not it is our Capital, if it has a castle, as well as its Market Access."}, {"id": "location_size", "zh": "地点面积", "en": "Location Size", "pillar": "territory", "desc": "一个【地点】的物理面积大小。并非每个地点的面积都相同。", "desc_en": "The physical size of a Location. Not every location is the same size."}, {"id": "town_and_city", "zh": "城镇", "en": "Urban Location", "pillar": "territory", "desc": "城镇是被认定为重要人类聚居区的【地点】。它们能够建造更为专业的【建筑】，并且能够容纳市民在此繁荣昌盛，被视为与【乡村】相对应的概念。\n\n根据【城镇】地点的规模，还可分为集镇和城市。", "desc_en": "This is a Location with a significant human settlement. It can contain more specialized Buildings, and allows for the flourishing of burghers. It is the opposite of a Rural Location.\n\nDepending on its size, an Urban Location can be a town, a city, or a megalopolis."}, {"id": "town_rights", "zh": "城镇特权", "en": "Urban Rights", "pillar": "territory", "desc": "城镇特权是【国家】可以授予【城镇】，影响【地点】和/或【国家】的特殊权利。\n\n一些【国家】开局即解锁了历史城镇特权，其中部分已于1337年授予。之后，从探索时代（III）开始，所有【国家】都可以研究advance icon城镇特权（探索时代革新）【革新】，从而解锁城镇特权，将【城镇】专门化，例如生产特定【商品】。\n\n默认情况下，集镇可以有1个城镇特权，城市可以有2个，大都市可以有3个，不过部分【政府改革】可以提升这些数值。", "desc_en": "Urban Rights are special privileges that a Country can grant to a Urban Location. These can impact the Location and/or the Country.\n\nSome Countries start with access to historical Urban Rights, and a number of them are granted from 1337. Later on, starting in the age 3 discovery, all Countries can research the advance icontown rights enable Advance, giving access to Urban Rights that allow for the specialization of Urban Locations in a particular purpose, like producing a specific Good.\n\nBy default, a town can have 1 Urban Right, a city can have 2, and a megalopolis can have 3, although some Government Reforms can increase these values."}, {"id": "continent", "zh": "大陆", "en": "Continent", "pillar": "territory", "desc": "世界分为数个大陆，这些大陆进一步细分为【次大陆】。", "desc_en": "The world is divided into a few continents, and these continents are then divided into Subcontinents."}, {"id": "natural_harbor_suitability", "zh": "天然港口区位度", "en": "Natural Harbor Suitability", "pillar": "territory", "desc": "用于评价在无进行任何人为改造之前，某一【地点】的自然条件有多适合船舶的停靠和人员、物资的装卸。该值可以降低港口【建筑】的建造花费，并改善【港口容量】。", "desc_en": "How well the Location naturally lends itself to the docking of ships and loading/unloading of men and material, before any man-made improvements. It makes port Buildings cheaper to construct, and improves Harbor Capacity."}, {"id": "frozen", "zh": "封冻", "en": "Frozen Over", "pillar": "territory", "desc": "封冻的【海域】可供【陆军】通行，并能对它所连接的土地实施更有效的控制；然而，【海军】在冰面解冻之前将搁浅。小心天气变化，如果海域在【陆军】冰上行军时解冻，将会产生灾难性后果。", "desc_en": "A frozen Seazone can be traversed by Armies and allows greater control over the lands it reaches; however, it will cause Navies to get stuck until it thaws. Be careful when the weather changes, it can thaw with catastrophic consequences if an Army is on the ice."}, {"id": "supported_building_levels", "zh": "建筑等级上限", "en": "Supported Building Levels", "pillar": "territory", "desc": "每处【地点】都有一项本地可容纳【建筑】等级的软上限。如果超过该上限，建造价格将逐步提高。\n\n建筑等级上限主要取决于该【地点】的【地点等级】和【发展度】。\n\n所有【建筑】等级都计入限制，包括建造中的建筑和缺少工人的建筑。外国拥有的【建筑】不计入。", "desc_en": "Every Location has a soft limit on the number of Building levels it can contain. Surpassing that limit will incur progressively higher construction prices.\n\nThe number of Supported Building Levels depends primarily on the Location Rank and the Development of the Location.\n\nAll Building levels count towards the limit, including those under construction and those without workers. Foreign-owned Buildings do not count."}, {"id": "conquer", "zh": "征服", "en": "Conquer", "pillar": "territory", "desc": "征服指的是【地点】的【拥有者】由一个【国家】转变为另一个。这通常是通过【战争】之后的【和平条约】，但也有其他的方式，例如，通过【外交】行动将【地点】出售给另一个国家。\n\n被征服且未整合的【地点】需要经过【整合】才能有效治理。", "desc_en": "This is when a Location is taken by force from one Country by another, usually through a Peace Treaty after a War. Peaceful transfers, such as selling Locations via Diplomacy, leave the Location better established than a conquest does.\n\nA Conquered Location needs to be Integrated in order to be governed effectively."}, {"id": "war_score", "zh": "战争分数", "en": "Warscore", "pillar": "territory", "desc": "战争分数是衡量一个【国家】在特定【战争】中表现如何的数值。【国家】可以通过赢得【战斗】，成功【围攻】【战争对手】【地点】、实现【战争目标】和建立【封锁】来提高其战争分数。", "desc_en": "Warscore is the value that indicates how well a Country is performing in a specific War. A Country can increase their warscore by winning Battles, managing to Siege War Enemy Locations, achieving the Wargoal, and establishing Blockades."}, {"id": "control", "zh": "控制力", "en": "Control", "pillar": "territory", "desc": "【地点】【拥有者】的控制力决定了该【地点】的可用【税基】、【陆军征召兵】和【海军征召兵】。它也会影响【升级】、【同化】和【皈依】的速度，以及产生的每月【人力】和【水手】。地点控制力会缓慢趋向于【最大控制力】，这意味着控制力高于上限时会缓慢降低，低于上限时会缓慢提高。\n\n有一些【建筑】可以增加最大控制力，但主要取决于它与【国家】【首都】的【邻近度】。【道路】或沿岸【海上存在】可以增加【邻近度】，提高【地点】的【最大控制力】。", "desc_en": "The control that the Owner of a Location has determines the Tax Base, Army Levies, and Naval Levies available in the Location. It also affects the speed of Assimilation and Conversion, as well as the amount of monthly Manpower and Sailors it gives. The Control of a Location will slowly change towards its Maximum Control, meaning Control will slowly decrease if it is above the Max, or slowly increase if it is below it.\n\nThere are some Buildings that increase Max control, but primarily it depends on the Proximity to the Capital of the Country. Tracing a route through Roads or Maritime Presence along our coasts increases the Proximity, increasing the Maximum Control of the Location."}, {"id": "zone_of_control", "zh": "控制区", "en": "Zone of Control", "pillar": "territory", "desc": "它代表了【防御工事】阻止【战争对手】【陆军】通过其毗邻【地点】的防御能力。入侵【陆军】位于【战争对手】【要塞】周围的【战争对手】【地点】时，必须先【围攻】【要塞】才能通行至毗邻该【要塞】的另一【地点】。", "desc_en": "It represents the defensive capabilities of a Fortification to block the movement of War Enemy Armies through the Locations adjacent to it. An invading Army standing on an War Enemy Location adjacent to an War Enemy Fort will have to Siege the Fort first before it can move past it to any other adjacent Location of that Fort.\n\nFriendly Zone of Control also shelters Armies from local Attrition sources, including Winter. This shelter extends to forts owned by your direct Subjects and to your direct Overlord."}, {"id": "controller", "zh": "控制者", "en": "Controller", "pillar": "territory", "desc": "当前能对一个【地点】行使事实权力的【国家】。\n\n通常来说，控制者与【拥有者】就是同一个国家，但在【战争】期间，如果【地点】被【占领】，其控制者可能变更为【战争对手】国家。", "desc_en": "The Country currently able to exercise de facto power over a Location.\n\nTypically, this is the Owner, but during a War this could become an War Enemy if the Location becomes Occupied."}, {"id": "supportrebels", "zh": "支持叛军", "en": "Support Rebels", "pillar": "territory", "desc": "这是一个【国家】向另一【国家】境内的【叛军】提供援助的一项外交行动，提供支持的国家希望【叛军】取得胜利后建立一个对该国友好的新政府。", "desc_en": "This is when a Country decides to offer assistance to a group of Rebels in a different Country, with the hope that if the Rebels are victorious then the new government in place will be friendly towards them."}, {"id": "integration", "zh": "整合", "en": "Integration", "pillar": "territory", "desc": "完成整合的【地点】已被真正纳入国土，因此比【未整合】【地点】更容易治理得多。\n\n【未整合】【地点】需要通过针对整个【省份】的【内阁行动】整合，其速度取决于多种因素，包括【地点】数量、【文化】或其【地点等级】。", "desc_en": "An Integrated Location has been properly incorporated into the State, and it is thus much easier to govern than a Conquered Location.\n\nConquered Locations need to be Integrated with a Cabinet Action that targets the whole Province, and whose speed depends on various factors including the number of Locations, their Culture, or their Location Rank."}, {"id": "integration_status", "zh": "整合状态", "en": "Integration Status", "pillar": "territory", "desc": "这代表一个【地点】在【拥有者】行政机构中的整合程度。拥有【主权】的所有【地点】都属于以下四种状态之一：\n\n• 【殖民地】\n• 【未整合】\n• 【已整合】\n• 【核心】\n\n【未整合】【地点】可以通过【内阁行动】进行【整合】，但成为【核心】需要【主流文化】或【已接纳文化】【人群】占到很大的比例。", "desc_en": "This represents how well a Location is incorporated into the administrative apparatus of its Owner. Every Owned Location falls into one of four different status:\n\n• Colonized\n• Conquered\n• Integrated\n• Core\n\nAny Conquered Location can be Integrated with a Cabinet Action, but reaching Core status requires a large proportion of Pops of the Primary Culture or any of the Accepted Cultures."}, {"id": "max_control", "zh": "最大控制力", "en": "Maximum Control", "pillar": "territory", "desc": "【地点】的【控制力】将缓慢趋向于其最大控制力。最大控制力的主要来源是【邻近度】，但【整合状态】和【人群满意度】也发挥着作用。\n\n地点的最大控制力可以通过在【省份】驻扎军队和提高省份控制力【内阁行动】暂时提高。", "desc_en": "The Control of a Location will slowly trend towards its Maximum Control. The main source of Maximum Control is Proximity, but the Integration Status and Pop Satisfaction also play a role.\n\nThe Maximum Control of a Location can be temporarily increased by stationing an Army in the Province, as well as with the increase control province Cabinet Action."}, {"id": "core", "zh": "核心", "en": "Core", "pillar": "territory", "desc": "属于【国家】核心的【地点】是该【国家】不可分割的一部分。\n如果【地点】在【战争】中被夺走，制造【宣战理由】尝试将其收复会更加容易。\n任何【拥有者】的【主流文化】或【已接纳文化】占当地主要文化的已【整合】【地点】会成为核心。", "desc_en": "A Location that is a Core of a Country is the integral part of that Country.\nIf that Location is ever lost in a War, it is easy to fabricate a Casus Belli to attempt to get it back.\nAny Integrated Location who has a majority of the Owner's Primary Culture or any Accepted Culture will become a Core.\nCores gained through Effects or those lost to other countries will disappear after 100 years if they do not have the correct Culture."}, {"id": "vegetation", "zh": "植被", "en": "Vegetation", "pillar": "territory", "desc": "植被代表了一个【地点】的植物覆盖。", "desc_en": "Vegetation represents the foliage cover of a Location."}, {"id": "sub_continent", "zh": "次大陆", "en": "Subcontinent", "pillar": "territory", "desc": "次大陆由一系列【区域】组成，并且是【大陆】的一部分。西欧或者印度就是一个典型的次大陆。", "desc_en": "A Subcontinent is a group of Regions that is part of a Continent. western europe or India are examples of a Subcontinent."}, {"id": "colonized", "zh": "殖民", "en": "Colonized", "pillar": "territory", "desc": "殖民地是当一个【国家】在一个【省份】中有【特许殖民地】并缓慢输送他们自己的【人口】以在当地成为新的主导时建立的。", "desc_en": "A colony is when a Country has a Colonial Charter in a Province that slowly sends their own Population there to become the new majority."}, {"id": "colonial_maintenance", "zh": "殖民地花费", "en": "Cost of Colonies", "pillar": "territory", "desc": "维持【特许殖民地】需要花费【杜卡特】派送船只、人口和物资。该定义即代表了此类花费。", "desc_en": "It costs Ducats to send ships, people, and supplies to maintain a Colonial Charter. This cost is represented here."}, {"id": "colonial_range", "zh": "殖民范围", "en": "Colonial Range", "pillar": "territory", "desc": "这简单地表示了我们可以【殖民】的最远距离。", "desc_en": "This is simply how far away we can Colonize."}, {"id": "colonial_migration", "zh": "殖民迁徙", "en": "Colonial Migration", "pillar": "territory", "desc": "【殖民迁徙】指的是【人群】从【核心】【地点】【迁徙】到【特许殖民地】。", "desc_en": "Colonial Migration is when Pops Migrate from the Core Locations to a Colonial Charter."}, {"id": "climate", "zh": "气候", "en": "Climate", "pillar": "territory", "desc": "一个【地点】的气候会影响居住在那里【人群】的生活质量，包括可以生产多少【食物】。它还会影响【地点】的最大【冬季等级】\\n\\n存在以下气候：\n（详见速查典：climate）", "desc_en": "The climate of a Location impacts how well Pops can live there, including how much Food can be produced. It also affects the maximum Winter Level of a Location.\\n\\nThe Climates below exist:\n(See ledger: climate)"}, {"id": "weather_system", "zh": "气象系统", "en": "Weather System", "pillar": "territory", "desc": "这些气象系统会给世界各地的【地点】带来大风、强降水和沙尘暴，偶尔也会造成严重的破坏。", "desc_en": "These are weather patterns that can bring high winds, rain, snow and sandstorms to Locations around the world, occasionally wreaking havoc."}, {"id": "river", "zh": "河流", "en": "River", "pillar": "territory", "desc": "河流是归属于【地点】的流动水体。\n\n河流无法容纳【海军】通航，跨河进入相邻【地点】作战的【陆军】会产生【渡水作战】战斗惩罚。另一方面，河流也能稍微提升该地点的【人口容量】。", "desc_en": "A Location may have a River, a moving body of water.\n\nRivers are not navigable by Navies, but they impose a Crossing combat malus on Armies who attempt to enter a Location with a River. Additionally, they slightly increase the Population Capacity of a location."}, {"id": "coastal", "zh": "沿海", "en": "Coastal", "pillar": "territory", "desc": "一个沿海【地点】与【海域】相连，因此会有一个【港口】；如果修建有诸如船埠或船坞【建筑】，就能建造【舰船】。", "desc_en": "A Location that is coastal is in contact with a Seazone, and as such will have a Port and will be able to build Ships if it has the appropriate Building, such as a wharf or a dock."}, {"id": "sea_current", "zh": "洋流", "en": "Sea Current", "pillar": "territory", "desc": "洋流是某些【海域】的特性，允许【海军】在特定方向上以更快的速度通行。", "desc_en": "A Sea Current is a particularity of certain Seazones that allows for faster movement of Navies in a specific direction."}, {"id": "seazone", "zh": "海域", "en": "Seazone", "pillar": "territory", "desc": "海域是【地点】在海洋地块中的近似概念。它是地图的一个分割区域，并不被任何实体【拥有】或【控制】。如果一个海域和陆地相邻，周边临近的【国家】也会产生【海上存在】。", "desc_en": "A seazone is similar to a Location except that it only contains water. It is a division of the map that is not Owned or Controlled by anyone. If a seazone is coastal, it will also have Maritime Presence from adjacent Countries."}, {"id": "strait", "zh": "海峡", "en": "Strait", "pillar": "territory", "desc": "海峡连接了被【海域】隔开的两个【地点】，但两个地点离得最够近，因此【陆军】不需要【海军】就能穿越。", "desc_en": "A Strait connects two Locations that are separated by a Seazone, but are close enough to each other so Armies can cross it without the need of a Navy."}, {"id": "port", "zh": "港口", "en": "Port", "pillar": "territory", "desc": "港口是可以建造和停泊【舰船】的沿海【地点】。", "desc_en": "A port is a land Location next to the sea which has the potential to build and moor Ships."}, {"id": "harbor_capacity", "zh": "港口容量", "en": "Harbor Capacity", "pillar": "territory", "desc": "港口容量降低了一处沿海地点进出港口时所需的【邻近度】和【贸易】范围成本。\n\n一处【地点】的港口容量主要由当地的【天然港口区位度】决定，同时可以通过改良港口相关【建筑】来进一步扩充其规模。", "desc_en": "Harbor Capacity reduces the cost of going from sea to land and vice versa in the Proximity and Trade calculations.\n\nThe Harbor Capacity of a Location depends mainly on its Natural Harbor Suitability, but many port-related Buildings can also increase it greatly."}, {"id": "lake", "zh": "湖泊", "en": "Lake", "pillar": "territory", "desc": "湖泊指的是内陆水体，除了可能有河流穿过，不与任何外海接触，因此没有相关的【舰船】可以在其中航行。", "desc_en": "Lakes represent inland bodies of water without any contact with the open sea except through possible rivers, so no Ships of relevance are able to sail in them."}, {"id": "colonial_charter", "zh": "特许殖民地", "en": "Colonial Charter", "pillar": "territory", "desc": "特许殖民地在【国家】想【殖民】整个【省份】时建立。\n特许殖民地将【迁徙】【人群】到该【省份】。当【地点】已经【完全定居】时，【地点】将被殖民者所【拥有】。", "desc_en": "A colonial charter is formed by a Country that wishes to Colonize an entire Province.\nThe Colonial Charter will Migrate Pops to the Province. When the Location is Fully Settled the Location will become Owned by the colonizer."}, {"id": "colonial_charter_goal", "zh": "特许殖民地目标", "en": "Colonial Charter Goal", "pillar": "territory", "desc": "为【特许殖民地】设定的目标，用于决定特许状完成后该【省份】的归属。", "desc_en": "The goal set for a Colonial Charter, determining what happens to the Province when the charter completes."}, {"id": "province", "zh": "省份", "en": "Province", "pillar": "territory", "desc": "省份由同一个【国家】【拥有】的一组【地点】构成。省份会向其所属地点共享和分配【食物】。【陆军征召兵】和【海军征召兵】也是同时在整个省份内动员。大部分【内阁行动】的作用对象都是一个省份。", "desc_en": "A province is a group of Locations Owned by the same Country. The province shares and distributes Food between its locations, and Army Levies and Naval Levies are raised from an entire province at once. Several Cabinet Actions target a province."}, {"id": "province_modifier", "zh": "省份修正", "en": "Province Modifier", "pillar": "territory", "desc": "作用于【省份】的【修正】。", "desc_en": "A Modifier that applies to a Province."}, {"id": "province_capital", "zh": "省会", "en": "Province Capital", "pillar": "territory", "desc": "省会是代表【省份】行政中心的【地点】。【省份】中人口最多或最发达的【地点】将自动被选为省会。当该【地点】在【战争】中被【占领】时，这一【省份】的其余【地点】将在短时间内被占领者自动控制。\n\n省会还决定了整个【省份】进行【食物】买卖的【市场】。", "desc_en": "The Province Capital is the Location that is the figurative heart of its Province. The most populated or developed Location in a Province will be automatically selected as the Province Capital, although it can be manually changed from the Location Panel. When this Location gets Occupied during a War, the remaining Locations of the Province fall automatically in the hands of the invader over a short period of time.\n\nThe Province Capital also determines the Market from which the whole Province buys and sells Food."}, {"id": "prosperity", "zh": "繁荣度", "en": "Prosperity", "pillar": "territory", "desc": "繁荣度代表一个【地点】的繁荣程度和资源丰富程度。处于正繁荣度的【地点】会随着时间的推移提高【发展度】，并使其更有可能吸引人口【迁徙】到此地。\n\n繁荣度会随着时间的推移自然增长，但会因【人群满意度】低下、【疫病】、受到【围攻】、【占领】、【封锁】或【地点】被敌方【陆军】【劫掠】而下降。负繁荣度可能对【地点】的【人口】造成毁灭性后果。", "desc_en": "Prosperity represents how prosperous and resourceful a Location is. Positive Prosperity increases the Development of the Location over time and makes it more likely to attract Migration.\n\nProsperity rises naturally over time, but will decrease as a result of low Pop Satisfaction, Diseases, Sieges, Occupation, Blockades, or if the Location is Looted by an enemy Army. Negative Prosperity can have devastating consequences for the Population of the Location."}, {"id": "economic_support", "zh": "经济支援", "en": "Economic Support", "pillar": "territory", "desc": "这种【条约】下，一个【国家】会每月支付【杜卡特】，支持另一【国家】的【财政】。这通常是因为一个国家不想直接参与【战争】，但仍想支持这一努力。", "desc_en": "This is a Treaty where one Country is sending Ducats each month to support the Finances of the other Country. This can often be the case when a country does not want to directly be involved in a War but still wants to support the effort."}, {"id": "heir_selection_score", "zh": "继承人分数", "en": "Heir Score", "pillar": "territory", "desc": "继承人分数衡量了一名【角色】在某个【国家】的【继承法】中受推崇的程度。通常，继承人分数最高的角色将在继承发生时成为新任【统治者】。", "desc_en": "The Heir Score determines how much the Character is favored to be elected by the Succession Law of a Country. Usually, the character with the highest score becomes the new Ruler upon a succession."}, {"id": "parliament_base_support", "zh": "议会基础支持度", "en": "Parliament Base Support", "pillar": "territory", "desc": "这代表了【议会】开启时的初始【议会支持度】。它主要因【王室力量】增加，但【法律】，【政府改革】和【革新】也会影响它。", "desc_en": "This impacts the initial Parliament Support when a Parliament is called. It is increased mainly by Crown Power, but Laws, Government Reforms and Advances can also impact it."}, {"id": "parliament_support", "zh": "议会支持度", "en": "Parliament Support", "pillar": "territory", "desc": "该值代表了【议会】通过【议会议案】的意愿程度。当国家想要请求讨论某个特定【议会要求】时，也需要参考该值。", "desc_en": "This is a value which represents how willing the Parliament is in passing a Parliament Issue. It is also required for when the state wants to perform a specific Parliament Request."}, {"id": "corridor", "zh": "走廊", "en": "Corridor", "pillar": "territory", "desc": "走廊是无法居住或被任何【国家】【拥有】的特殊【地点】，但与【荒地】不同，【陆军】仍可以穿越走廊。", "desc_en": "Corridors are special Locations that cannot be inhabited or Owned by any Country, but, contrary to Wastelands, still can be traversed by Armies."}, {"id": "transport_capacity", "zh": "运输能力", "en": "Transport Capacity", "pillar": "territory", "desc": "运输能力简述了我们的【舰船】能搭载多少来自【军团】的【兵力】。", "desc_en": "Transport capacity simply describes how many men, or Strength, from Regiments we can get on our Ship."}, {"id": "import", "zh": "进口", "en": "Import", "pillar": "territory", "desc": "进口是将【商品】转移进入某一【市场】，从而增加【市场】内该商品【供给】的【贸易】活动。", "desc_en": "An Import is a Trade moving Goods into a Market, and thus increasing its Supply in that Market."}, {"id": "import_tariff", "zh": "进口关税", "en": "Import Tariff", "pillar": "territory", "desc": "进口关税是对通过【进口】进入你【市场】的特定【商品】征收的费用。它增加了外国商人将该商品带入时的【贸易支出】，使这些贸易路线利润降低，同时每月为国库带来额外【杜卡特】收入。\n\n可以在贸易政策界面设定每种【商品】的进口关税税率。", "desc_en": "An import tariff is a fee charged on Imports entering your Markets for a specific Good. It increases the Trade Expense for foreign merchants bringing that good in, making those routes less profitable, while generating extra Ducats for your treasury each month.\n\nImport tariff rates are set per Good in the Trade Policies view."}, {"id": "import_market", "zh": "进口市场", "en": "Import Market", "pillar": "territory", "desc": "这是进行【进口】活动的【市场】，【商品】通过贸易输入。", "desc_en": "This is the Market where the Goods of a trade are sold, creating an Import."}, {"id": "import_efficiency", "zh": "进口效率", "en": "Import Efficiency", "pillar": "territory", "desc": "这降低从境外【市场】进口【商品】的花费。", "desc_en": "This reduces the cost paid when importing Goods from a foreign Market."}, {"id": "import_subvention", "zh": "进口补贴", "en": "Import Subvention", "pillar": "territory", "desc": "进口补贴降低了特定【商品】进入你【市场】的【进口】的【贸易支出】。这使得这些路线对外国商人更具吸引力，从而以每月消耗国库【杜卡特】为代价，将更多【贸易】引入你的【市场】。\n\n可以在贸易政策界面设定每种【商品】的进口补贴比率。", "desc_en": "An import subvention reduces the Trade Expense on Imports entering your Markets for a specific Good. This makes those routes more attractive for foreign merchants, drawing more Trade into your Market at a monthly Ducats cost to your treasury.\n\nImport subvention rates are set per Good in the Trade Policies view."}, {"id": "road", "zh": "道路", "en": "Road", "pillar": "territory", "desc": "道路是一种连接两个【地点】的设施，它有利于【国家】提升对领土的【控制力】，促进【贸易】并允许【陆军】更快移动。", "desc_en": "A road is a built connection between two Locations. These make it easier for a Country to exert Control over its territory, make Trade easier, and allow Armies to march faster."}, {"id": "proximity", "zh": "邻近度", "en": "Proximity", "pillar": "territory", "desc": "邻近度是衡量一个location with icon与其【拥有者】的capital with icon之间距离远近的数值，也是决定本地最大control with icon的基础参数。\n\n对每个【国家】的【首都】而言，【邻近度】恒定为100%，并向所有相邻【地点】辐射、向外扩散，并赋予他们逐步衰减的【邻近度】。邻近度在两处【地点】之间总会出现不同程度的衰减，这被称为【邻近度】消耗。消耗的数额主要取决于【地点】的地理属性，并可通过建造基础设施有效改善。\n\n两处【地点】之间的【邻近度】消耗受到topography with icon和vegetation with icon的显著影响。在陆上地点，可以通过建造roads with icon、提高development with icon和提升陆权倾向societal value with icon偏移倾向来改善邻近度消耗。而隔海相望的【地点】可以通过改良harbor capacity with icon、提高maritime presence with icon和提升海权倾向【社会价值观】偏移倾向来改善邻近度消耗。", "desc_en": "The Proximity of a location with icon measures how close it is to the capital with icon of its Owner, and it determines how much control with icon Locations can have.\n\nProximity starts at 100% in the Capital of every Country, and jumps to nearby Locations, giving them Proximity. Some Proximity is lost with every subsequent jump, depending on the terrain and the infrastructure present in the Location. The Proximity that is lost in jumping from one Location to the next is called Proximity Cost.\n\nThe Proximity cost between Locations varies greatly with topography with icon and vegetation with icon. On land, it can be reduced by building roads with icon, increasing development with icon, and the land societal value with icon. On sea, it can be reduced by harbor capacity with icon, maritime presence with icon and the naval Societal Value."}, {"id": "province_definition", "zh": "预设省份", "en": "Province Definition", "pillar": "territory", "desc": "预设省份是一组预先设定的决定了游戏中【省份】构成的【地点】。\n\nareas with icon划分为省份，省份划分为locations with icon。同一省份定义的所有【地点】若由同一country with icon【拥有】则会属于同一【省份】。\n\n如果多个【国家】在同一省份定义【拥有】【地点】，则会出现多个【省份】，每个都拥有自己的province capital with icon和food stockpile with icon。", "desc_en": "A Province Definition is a predetermined group of Locations that determines how Provinces are created throughout the game.\n\nareas with icon are divided into Province Definitions, which in turn contain locations with icon. All Locations in the same Province Definition that are Owned by the same country with icon will belong to the same Province.\n\nIf multiple Countries Own Locations in the same Province Definition, there will be as many different Provinces, each with its own province capital with icon and food stockpile with icon."}];
